# ============================================================
MEMORY_SYMBOLES = ["🍥","🗡️","🏴‍☠️","⚔️","📓","👊","🐉","⚗️","🏐","💚",
                   "⛓️","🕵️","🧝","⚽","🌑","♟️","🧪","🎹","🪓","🕷️",
                   "🕯️","🪂","🦑","🦅","🍺","📼","👑","📻","🩺","🔥"]
active_memory = {}

class MemoryView(ui.View):
    """Grille de paires à retourner"""
    TAILLES = {"facile": (4, 3), "normal": (4, 4), "difficile": (5, 4)}

    def __init__(self, joueur, salon, niveau="normal", etat=None, timeout=300):
        super().__init__(timeout=timeout)
        self.joueur, self.salon, self.niveau = joueur, salon, niveau
        self.etat = etat or {}
        self.gagne = False
        cols, lignes = self.TAILLES[niveau]
        total = cols * lignes
        paires = random.sample(MEMORY_SYMBOLES, total // 2)
        self.cartes = paires * 2
        random.shuffle(self.cartes)
        self.cols = cols
        self.trouvees = set()
        self.retournees = []
        self.coups = 0
        self.debut = None
        self.message = None
        self.fini = False
        for i in range(total):
            btn = ui.Button(label="\u200b", emoji="🎴",
                            style=discord.ButtonStyle.secondary, row=i // cols)
            async def cb(interaction, idx=i):
                await self.retourner(interaction, idx)
            btn.callback = cb
            self.add_item(btn)

    def build(self, fin=None):
        restant = len(self.cartes) // 2 - len(self.trouvees) // 2
        NIV = {"facile": "🟢 Facile", "normal": "🟡 Normal", "difficile": "🔴 Difficile"}
        serie = self.etat.get("serie", 0)
        if fin:
            desc = fin
            col = 0x2ecc71
        else:
            desc = (f"Retrouve toutes les paires !\n\n"
                    f"🎴 Paires restantes : **{restant}**\n"
                    f"🔄 Coups joués : **{self.coups}**"
                    + (f"\n🔥 Série en cours : **{serie}**" if serie else ""))
            col = 0x9b59b6
        titre = f"🃏 Memory — Manche {self.etat.get('manche', 1)} · {NIV[self.niveau]}"
        e = discord.Embed(title=titre, description=desc, color=col)
        e.set_author(name=self.joueur.display_name, icon_url=self.joueur.display_avatar.url)
        if not fin:
            e.set_footer(text="Clique sur deux cartes pour les retourner")
        return e

    async def retourner(self, interaction, idx):
        if interaction.user.id != self.joueur.id:
            return await interaction.response.send_message("❌ C'est la partie de quelqu'un d'autre !", ephemeral=True)
        if self.fini or idx in self.trouvees or idx in self.retournees:
            return await interaction.response.defer()
        if len(self.retournees) >= 2:
            return await interaction.response.defer()

        import time as _t
        if self.debut is None:
            self.debut = _t.time()
        self.retournees.append(idx)
        self.children[idx].emoji = self.cartes[idx]
        self.children[idx].style = discord.ButtonStyle.primary

        if len(self.retournees) < 2:
            return await interaction.response.edit_message(embed=self.build(), view=self)

        self.coups += 1
        a, b = self.retournees
        await interaction.response.edit_message(embed=self.build(), view=self)

        if self.cartes[a] == self.cartes[b]:
            self.trouvees.update((a, b))
            self.retournees = []
            for i in (a, b):
                self.children[i].style = discord.ButtonStyle.success
                self.children[i].disabled = True
            if len(self.trouvees) == len(self.cartes):
                self.fini = True
                duree = int(_t.time() - self.debut)
                parfait = len(self.cartes) // 2
                bonus = max(0, (parfait * 2 - self.coups)) * 40
                base = {"facile": 250, "normal": 450, "difficile": 800}[self.niveau]
                gain = base + bonus
                uid = str(self.joueur.id)
                economy_data[uid]["coins"] += gain
                gazette_gain(uid, gain)
                xp_data[uid]["xp"] += 40
                check_coins_achievements(uid, self.salon)
                active_memory.pop(self.salon.id, None)
                for it in self.children:
                    it.disabled = True
                return await interaction.message.edit(embed=self.build(
                    f"🎉 **Toutes les paires trouvées !**\n\n"
                    f"🔄 **{self.coups}** coups *(minimum possible : {parfait})*\n"
                    f"⏱️ **{duree//60}m{duree%60:02d}s**\n\n"
                    f"💰 **+{gain:,} pièces** *(base {base} + {bonus} de précision)*\n⭐ +40 XP"), view=self)
            return await interaction.message.edit(embed=self.build(), view=self)

        # Paire ratée : on remasque après une pause
        await asyncio.sleep(1.1)
        for i in (a, b):
            self.children[i].emoji = "🎴"
            self.children[i].style = discord.ButtonStyle.secondary
        self.retournees = []
        try:
            await interaction.message.edit(embed=self.build(), view=self)
        except Exception:
            pass

    async def on_timeout(self):
        self.fini = True
        for it in self.children:
            it.disabled = True
        if self.message:
            try:
                await self.message.edit(embed=self.build("⏰ Partie abandonnée — trop d'attente."), view=self)
            except Exception:
                pass

@bot.command(name="memory", aliases=["paires", "memo"])
async def memory_cmd(ctx, niveau: str = "facile"):
    """Memory en manches enchaînées — .memory (`.memorystop` pour arrêter)"""
    niveau = niveau.lower().strip()
    if niveau not in MemoryView.TAILLES:
        niveau = "facile"
    if ctx.channel.id in active_memory:
        return await ctx.send("🃏 Une partie de Memory est déjà en cours ! `.memorystop` pour l'arrêter.")

    salon, temporaire = await demander_salon_prive(ctx, "Memory", "🃏")
    if salon.id in active_memory:
        return await salon.send("🃏 Une partie est déjà en cours ici !")

    active_memory[salon.id] = {"running": True, "manche": 0, "total": 0,
                               "serie": 0, "niveau": niveau, "vue": None}
    await salon.send(embed=discord.Embed(
        title="🃏 Memory — Marathon",
        description=("Retrouve toutes les paires. À chaque réussite, **le niveau monte** :\n"
                     "🟢 Facile → 🟡 Normal → 🔴 Difficile → 🟢 Facile → …\n\n"
                     "**Les manches s'enchaînent sans fin.**\n"
                     "🔥 Ta **série** de victoires augmente les gains à chaque manche.\n\n"
                     "🟢 12 cartes · **250 p**   🟡 16 cartes · **450 p**   🔴 20 cartes · **800 p**\n"
                     "*+40 p par coup économisé · +10 % par manche de série*\n\n"
                     "Tape **`.memorystop`** quand tu veux arrêter."),
        color=0x9b59b6))
    await asyncio.sleep(2)

    ORDRE = ["facile", "normal", "difficile"]
    idx = ORDRE.index(niveau)

    while salon.id in active_memory and active_memory[salon.id].get("running"):
        etat = active_memory[salon.id]
        etat["manche"] += 1
        etat["niveau"] = ORDRE[idx % 3]

        vue = MemoryView(ctx.author, salon, etat["niveau"], etat)
        etat["vue"] = vue
        vue.message = await salon.send(embed=vue.build(), view=vue)
        await vue.wait()

        if salon.id not in active_memory:
            break
        if vue.gagne:
            idx += 1
            etat["serie"] += 1
            await asyncio.sleep(2.5)
        else:
            # Abandon ou temps écoulé : la série repart de zéro
            etat["serie"] = 0
            if not etat.get("running"):
                break
            await asyncio.sleep(2.5)

    etat = active_memory.pop(salon.id, None)
    if etat and etat["manche"] > 0:
        await salon.send(embed=discord.Embed(
            title="🃏 Marathon terminé",
            description=(f"**{etat['manche']} manche(s)** jouée(s)\n"
                         f"🔥 Meilleure série : **{etat.get('record', etat['serie'])}**\n"
                         f"💰 Total gagné : **{etat['total']:,} pièces**"),
            color=0x9b59b6))
    if temporaire:
        await close_event_channel(salon, 60)


@bot.command(name="memorystop", aliases=["stopmemory"])
async def memorystop_cmd(ctx):
    """Abandonne la partie de Memory — .memorystop"""
    vue = active_memory.get(ctx.channel.id)
    if not vue:
        return await ctx.send("❌ Aucune partie de Memory en cours ici !")
    if ctx.author.id != vue.joueur.id and not ctx.author.guild_permissions.manage_messages:
        return await ctx.send("❌ Seul le joueur peut abandonner.")
    vue.fini = True
    vue.stop()
    active_memory.pop(ctx.channel.id, None)
    await ctx.send(embed=discord.Embed(description="🛑 Partie de Memory abandonnée.", color=0xe74c3c))

# ============================================================
#  🔴 PUISSANCE 4 — duel à boutons
# ============================================================
active_p4 = {}

class Puissance4View(ui.View):
    """Grille 7×6, deux joueurs, boutons de colonne"""
    def __init__(self, j1, j2, channel, timeout=600):
        super().__init__(timeout=timeout)
        self.grille = [[0]*7 for _ in range(6)]
        self.joueurs = {1: j1, 2: j2}
        self.tour = 1
        self.channel = channel
        self.fini = False
        self.message = None
        for col in range(7):
            btn = ui.Button(label=str(col+1), style=discord.ButtonStyle.secondary, row=col // 4)
            async def cb(interaction, cc=col):
                await self.jouer(interaction, cc)
            btn.callback = cb
            self.add_item(btn)

    def _poser(self, col):
        for ligne in range(5, -1, -1):
            if self.grille[ligne][col] == 0:
                self.grille[ligne][col] = self.tour
                return ligne
        return None

    def _gagne(self, l, c2):
        j = self.grille[l][c2]
        for dl, dc in ((0,1),(1,0),(1,1),(1,-1)):
            n = 1
            for sens in (1,-1):
                x, y = l+dl*sens, c2+dc*sens
                while 0 <= x < 6 and 0 <= y < 7 and self.grille[x][y] == j:
                    n += 1
                    x, y = x+dl*sens, y+dc*sens
            if n >= 4:
                return True
        return False

    def build(self, fin=None):
        P = {0: "⚪", 1: "🔴", 2: "🟡"}
        plateau = "\n".join("".join(P[v] for v in ligne) for ligne in self.grille)
        plateau += "\n1️⃣2️⃣3️⃣4️⃣5️⃣6️⃣7️⃣"
        if fin:
            desc = f"{plateau}\n\n{fin}"
            col = 0xf1c40f
        else:
            j = self.joueurs[self.tour]
            desc = f"{plateau}\n\n{'🔴' if self.tour == 1 else '🟡'} Au tour de **{j.display_name}**"
            col = 0xe74c3c if self.tour == 1 else 0xf1c40f
        e = discord.Embed(title="🔴 Puissance 4", description=desc, color=col)
        e.set_footer(text=f"🔴 {self.joueurs[1].display_name}   vs   🟡 {self.joueurs[2].display_name}")
        return e

    async def jouer(self, interaction, col):
        if self.fini:
            return await interaction.response.send_message("❌ La partie est terminée.", ephemeral=True)
        if interaction.user.id != self.joueurs[self.tour].id:
            if interaction.user.id in (self.joueurs[1].id, self.joueurs[2].id):
                return await interaction.response.send_message("⏳ Ce n'est pas ton tour !", ephemeral=True)
            return await interaction.response.send_message("❌ Tu ne joues pas cette partie.", ephemeral=True)
        ligne = self._poser(col)
        if ligne is None:
            return await interaction.response.send_message("❌ Cette colonne est pleine !", ephemeral=True)

        if self._gagne(ligne, col):
            self.fini = True
            gagnant = self.joueurs[self.tour]
            gain = random.randint(250, 450)
            economy_data[str(gagnant.id)]["coins"] += gain
            gazette_gain(str(gagnant.id), gain)
            xp_data[str(gagnant.id)]["xp"] += 40
            check_coins_achievements(str(gagnant.id), self.channel)
            try: missions_progress[str(gagnant.id)]["wins"] += 1
            except Exception: pass
            gazette_note(str(gagnant.id), "duels_gagnes")
            for it in self.children: it.disabled = True
            active_p4.pop(self.channel.id, None)
            await interaction.response.edit_message(
                embed=self.build(f"🏆 **{gagnant.display_name}** aligne 4 jetons !\n💰 +{gain} pièces · ⭐ +40 XP"),
                view=self)
            return self.stop()

        if all(self.grille[0][x] != 0 for x in range(7)):
            self.fini = True
            for it in self.children: it.disabled = True
            active_p4.pop(self.channel.id, None)
            await interaction.response.edit_message(
                embed=self.build("🤝 **Match nul !** La grille est pleine."), view=self)
            return self.stop()

        self.tour = 2 if self.tour == 1 else 1
        await interaction.response.edit_message(embed=self.build(), view=self)

    async def on_timeout(self):
        active_p4.pop(self.channel.id, None)
        for it in self.children: it.disabled = True
        if self.message:
            try:
                await self.message.edit(embed=self.build("⏰ Partie abandonnée — trop d'attente."), view=self)
            except Exception:
                pass

@bot.command(name="puissance4", aliases=["p4", "connect4"])
async def puissance4_cmd(ctx, adversaire: discord.Member = None):
    """Puissance 4 en duel — .puissance4 @joueur"""
    if not adversaire or adversaire.bot or adversaire.id == ctx.author.id:
        return await ctx.send("❌ Mentionne un adversaire ! Ex : `.puissance4 @ami`")
    if ctx.channel.id in active_p4:
        return await ctx.send("🔴 Une partie est déjà en cours dans ce salon !")

    view = AcceptView(adversaire, timeout=60)
    msg = await ctx.send(
        f"{adversaire.mention}",
        embed=discord.Embed(
            title="🔴 Défi Puissance 4",
            description=(f"**{ctx.author.display_name}** défie **{adversaire.display_name}** !\n\n"
                         f"🏆 **250 à 450 pièces** + 40 XP au vainqueur\n"
                         f"*60 secondes pour accepter.*"),
            color=0xe74c3c), view=view)
    await view.wait()
    if not view.value:
        return await msg.edit(embed=discord.Embed(
            description=f"❌ **{adversaire.display_name}** n'a pas relevé le défi.", color=0x95a5a6), view=None)

    ajouter_lien(str(ctx.author.id), str(adversaire.id), "duel")
    jeu = Puissance4View(ctx.author, adversaire, ctx.channel)
    active_p4[ctx.channel.id] = jeu
    jeu.message = await ctx.send(embed=jeu.build(), view=jeu)

@bot.command(name="p4stop", aliases=["stopp4"])
async def p4stop_cmd(ctx):
    """Annule la partie de Puissance 4 — .p4stop"""
    jeu = active_p4.get(ctx.channel.id)
    if not jeu:
        return await ctx.send("❌ Aucune partie en cours ici !")
    if ctx.author.id not in (jeu.joueurs[1].id, jeu.joueurs[2].id) and not ctx.author.guild_permissions.manage_messages:
        return await ctx.send("❌ Seuls les joueurs peuvent annuler la partie.")
    jeu.fini = True
    jeu.stop()
    active_p4.pop(ctx.channel.id, None)
    await ctx.send(embed=discord.Embed(description="🛑 Partie de Puissance 4 annulée.", color=0xe74c3c))


# ============================================================
#  🎲 QUITTE OU DOUBLE — la cagnotte monte, la peur aussi
# ============================================================
QD_PALIERS = [200, 500, 1000, 2000, 4000, 8000, 15000, 30000]

class QDCandidatView(ui.View):
    def __init__(self, timeout=60):
        super().__init__(timeout=timeout)
        self.candidat = None
    @ui.button(label="Je tente ma chance !", emoji="🎲", style=discord.ButtonStyle.success)
    async def jouer(self, interaction, button):
        self.candidat = interaction.user
        button.disabled = True
        button.label = f"{interaction.user.display_name} monte sur scène"
        await interaction.response.edit_message(view=self)
        self.stop()

class QDChoixView(ui.View):
    def __init__(self, joueur, timeout=45):
        super().__init__(timeout=timeout)
        self.joueur, self.continuer = joueur, None
    async def interaction_check(self, interaction):
        if interaction.user.id != self.joueur.id:
            await interaction.response.send_message("❌ Seul le candidat décide !", ephemeral=True)
            return False
        return True
    @ui.button(label="Continuer", emoji="🔼", style=discord.ButtonStyle.danger)
    async def suite(self, interaction, button):
        self.continuer = True
        for it in self.children: it.disabled = True
        await interaction.response.edit_message(view=self)
        self.stop()
    @ui.button(label="J'encaisse", emoji="💰", style=discord.ButtonStyle.success)
    async def stop_btn(self, interaction, button):
        self.continuer = False
        for it in self.children: it.disabled = True
        await interaction.response.edit_message(view=self)
        self.stop()

async def run_quitte_ou_double(channel, guild):
    """🎲 Quitte ou Double — un candidat, des questions, une cagnotte qui explose"""
    salon = await create_event_channel(guild, "🎲・quitte-ou-double")
    cible = salon or channel
    if salon:
        await annoncer_event(guild, channel, "everyone", discord.Embed(
            title="🎲 QUITTE OU DOUBLE",
            description="Un candidat, 8 questions, **jusqu'à 30 000 pièces**… ou rien du tout.",
            color=0xf1c40f), salon)

    v = QDCandidatView(timeout=60)
    await cible.send(get_event_ping(guild, "everyone") if cible is channel else "",
                     embed=discord.Embed(
                         title="🎲 QUITTE OU DOUBLE",
                         description=("**8 paliers. La cagnotte double à chaque bonne réponse.**\n\n"
                                      "À chaque étape tu choisis : **encaisser** ou **continuer**.\n"
                                      "Une seule erreur et **tu repars les mains vides**.\n\n"
                                      "💰 200 → 500 → 1 000 → 2 000 → 4 000 → 8 000 → 15 000 → **30 000**\n\n"
                                      "*Qui a les nerfs assez solides ?*"),
                         color=0xf1c40f), view=v)
    await v.wait()
    if not v.candidat:
        await cible.send(embed=discord.Embed(description="😴 Personne n'a osé.", color=0x95a5a6))
        if salon: await close_event_channel(salon, 60)
        return

    joueur = v.candidat
    uid = str(joueur.id)
    pool = QUIZ_THEMES["mix"][:]
    random.shuffle(pool)
    posees = []

    def check(m):
        return m.channel == cible and m.author.id == joueur.id

    for palier, montant in enumerate(QD_PALIERS, start=1):
        q = pool[palier - 1] if palier - 1 < len(pool) else random.choice(QUIZ_THEMES["mix"])
        posees.append(q)
        await cible.send(f"{joueur.mention}", embed=discord.Embed(
            title=f"🎲 Palier {palier}/8  —  {montant:,} pièces en jeu",
            description=f"**{q['q']}**\n\n*30 secondes pour répondre.*",
            color=0xf1c40f))
        try:
            msg = await bot.wait_for("message", check=check, timeout=30)
            bonne = check_answer(msg.content, q["a"])
        except asyncio.TimeoutError:
            bonne = False

        if not bonne:
            await cible.send(embed=discord.Embed(
                title="💀 PERDU !",
                description=(f"La réponse était **{q['a']}**.\n\n"
                             f"**{joueur.display_name}** repart avec **0 pièce**…\n"
                             f"*Il était à un palier de {montant:,} pièces.*"),
                color=0xe74c3c))
            if salon: await close_event_channel(salon, 120)
            return

        await cible.send(embed=discord.Embed(
            description=f"✅ Bonne réponse ! **{montant:,} pièces** sécurisées… pour l'instant.",
            color=0x2ecc71))
        if palier == len(QD_PALIERS):
            break

        cv = QDChoixView(joueur, timeout=45)
        await cible.send(f"{joueur.mention}", embed=discord.Embed(
            title="🤔 Le choix",
            description=(f"Tu as **{montant:,} pièces** dans la poche.\n"
                         f"Le palier suivant vaut **{QD_PALIERS[palier]:,} pièces**.\n\n"
                         f"🔼 **Continuer** — tout risquer pour doubler\n"
                         f"💰 **J'encaisse** — repartir avec ce que tu as"),
            color=0xe67e22), view=cv)
        await cv.wait()
        if cv.continuer is False:
            economy_data[uid]["coins"] += montant
            check_coins_achievements(uid, cible)
            suivante = posees[-1]
            await cible.send(embed=discord.Embed(
                title="💰 ENCAISSÉ !",
                description=(f"**{joueur.display_name}** repart avec **{montant:,} pièces** !\n\n"
                             f"*Sagesse ou lâcheté ? Le débat est ouvert.*"),
                color=0xf1c40f))
            if salon: await close_event_channel(salon, 120)
            return
        await cible.send(embed=discord.Embed(
            description="🔥 **Il continue !** Le public retient son souffle…", color=0xe74c3c))
        await asyncio.sleep(2)

    total = QD_PALIERS[-1]
    economy_data[uid]["coins"] += total
    check_coins_achievements(uid, cible)
    await cible.send(embed=discord.Embed(
        title="🏆 LES 8 PALIERS !",
        description=(f"**{joueur.display_name}** a tout réussi et empoche **{total:,} pièces** !\n\n"
                     f"*Une performance qui restera dans les annales du QG.*"),
        color=0xf1c40f))
    if salon: await close_event_channel(salon, 180)

