import time as _time_module

gacha_wishlist = defaultdict(set)
claim_freeze = {}
claim_curse = {}

RARETE_POIDS = {
    # Poids par carte. Rééquilibrés pour que la collection entière soit visible :
    # avant, Épique+ (299 cartes sur 498) ne représentait que 5,8 % des tirages.
    "Mythique":   30,
    "Légendaire": 180,
    "Épique":     700,
    "Rare":       2400,
    "Commun":     6690,
}

def gacha_tirer(uid=None):
    """Tire une carte aléatoire selon les probabilités"""
    pool = get_obtainable_card_pool()
    # Malédiction Rare : forcé en Commun
    if uid and malediction_active.get(uid, 0) > _time_module.time():
        malediction_active.pop(uid, None)
        communs = [k for k in pool if ANIME_CARDS_DB[k]["rarete"] == "Commun"]
        if communs:
            return random.choice(communs)
    # Si boost rareté actif
    if uid and rarity_boost.get(uid, 0) > 0:
        rare_pool = [k for k in pool if ANIME_CARDS_DB[k]["rarete"] in ("Rare","Épique","Légendaire","Mythique")]
        if rare_pool and random.random() < 0.4:
            rarity_boost[uid] -= 1
            return random.choice(rare_pool)
    # Nuit de Chasse : Mythique ×3 et Légendaire ×2
    poids = dict(RARETE_POIDS)
    if nuit_chasse_active:
        poids["Mythique"] *= 3
        poids["Légendaire"] *= 2
    # 🌙 Mode Nuit : les raretés élevées sont plus accessibles entre minuit et 6 h
    if est_nuit():
        for r in ("Mythique", "Légendaire", "Épique"):
            poids[r] = int(poids[r] * NUIT_BONUS_ROLL)
    poids_total = sum(poids[ANIME_CARDS_DB[k]["rarete"]] for k in pool)
    r = random.randint(1, poids_total)
    cumul = 0
    for key in pool:
        cumul += poids[ANIME_CARDS_DB[key]["rarete"]]
        if r <= cumul:
            return key
    return random.choice(pool)

def trouver_carte(perso, uid=None, possedees_only=False):
    """Trouve la clé d'une carte. Les cartes possédées par `uid` sont prioritaires
    à score égal — évite de tomber sur un homonyme qu'on ne possède pas."""
    if not perso:
        return None
    q, qc = normalize_str(perso), _sans_espaces(perso)
    if not q:
        return None
    mots_q = set(q.split())
    a_moi = set(gacha_collections.get(uid, {})) if uid else set()

    resultats = []
    for k, cc in ANIME_CARDS_DB.items():
        if possedees_only and k not in a_moi:
            continue
        nom_n, nom_c = normalize_str(cc["nom"]), _sans_espaces(cc["nom"])
        mots_n = set(nom_n.split())
        score = 0
        if q == nom_n or qc == nom_c or qc == k:
            score = 100
        elif mots_q == mots_n:                      # « Gojo Satoru » = « Satoru Gojo »
            score = 95
        elif mots_q and mots_q.issubset(mots_n):    # tous les mots cherchés sont dans le nom
            score = 88
        elif nom_n.startswith(q) or nom_c.startswith(qc) or k.startswith(qc):
            score = 80
        elif q in nom_n or qc in nom_c:
            score = 70
        elif len(qc) >= 4 and qc in k:
            score = 60
        if score:
            # +15 si le joueur la possède : à score proche, c'est la sienne qui gagne
            bonus = 15 if k in a_moi else 0
            # −25 si la carte est retirée du pool : la carte principale prime,
            # sauf si le joueur possède justement la variante Legacy
            if k in RETIRED_CARD_MAP and k not in a_moi:
                bonus -= 25
            resultats.append((score + bonus, k))
    if not resultats:
        return None
    resultats.sort(key=lambda x: -x[0])
    return resultats[0][1]

def donner_carte(uid, key, channel=None, source=""):
    """Attribue une carte à un membre — enregistre TOUT (collection, stats, succès, gazette).
    À utiliser partout plutôt que de toucher claimed_cards directement."""
    if key not in ANIME_CARDS_DB:
        return False
    claimed_cards[key] = uid
    gacha_collections[uid][key] = {"fusion": 0}
    gazette_note(uid, "cartes")
    try:
        check_collection_achievements(uid, channel)
    except Exception:
        pass
    cc = ANIME_CARDS_DB[key]
    if cc["rarete"] in ("Légendaire", "Mythique"):
        poids = 10 if cc["rarete"] == "Mythique" else 5
        gazette_fait("carte",
                     f"**<@{uid}>** a obtenu {RARETE_EMOJI.get(cc['rarete'],'')} **{cc['nom']}** "
                     f"— une {cc['rarete']}{(' ' + source) if source else ''} !", poids)
    return True

