# ── Migration du catalogue : idempotente, rejouable sans risque ──
GACHA_CATALOG_MIGRATION_VERSION = 4
migration_state = {}     # {"catalogue": version_appliquée}

def migrer_catalogue_gacha():
    """Migre les collections vers les cartes canoniques.
    Règles absolues :
      · si la canonique est LIBRE  → la variante est transférée
      · si la canonique est PRISE par quelqu'un d'autre → le joueur GARDE sa variante (Legacy)
      · aucune carte n'est jamais retirée à personne
    Idempotente : ne s'exécute qu'une fois par version, même après 20 redémarrages."""
    if migration_state.get("catalogue", 0) >= GACHA_CATALOG_MIGRATION_VERSION:
        return {"deja_fait": True}

    stats = {"transferees": 0, "legacy": 0, "wishlist": 0, "vitrine": 0, "deja_fait": False}

    for ancien, canon in RETIRED_CARD_MAP.items():
        proprio = claimed_cards.get(ancien)
        if not proprio:
            continue
        proprio_canon = claimed_cards.get(canon)

        if proprio_canon is None:
            # La canonique est libre : on transfère proprement
            claimed_cards[canon] = proprio
            gacha_collections[proprio][canon] = gacha_collections[proprio].pop(
                ancien, {"fusion": 0})
            claimed_cards.pop(ancien, None)
            stats["transferees"] += 1
        elif proprio_canon == proprio:
            # Le joueur possède déjà la canonique : sa variante devient Legacy chez lui
            stats["legacy"] += 1
        else:
            # Conflit : deux joueurs différents. Personne ne perd rien.
            stats["legacy"] += 1

    # Les wishlists pointant vers une carte retirée sont redirigées
    for uid, wl in list(gacha_wishlist.items()):
        for ancien in list(wl):
            if ancien in RETIRED_CARD_MAP:
                wl.discard(ancien)
                canon = RETIRED_CARD_MAP[ancien]
                if canon not in claimed_cards:
                    wl.add(canon)
                stats["wishlist"] += 1

    # Les vitrines pointant vers une carte transférée
    for uid, cos in list(profil_custom.items()):
        vit = cos.get("vitrine")
        if isinstance(vit, list):
            for i, k in enumerate(vit):
                if k in RETIRED_CARD_MAP and k not in claimed_cards:
                    vit[i] = RETIRED_CARD_MAP[k]
                    stats["vitrine"] += 1

    migration_state["catalogue"] = GACHA_CATALOG_MIGRATION_VERSION
    save_all_data()
    return stats

def carte_obtenable(key):
    """Une carte retirée du pool ne peut plus être obtenue."""
    return key in ANIME_CARDS_DB and key not in RETIRED_CARD_MAP

def get_obtainable_card_pool(filtre=None, libres_only=False):
    """LE point d'entrée unique pour tout système qui donne une carte.
    `filtre` : fonction(cc) -> bool sur la fiche de la carte.
    `libres_only` : exclut les cartes déjà possédées."""
    out = []
    for k, cc in ANIME_CARDS_DB.items():
        if k in RETIRED_CARD_MAP:
            continue
        if libres_only and k in claimed_cards:
            continue
        if filtre and not filtre(cc):
            continue
        out.append(k)
    return out

def est_legacy(key):
    """La carte existe encore chez son propriétaire mais n'est plus obtenable."""
    return key in RETIRED_CARD_MAP

def badge_legacy(key):
    """Petit marqueur à afficher à côté d'une carte retirée."""
    return "  🏛️" if key in RETIRED_CARD_MAP else ""

def build_card_embed(key, uid_claimer=None, claimed=False, guild=None):
    c = ANIME_CARDS_DB[key]
    rarete    = c["rarete"]
    r_emoji   = RARETE_EMOJI.get(rarete, "▫️")
    couleur   = RARETE_COULEURS.get(rarete, 0x95a5a6)
    owner_uid = claimed_cards.get(key)

    # Bonus de fusion et de niveau (uniquement si la carte a un propriétaire)
    fus = fusion_levels.get(owner_uid, {}).get(key, 0) if owner_uid else 0
    lvl = card_level.get(owner_uid, {}).get(key, 1) if owner_uid else 1
    b_pv  = fus * 20 + (lvl - 1) * 5
    b_atk = fus * 15 + (lvl - 1) * 3
    b_def = fus * 10 + (lvl - 1) * 2
    etoiles = " " + "⭐" * fus if fus else ""

    embed = discord.Embed(
        title=f"{c.get('emoji','🎴')} {c['nom']}{etoiles}",
        description=f"*{c.get('serie','?')}*  {r_emoji} **{rarete}**",
        color=couleur)

    if c.get("image"):
        embed.set_image(url=c["image"])

    embed.add_field(
        name="📊 Stats",
        value=(f"❤️ **{c.get('pv',100) + b_pv}** PV  |  "
               f"⚔️ **{c.get('attaque',50) + b_atk}** ATK  |  "
               f"🛡️ **{c.get('defense',50) + b_def}** DEF"),
        inline=False)

    if c.get("attaques"):
        embed.add_field(
            name="⚔️ Attaques",
            value="\n".join(f"{a['emoji']} **{a['nom']}** — `{a['degats']} dégâts`"
                            for a in c["attaques"])[:1024],
            inline=False)

    if c.get("faiblesse") or c.get("resistance"):
        embed.add_field(
            name="🧩 Affinités",
            value=f"Faiblesse {c.get('faiblesse','—')}   •   Résistance {c.get('resistance','—')}",
            inline=False)

    if lvl > 1:
        embed.add_field(name="📈 Niveau", value=f"**{lvl}** / 10", inline=False)

    if owner_uid and uid_claimer and owner_uid == uid_claimer:
        nb = doublons[owner_uid].get(key, 0)
        embed.set_footer(text=f"⚡ Elle est à toi — doublons accumulés : {nb}")
    elif owner_uid:
        nom_proprio = None
        if guild:
            m = guild.get_member(int(owner_uid))
            if m:
                nom_proprio = m.display_name
        depuis = ""
        fus = fusion_levels.get(owner_uid, {}).get(key, 0)
        if fus:
            depuis = f"  ·  {'⭐' * fus}"
        if nom_proprio:
            embed.add_field(name="🔒 Déjà possédée",
                            value=f"Cette carte appartient à **{nom_proprio}**{depuis}\n"
                                  f"*`.wish {ANIME_CARDS_DB[key]['nom']}` pour être prévenu si elle se libère.*",
                            inline=False)
            embed.set_footer(text=f"🔒 Propriétaire : {nom_proprio}")
        else:
            embed.add_field(name="🔒 Déjà possédée",
                            value=f"Elle appartient à <@{owner_uid}>{depuis}", inline=False)
            embed.set_footer(text="🔒 Carte déjà réclamée")
    elif claimed:
        embed.set_footer(text="✅ Claimée !")
    else:
        embed.set_footer(text="❤️ Clique sur le cœur pour la réclamer — 30 secondes")
    if est_legacy(key):
        _cible = RETIRED_CARD_MAP[key]
        if _cible == key:
            embed.add_field(
                name="🏛️ Carte retirée",
                value="*Cette carte a été retirée du catalogue et n'est plus obtenable.*\n"
                      "*Elle reste dans ta collection.*",
                inline=False)
        else:
            _canon = ANIME_CARDS_DB.get(_cible, {}).get("nom", "?")
            embed.add_field(
                name="🏛️ Ancienne édition",
                value=(f"*Cette carte n'est plus obtenable.*\n"
                       f"*Le personnage est désormais représenté par **{_canon}**.*"),
                inline=False)
    return embed

# ============================================================
#  ❤️ CLAIM — bouton cœur sous la carte
# ============================================================
def try_claim(uid, key, guild_id, channel=None):
    """Tente de claim une carte. Retourne (succès: bool, message: str)."""
    if key not in ANIME_CARDS_DB:
        return False, "❌ Carte introuvable !"
    if key in claimed_cards:
        return False, "❌ Trop tard — cette carte appartient déjà à quelqu'un !"
    now = _time_module.time()
    # Sceau des Ombres / Cadenas — le claim est bloqué
    if claim_freeze.get(uid, 0) > now:
        reste = int(claim_freeze[uid] - now)
        return False, f"🧊 Tu es **bloqué** — encore **{reste}s** avant de pouvoir claim !"
    cooldown_mins = CLAIM_COOLDOWN_MINUTES - claim_reduction.get(uid, 0)
    # Malédiction Claim — +5 min de cooldown
    if claim_curse.get(uid, 0) > now:
        cooldown_mins += 5
    last = claim_cooldown[uid]
    if last and now - last < cooldown_mins * 60:
        reste = int((cooldown_mins * 60 - (now - last)) / 60) + 1
        return False, f"⏳ Ton claim est en recharge — encore **{reste} min**."
    donner_carte(uid, key, channel, "au claim")
    claim_cooldown[uid] = now
    economy_data[uid]["coins"] += 10
    return True, "ok"

class ClaimView(ui.View):
    """Bouton ❤️ sous la carte — premier arrivé, premier servi"""
    def __init__(self, key, timeout=30):
        super().__init__(timeout=timeout)
        self.key = key
        self.message = None

    @ui.button(emoji="❤️", style=discord.ButtonStyle.danger)
    async def claim_btn(self, interaction, button):
        uid = str(interaction.user.id)
        ok, msg = try_claim(uid, self.key, interaction.guild.id, interaction.channel)
        if not ok:
            return await interaction.response.send_message(msg, ephemeral=True)
        c = ANIME_CARDS_DB[self.key]
        button.disabled = True
        embed = build_card_embed(self.key, uid, claimed=True, guild=interaction.guild)
        embed.set_author(name=f"✅  {interaction.user.display_name} a réclamé cette carte !")
        await interaction.response.edit_message(embed=embed, view=self)
        if c["rarete"] == "Mythique":
            unlock_achievement(uid, "mythique_1", interaction.channel)
        check_collection_achievements(uid, interaction.channel)
        self.stop()

    async def on_timeout(self):
        for item in self.children:
            item.disabled = True
        if self.message and self.key not in claimed_cards:
            try:
                embed = build_card_embed(self.key, guild=getattr(self.message, "guild", None) if self.message else None)
                embed.set_footer(text="⏰ Claim expiré — personne n'a réclamé cette carte")
                await self.message.edit(embed=embed, view=self)
            except Exception:
                pass


class DoublonView(ui.View):
    """⚡ Bouton doublon — réservé au propriétaire, n'utilise pas le claim"""
    def __init__(self, key, owner_uid, timeout=30):
        super().__init__(timeout=timeout)
        self.key = key
        self.owner_uid = owner_uid
        self.message = None

    @ui.button(emoji="⚡", style=discord.ButtonStyle.primary)
    async def doublon_btn(self, interaction, button):
        uid = str(interaction.user.id)
        if uid != self.owner_uid:
            proprio = interaction.guild.get_member(int(self.owner_uid))
            return await interaction.response.send_message(
                f"❌ Cette carte appartient à **{proprio.display_name if proprio else 'quelqu\'un d\'autre'}** — "
                f"seul son propriétaire peut récupérer le doublon.", ephemeral=True)
        doublons[uid][self.key] += 1
        nb = doublons[uid][self.key]
        cc = ANIME_CARDS_DB[self.key]
        etoiles = fusion_levels[uid].get(self.key, 0)
        button.disabled = True
        embed = build_card_embed(self.key, uid, guild=interaction.guild)
        embed.set_author(name=f"⚡  {interaction.user.display_name} récupère un doublon !")
        reste = max(0, 2 - nb)
        embed.set_footer(
            text=(f"⚡ Doublons de cette carte : {nb}  •  "
                  + (f"Encore {reste} pour fusionner (.fusionner {cc['nom']})" if etoiles < 3 and reste
                     else (f"Tu peux fusionner ! → .fusionner {cc['nom']}" if etoiles < 3
                           else "Fusion maximale atteinte ⭐⭐⭐"))))
        await interaction.response.edit_message(embed=embed, view=self)
        self.stop()

    async def on_timeout(self):
        for it in self.children:
            it.disabled = True
        if self.message:
            try:
                await self.message.edit(view=self)
            except Exception:
                pass

