def role_carte(key):
    """Rôle de combat d'une carte. Équilibré par défaut si inconnue."""
    return CARTE_ROLES.get(key, "Équilibré")

# ── Forme du profil par rôle (part de PV / ATK / DEF) ──
ROLE_FORME = {
    "Tank":      (0.55, 0.20, 0.25),
    "Assassin":  (0.30, 0.56, 0.14),
    "Bruiser":   (0.42, 0.38, 0.20),
    "Perceur":   (0.34, 0.52, 0.14),
    "Équilibré": (0.38, 0.34, 0.28),
    "Support":   (0.34, 0.32, 0.34),
}
ROLE_NEUTRE = (0.38, 0.34, 0.28)
ROLE_INTENSITE = 0.40      # 0 = tous identiques, 1 = formes extrêmes

# ── Budget de puissance par rareté ──
RARETE_BUDGET = {
    "Commun": 180, "Rare": 240, "Épique": 300, "Légendaire": 360, "Mythique": 420,
}
ROLE_ECHELLE = {"pv": 1.35, "atk": 0.60, "dfs": 0.55}

# ── Capacités de rôle ──
ROLE_CAPACITE = {
    "Tank":      dict(nom="Fortification",   emoji="🛡️", cd=3, reduc=0.20, duree=1),
    "Assassin":  dict(nom="Esquive",         emoji="🌫️", cd=3, esquive=0.65, duree=1),
    "Bruiser":   dict(nom="Rage",            emoji="🔥", cd=3, boost=0.50, duree=3),
    "Perceur":   dict(nom="Faille",          emoji="💢", cd=3, perce=0.75, duree=3),
    "Équilibré": dict(nom="Second souffle",  emoji="⚖️", cd=3, reduc=0.24, soin=0.06, duree=1),
    "Support":   dict(nom="Entrave",         emoji="✨", cd=3, entrave=0.16, duree=3),
}
ROLE_EMOJI = {"Tank":"🛡️", "Assassin":"🗡️", "Bruiser":"⚔️", "Perceur":"💥",
              "Équilibré":"⚖️", "Support":"✨"}
CAPACITE_FRAPPE = 0.55     # la capacité inflige 55 % d'une Attaque
TECHNIQUE_CD    = 2

def stats_role(key, carte=None):
    """Stats de base issues du rôle et de la rareté (avant progression)."""
    cc = carte or ANIME_CARDS_DB.get(key)
    if not cc:
        return 0, 0, 0
    budget = RARETE_BUDGET.get(cc["rarete"], 240)
    f = ROLE_FORME.get(role_carte(key), ROLE_NEUTRE)
    f = tuple(ROLE_NEUTRE[i] + (f[i] - ROLE_NEUTRE[i]) * ROLE_INTENSITE for i in range(3))
    return (round(budget * f[0] * ROLE_ECHELLE["pv"]),
            round(budget * f[1] * ROLE_ECHELLE["atk"]),
            round(budget * f[2] * ROLE_ECHELLE["dfs"]))

# ── Progression proportionnelle ──
# Chaque étoile de fusion : +7 %  ·  chaque niveau au-dessus de 1 : +1,7 %
# Maximum 3⭐ + niveau 10 = ×1,363
# Le multiplicateur s'applique à PV, ATK, DEF **et** aux dégâts des attaques.
PROG_FUSION = 0.07
PROG_NIVEAU = 0.017

def card_multiplier(uid, key):
    """Multiplicateur de puissance d'une carte selon sa fusion et son niveau."""
    fus = fusion_levels[uid].get(key, 0)      # 0 à 3
    lvl = card_level[uid].get(key, 1)         # 1 à 10
    return 1 + fus * PROG_FUSION + (lvl - 1) * PROG_NIVEAU

def carte_stats_finales(uid, key, carte=None):
    """SOURCE DE VÉRITÉ des stats : rôle + rareté, puis progression.
    Alimente le combat, .gachastock, .cardinfo et .fusionner.
    Retourne (pv, attaque, defense, multiplicateur)."""
    cc = carte or ANIME_CARDS_DB.get(key)
    if not cc:
        return 0, 0, 0, 1.0
    pv, atk, dfs = stats_role(key, cc)
    m = card_multiplier(uid, key)
    return round(pv*m), round(atk*m), round(dfs*m), m

def card_total_bonus(uid, key):
    """Bonus apportés par la fusion et le niveau, en valeur absolue,
    calculés depuis les stats de rôle pour rester cohérents avec le combat."""
    cc = ANIME_CARDS_DB.get(key)
    if not cc:
        return 0, 0, 0
    b_pv, b_atk, b_dfs = stats_role(key, cc)
    pv, atk, dfs, _ = carte_stats_finales(uid, key, cc)
    return pv - b_pv, atk - b_atk, dfs - b_dfs

def degats_attaque(uid, key, base):
    """Dégâts d'une attaque, multiplicateur de progression appliqué."""
    return round(base * card_multiplier(uid, key))

def give_card_xp(uid, key, won=True):
    """Donne de l'XP à une carte et gère la montée de niveau. Retourne (level_up, new_level)"""
    if key not in ANIME_CARDS_DB:
        return False, card_level[uid].get(key, 1)
    gain = CARD_XP_WIN if won else CARD_XP_LOSE
    card_xp[uid][key] += gain
    lvl = card_level[uid].get(key, 1)
    leveled = False
    while lvl < CARD_LEVEL_MAX and card_xp[uid][key] >= CARD_XP_PER_LEVEL:
        card_xp[uid][key] -= CARD_XP_PER_LEVEL
        lvl += 1
        leveled = True
    card_level[uid][key] = lvl
    return leveled, lvl

def card_xp_team(uid, equipe, won=True):
    """Donne de l'XP à toute une équipe de cartes, retourne la liste des level-ups"""
    levelups = []
    for carte in equipe:
        key = carte.get("key")
        if key:
            leveled, new_lvl = give_card_xp(uid, key, won)
            if leveled:
                levelups.append((ANIME_CARDS_DB.get(key, {}).get("nom", key), new_lvl))
    return levelups

# ============================================================
#  F. COLLECTION PAR SÉRIE — Helpers
# ============================================================
def get_serie_cards(serie):
    """Retourne toutes les clés de cartes d'une série"""
    return [k for k, c in ANIME_CARDS_DB.items() if c["serie"].lower() == serie.lower()]

def check_serie_complete(uid, serie):
    """Vérifie si un joueur a complété une série. Retourne (complete, owned, total)"""
    serie_keys = get_serie_cards(serie)
    if not serie_keys:
        return False, 0, 0
    owned = sum(1 for k in serie_keys if k in gacha_collections[uid])
    return owned == len(serie_keys), owned, len(serie_keys)

# Récompenses de complétion par taille de série
def serie_reward(total):
    """Récompense en pièces selon la taille de la série complétée"""
    return total * 500   # 500 pièces par carte de la série

@bot.command(name="ga", aliases=["roll"])
async def ga_cmd(ctx):
    """Tire une carte gacha — .ga"""
    if SALON_GACHA_ID and ctx.channel.id != SALON_GACHA_ID:
        salon = ctx.guild.get_channel(SALON_GACHA_ID)
        mention = salon.mention if salon else "le salon gacha"
        return await ctx.send(f"🎰 Le gacha c'est dans {mention} !", delete_after=5)
    uid = str(ctx.author.id)
    now = _time_module.time()
    data = roll_data[uid]
    # Recharge des rolls
    if now - data["last_reset"] >= ROLLS_RESET_MINUTES * 60:
        data["rolls"] = ROLLS_MAX
        data["last_reset"] = now
    if data["rolls"] <= 0:
        reset_in = int((ROLLS_RESET_MINUTES * 60 - (now - data["last_reset"])) / 60)
        return await ctx.send(f"❌ Plus de rolls ! Recharge dans **{reset_in} min** ou utilise `.daily` pour +1 roll.")
    _proll = pet_bonus(uid, "roll")
    if _proll and random.randint(1, 100) <= _proll:
        pid_r, pdb_r, _ = get_active_pet(uid)
        await ctx.send(f"{pdb_r['emoji']} **{pdb_r['nom']}** te protège — roll gratuit ! 🎁", delete_after=6)
    else:
        data["rolls"] -= 1
    # Tracking missions
    track_stat(uid, "rolls", channel=ctx.channel)
    try: missions_progress[uid]["rolls"] += 1
    except: pass
    if aimant_actif.pop(uid, None):
        pool_rare = [k for k, cc in ANIME_CARDS_DB.items()
                     if k not in RETIRED_CARD_MAP
                     if cc["rarete"] in ("Rare", "Épique", "Légendaire", "Mythique")]
        key = random.choice(pool_rare) if pool_rare else gacha_tirer(uid)
    else:
        key = gacha_tirer(uid)
    c = ANIME_CARDS_DB[key]
    embed = build_card_embed(key, uid, guild=ctx.guild)
    if oeil_destin[uid] > 0:
        oeil_destin[uid] -= 1
        futur = [ANIME_CARDS_DB[gacha_tirer(uid)]["nom"] for _ in range(2)]
        embed.add_field(name="🧿 L'Œil du Destin murmure",
                        value="Prochains tirages possibles : " + " · ".join(f"*{x}*" for x in futur),
                        inline=False)
    embed.set_author(name=f"🎰  Roll de {ctx.author.display_name}  •  {data['rolls']} rolls restants")
    proprio = claimed_cards.get(key)
    if proprio == uid:
        # Ta propre carte revient → doublon gratuit, sans toucher au claim
        embed.set_footer(text="⚡ Clique sur l'éclair pour récupérer un DOUBLON — "
                              "gratuit, ça n'utilise pas ton claim ! (2 doublons = fusion)")
        view = DoublonView(key, uid, timeout=30)
        view.message = await ctx.send(embed=embed, view=view)
    elif proprio:
        await ctx.send(embed=embed)
    else:
        view = ClaimView(key, timeout=30)
        view.message = await ctx.send(embed=embed, view=view)
    # 🌟 Ping automatique des joueurs qui ont wish cette carte
    if key not in claimed_cards:
        interesses = [w for w, s in gacha_wishlist.items() if key in s and w != uid]
        if interesses:
            mentions = []
            for w in interesses[:10]:
                m = ctx.guild.get_member(int(w))
                if m:
                    mentions.append(m.mention)
            if mentions:
                await ctx.send(f"🌟 {' '.join(mentions)} — **{c['nom']}** est dans votre wishlist !")

