drama_saison = {
    "titre": None, "episode": 0, "en_cours": False,
    "casting": {}, "historique": [], "trope_cle": None,
    "vue": None, "dernier_choix": [], "votes": {},
}

def _drama_valide():
    """Répare une saison sauvegardée dans un ancien format.
    Retourne False si la saison est inutilisable (et la remet à zéro)."""
    s = drama_saison
    # Migration : l'ancien champ s'appelait « trame »
    if not s.get("trope_cle") and s.get("trame"):
        s["trope_cle"] = s.pop("trame", None)
    s.pop("trame", None)
    s.pop("vote_msg", None)
    s.setdefault("historique", [])
    s.setdefault("casting", {})
    s.setdefault("dernier_choix", [])
    s.setdefault("votes", {})
    s.setdefault("episode", 0)
    s["vue"] = None
    # Trope inconnu ou disparu → la saison ne peut pas continuer
    if s.get("en_cours") and s.get("trope_cle") not in DRAMA_TROPES:
        print(f"[Drama] Saison invalide (trope « {s.get('trope_cle')} ») — remise à zéro.")
        s.update({"en_cours": False, "episode": 0, "trope_cle": None,
                  "titre": None, "casting": {}, "historique": []})
        return False
    return True

# Chaque trame donne une saison totalement différente

# Chaque épisode a sa propre couleur narrative






class DramaVoteView(ui.View):
    """Vote de l'ancien système — conservé pour compatibilité"""
    def __init__(self, options=None, timeout=None):
        super().__init__(timeout=timeout)
        self.options = options or drama_saison.get("dernier_choix") or ["A", "B", "C"]
        for i in range(3):
            btn = ui.Button(label=["A", "B", "C"][i], emoji=["🅰️", "🅱️", "🇨"][i],
                            style=discord.ButtonStyle.primary,
                            custom_id=f"drama_vote_{i}")
            async def cb(interaction, idx=i):
                if not drama_saison.get("en_cours"):
                    return await interaction.response.send_message(
                        "❌ Aucune saison en cours.", ephemeral=True)
                choix = drama_saison.get("dernier_choix") or self.options
                if idx >= len(choix):
                    return await interaction.response.send_message(
                        "❌ Ce vote n'est plus valide.", ephemeral=True)
                votes = drama_saison.setdefault("votes", {})
                uid = str(interaction.user.id)
                deja = votes.get(uid)
                votes[uid] = idx
                save_all_data()
                cnt = {}
                for v in votes.values():
                    cnt[v] = cnt.get(v, 0) + 1
                tot = sum(cnt.values())
                detail = "\n".join(
                    f"{['🅰️','🅱️','🇨'][k]} {choix[k][:40]} — **{v}** ({v/tot*100:.0f} %)"
                    for k, v in sorted(cnt.items()))
                await interaction.response.send_message(
                    f"{'🔄 Vote modifié' if deja is not None else '✅ Vote enregistré'} — "
                    f"**{choix[idx]}**\n\n{detail}\n\n"
                    f"*{tot} personne(s) ont voté. Tu peux changer d'avis jusqu'au dépouillement.*",
                    ephemeral=True)
            btn.callback = cb
            self.add_item(btn)


def _drama_perso(guild):
    s = drama_saison
    a = s["casting"].get("a") or "Elle"
    b = s["casting"].get("b") or "Lui"
    return a, b

def _drama_format(txt, guild, lieu):
    s = drama_saison
    tr = DRAMA_TROPES.get(s.get("trope_cle")) or next(iter(DRAMA_TROPES.values()))
    a, b = _drama_perso(guild)
    return (txt.replace("{a}", a).replace("{b}", b).replace("{lieu}", lieu)
               .replace("{objet}", tr["objet"]).replace("{conflit}", tr["conflit"])
               .replace("{proximite}", tr["proximite"]))

async def publier_episode(guild, salon, rappel=None):
    """Publie l'épisode courant, précédé du résultat des votes"""
    s = drama_saison
    if not _drama_valide():
        return await salon.send("❌ La saison en cours était corrompue — elle a été remise à zéro. "
                                "Relance-la avec `.drama-start`.")
    tr = DRAMA_TROPES[s["trope_cle"]]
    ep = s["episode"] + 1
    if ep > len(DRAMA_EPISODES):
        return await cloturer_saison(guild, salon)

    E = DRAMA_EPISODES[ep - 1]
    lieu = random.choice(tr["lieux"])
    scene = _drama_format(random.choice(E["scenes"]), guild, lieu)
    cliff_src = [x for x in E["cliff"] if x]
    cliff = _drama_format(random.choice(cliff_src), guild, lieu) if cliff_src else ""
    choix = [_drama_format(x, guild, lieu) for x in random.choice(E["choix"])]

    # ── En-tête : résultat du vote précédent ──
    entete = ""
    if rappel:
        pont = random.choice(DRAMA_PONTS.get(rappel.get("index"), DRAMA_PONTS[None]))
        pont = _drama_format(pont, guild, lieu)
        entete = (f"> 🗳️ **Résultats de l'épisode {ep-1}**\n"
                  f"> {rappel['detail']}\n"
                  f"> \n"
                  f"> ➡️ **Le choix du serveur : {rappel['gagnant']}**\n\n"
                  f"━━━━━━━━━━━━━━━━━━━━\n\n"
                  f"**Conséquence :** {pont}\n\n"
                  f"━━━━━━━━━━━━━━━━━━━━\n\n")

    corps = (f"{entete}"
             f"### 「 Épisode {ep} — {E['titre']} 」\n"
             f"*{E['etape']}*\n\n"
             f"━━━━━━━━━━━━━━━━━━━━\n\n"
             f"{scene}")

    embed = discord.Embed(
        title=f"🎬  {tr['titre']}",
        description=corps[:4000],
        color=0xff6b9d)
    embed.set_author(name=f"{tr['trope']}  ·  Épisode {ep}/{len(DRAMA_EPISODES)}")

    if cliff:
        embed.add_field(name="\u200b", value=f"### ⚡\n> *{cliff}*", inline=False)

    embed.add_field(
        name="🗳️  À vous d'écrire la suite",
        value=(f"🅰️  {choix[0]}\n"
               f"🅱️  {choix[1]}\n"
               f"🇨  {choix[2]}\n\n"
               f"*Votez ci-dessous. Le prochain épisode partira de votre choix.*\n"
               f"💰 **150 pièces** à chaque votant."),
        inline=False)
    embed.set_footer(text=f"{tr['titre']} · Épisode {ep}/{len(DRAMA_EPISODES)} · "
                          f"Le staff publiera la suite avec .drama-next")

    s["episode"] = ep
    s["dernier_choix"] = choix
    s["votes"] = {}
    vue = DramaVoteView(choix)
    s["vue"] = vue
    await salon.send(get_event_ping(guild, "everyone"), embed=embed, view=vue)
    save_all_data()

