async def resoudre_episode(guild, salon):
    """Dépouille le vote et enchaîne sur l'épisode suivant"""
    s = drama_saison
    votes = s.get("votes") or {}
    rappel = None
    if votes and s.get("dernier_choix"):
        cnt = {}
        for v in votes.values():
            cnt[int(v)] = cnt.get(int(v), 0) + 1
        gagnant = max(cnt, key=cnt.get)
        total = sum(cnt.values())
        texte = s["dernier_choix"][gagnant]
        s["historique"].append(f"Ép. {s['episode']} — {texte}")
        detail = "  ·  ".join(
            f"{['🅰️','🅱️','🇨'][k]} {v} ({v/total*100:.0f} %)"
            for k, v in sorted(cnt.items()))
        rappel = {"detail": detail, "gagnant": texte, "index": gagnant,
                  "consequence": random.choice(DRAMA_CONSEQ)}
        # Chronique 2.0 : plus aucune récompense pour voter.
        # On vote parce qu'on est impliqué dans l'histoire, pas pour farmer.
        gazette_fait("divers",
                     f"Le serveur a voté « {texte} » — épisode {s['episode']} du drama.", 2)
    else:
        s["historique"].append(f"Ép. {s['episode']} — Personne n'a voté, l'histoire a suivi son cours.")
        rappel = {"detail": "Aucun vote enregistré.", "index": None,
                  "gagnant": "l'histoire a suivi son cours toute seule",
                  "consequence": "Le silence est aussi une réponse."}
    s["vue"] = None
    s["votes"] = {}
    await publier_episode(guild, salon, rappel=rappel)


async def cloturer_saison(guild, salon):
    """Fin de saison — récapitulatif complet"""
    s = drama_saison
    tr = DRAMA_TROPES.get(s.get("trope_cle")) or next(iter(DRAMA_TROPES.values()))
    a, b = _drama_perso(guild)
    recap = "\n".join(f"**{t}**" for t in s["historique"]) or "*Aucun épisode joué.*"
    await salon.send(embed=discord.Embed(
        title=f"🎬  {tr['titre']}  —  FIN DE SAISON",
        description=(f"*{tr['accroche']}*\n\n"
                     f"━━━━━━━━━━━━━━━━━━━━\n\n"
                     f"🎭 {a} — {tr['role_a']}\n"
                     f"🎭 {b} — {tr['role_b']}\n\n"
                     f"━━━━━━━━━━━━━━━━━━━━\n\n"
                     f"### L'histoire que vous avez écrite\n\n{recap}\n\n"
                     f"━━━━━━━━━━━━━━━━━━━━\n\n"
                     f"*Cette saison n'existe que sur ce serveur. "
                     f"Personne d'autre n'aura jamais lu celle-ci.*"),
        color=0xf1c40f).set_footer(text="Le staff peut lancer une nouvelle saison avec .drama-start"))
    s["en_cours"] = False
    s["episode"] = 0
    save_all_data()

@bot.command(name="drama-start", aliases=["dramastart", "lancerdrama"])
@commands.has_permissions(manage_guild=True)
async def dramastart_cmd(ctx, *, args: str = None):
    """Lance une saison — .drama-start [trope] [@perso1 @perso2] (staff)

    `.drama-start`                        → trope et casting au hasard
    `.drama-start ennemis`                → trope choisi, casting au hasard
    `.drama-start @Marie @Kevin`          → casting choisi, trope au hasard
    `.drama-start ennemis @Marie @Kevin`  → tout choisi
    `.drama-start liste`                  → voir les 10 histoires
    """
    s = drama_saison
    _drama_valide()
    if s["en_cours"]:
        return await ctx.send(embed=discord.Embed(
            description=(f"🎬 **{DRAMA_TROPES[s['trope_cle']]['titre']}** est déjà en cours "
                         f"— épisode **{s['episode']}/{len(DRAMA_EPISODES)}**.\n\n"
                         f"`.drama-next` pour la suite · `.drama-stop` pour clôturer."),
            color=0xe74c3c))

    # ── Casting : on lit les mentions réelles du message ──
    mentions = [m for m in ctx.message.mentions if not m.bot]

    # ── Trope : on retire les mentions du texte pour isoler le mot-clé ──
    texte = re.sub(r"<@!?\d+>", "", args or "").strip().lower()
    mot = texte.split()[0] if texte.split() else None

    if mot in ("liste", "list", "tropes", "histoires", "aide", "help"):
        mot = "__liste__"

    if mot and mot != "__liste__" and mot not in DRAMA_TROPES:
        proches = [k for k in DRAMA_TROPES if mot in k or k in mot]
        if len(proches) == 1:
            mot = proches[0]
        else:
            mot = "__liste__"

    if mot == "__liste__":
        items = list(DRAMA_TROPES.items())
        pages = []
        for i in range(0, len(items), 4):
            e = discord.Embed(
                title="🎬 Choisis une histoire",
                description=("*Chaque trope donne une saison entièrement différente.*\n\n"
                             "**`.drama-start <trope>`** — l'histoire de ton choix\n"
                             "**`.drama-start`** — une histoire et un casting au hasard\n"
                             "**`.drama-start <trope> @a @b`** — tout choisir"),
                color=0xff6b9d)
            for k, v in items[i:i+4]:
                e.add_field(name=f"{v['trope']}  ·  {v['titre']}",
                            value=f"`{k}`\n*« {v['accroche']} »*", inline=False)
            e.set_footer(text=f"{len(DRAMA_TROPES)} histoires · {len(DRAMA_EPISODES)} épisodes chacune")
            pages.append(e)
        vue = PageView(pages, ctx.author, timeout=180) if len(pages) > 1 else None
        return await ctx.send(embed=pages[0], view=vue)

    cle = mot if mot else random.choice(list(DRAMA_TROPES))
    tr = DRAMA_TROPES[cle]

    # ── Sélection du casting ──
    # Slot A = personnage féminin · Slot B = personnage masculin (les scènes sont écrites ainsi)
    duo_reel = len(mentions) >= 2

    if duo_reel:
        m1, m2 = mentions[0], mentions[1]
        g1 = detecter_genre(m1)
        # Si m1 est un homme, il prend le slot B
        if g1 == "h":
            slot_a, slot_b = m2, m1
        else:
            slot_a, slot_b = m1, m2
        casting = {"a": slot_a.mention, "b": slot_b.mention,
                   "nom_a": slot_a.display_name, "nom_b": slot_b.display_name,
                   "fictif": None}
        vedette, partenaire = slot_a, None
        origine_casting = "deux membres du serveur"
    else:
        if len(mentions) == 1:
            vedette = mentions[0]
            origine_casting = "membre choisi par le staff"
        else:
            actifs = [m for m in ctx.guild.members
                      if not m.bot and str(m.id) in xp_data and xp_data[str(m.id)]["level"] >= 2]
            pool = actifs or [m for m in ctx.guild.members if not m.bot and str(m.id) in xp_data] \
                          or [m for m in ctx.guild.members if not m.bot]
            if not pool:
                return await ctx.send("❌ Aucun membre disponible pour le casting.")
            vedette = random.choice(pool)
            origine_casting = "membre tiré au sort"

        genre_membre = detecter_genre(vedette)
        if genre_membre is None:
            genre_membre = random.choice(["f", "h"])
            origine_casting += " · genre non configuré, deviné"

        perso = creer_personnage("h" if genre_membre == "f" else "f")
        if genre_membre == "f":
            casting = {"a": vedette.mention, "b": f"**{perso['prenom']}**",
                       "nom_a": vedette.display_name, "nom_b": perso["nom"], "fictif": perso}
        else:
            casting = {"a": f"**{perso['prenom']}**", "b": vedette.mention,
                       "nom_a": perso["nom"], "nom_b": vedette.display_name, "fictif": perso}
        partenaire = perso

    s.update({"titre": tr["titre"], "episode": 0, "en_cours": True, "trope_cle": cle,
              "casting": casting, "historique": [], "vue": None})
    save_all_data()

    salon = (ctx.guild.get_channel(SALON_ANNONCES_ID) if SALON_ANNONCES_ID else None) or ctx.channel
    if partenaire:
        bloc_casting = (
            f"### 🎭 Au casting\n"
            f"{casting['a']}\n└ *{tr['role_a']}*\n\n"
            f"{casting['b']}\n└ *{tr['role_b']}*\n\n"
            f"> 🆕 **{partenaire['nom']}** est un personnage inventé pour cette saison.\n"
            f"> On le reconnaît à {partenaire['trait']}.")
    else:
        bloc_casting = (f"### 🎭 Au casting\n"
                        f"{casting['a']}\n└ *{tr['role_a']}*\n\n"
                        f"{casting['b']}\n└ *{tr['role_b']}*")

    embed = discord.Embed(
        title=f"🎬  {tr['titre']}",
        description=(f"## « {tr['accroche']} »\n\n"
                     f"━━━━━━━━━━━━━━━━━━━━\n\n"
                     f"{tr['pitch']}\n\n"
                     f"━━━━━━━━━━━━━━━━━━━━\n\n"
                     f"{bloc_casting}\n\n"
                     f"━━━━━━━━━━━━━━━━━━━━\n\n"
                     f"**{len(DRAMA_EPISODES)} épisodes.** Pas de coup de foudre, "
                     f"pas de raccourci — ils partent de zéro et se supportent à peine.\n\n"
                     f"À la fin de chaque épisode, **vous votez**. Le suivant reprendra "
                     f"exactement là où votre choix l'aura mené.\n"
                     f"💰 **150 pièces** à chaque votant.\n\n"
                     f"*Personne ne connaît la fin. Elle n'est pas écrite.*"),
        color=0xff6b9d)
    embed.set_author(name=tr["trope"])
    embed.set_thumbnail(url=vedette.display_avatar.url)
    embed.set_footer(text=f"Casting : {origine_casting} · le premier épisode arrive…")
    ping = vedette.mention + ((" " + mentions[1].mention) if duo_reel else "")
    await salon.send(ping, embed=embed)
