NUIT_DEBUT, NUIT_FIN = 0, 6

def est_nuit():
    h = datetime.datetime.now().hour
    return NUIT_DEBUT <= h < NUIT_FIN

def couleur_nuit(defaut=0xff6b9d):
    """Palette sombre quand il fait nuit"""
    return 0x2c2f4a if est_nuit() else defaut

