@bot.command(name="petparler", aliases=["parler", "petdiscuter"])
async def petparler_cmd(ctx, *, message: str = None):
    """Parle à ton compagnon — .petparler [message]"""
    uid = str(ctx.author.id)
    pid, pdb, pst = get_active_pet(uid)
    if not pid:
        return await ctx.send("🐾 Tu n'as pas de compagnon actif ! Rends-toi dans `.shop`.")
    pet_init_perso(uid)
    init_preferences(uid)
    st = pet_etat(uid)
    nom_pet = pst.get("surnom") or pdb["nom"]
    cle_r, emo_r, nom_r = routine_actuelle()

    # ── 1. Une intention reconnue prime sur tout ──
    intention = detecter_intention(message)
    if intention:
        cle_i, conf_i = intention
        objet = pst.get("objet_prefere") or "son jouet"
        # La personnalité change la réponse quand une variante existe
        pool = list(conf_i["reponses"])
        for tr in (pst.get("traits") or []):
            var = INTENTIONS_TRAITS.get(cle_i, {}).get(tr)
            if var:
                pool = var * 3 + pool
        replique = _sans_repet(uid, "int_" + cle_i, pool, memoire=4).replace(
            "{objet}", f"**{objet}**")
        # Une fois sur cinq, il fait référence à son vécu
        if random.random() < 0.2:
            _ref = _souvenir_evocable(uid, pst)
            if _ref:
                replique += f"\n-# {_ref}"
        st["humeur"] = max(0, min(100, st["humeur"] + conf_i["humeur"]))
        pst["confiance"] = min(100, pst.get("confiance", 0) + conf_i["confiance"])
        pst.setdefault("intentions", {})
        pst["intentions"][cle_i] = pst["intentions"].get(cle_i, 0) + 1
    else:
        # ── 2. Sinon : selon l'état, la personnalité et l'heure ──
        pool = []
        if st["faim"] > 65: pool += PET_REPLIQUES["faim"] * 3
        if st["energie"] < 35: pool += PET_REPLIQUES["fatigue"] * 3
        if st["proprete"] < 35: pool += PET_REPLIQUES["sale"] * 2
        if st["humeur"] < 40: pool += PET_REPLIQUES["triste"] * 3
        elif st["humeur"] > 75: pool += PET_REPLIQUES["heureux"] * 2
        for t in pst.get("traits", []):
            if t in PET_REPLIQUES:
                pool += PET_REPLIQUES[t] * 2
        if cle_r in PET_REPLIQUES: pool += PET_REPLIQUES[cle_r] * 2
        _mois = datetime.datetime.now().month
        _sais = ("hiver" if _mois in (12,1,2) else "ete" if _mois in (6,7,8) else None)
        if _sais and _sais in PET_REPLIQUES: pool += PET_REPLIQUES[_sais]
        pool += PET_REPLIQUES["neutre"]
        replique = _sans_repet(uid, "replique", pool, memoire=8)

    if not intention:
        st["humeur"] = min(100, st["humeur"] + 3)
    pet_stat(uid, "discussions")
    appris = analyser_mot(uid, message)
    save_all_data()

    _, _, activite = activite_routine(uid)
    embed = discord.Embed(
        title=f"💬 {pet_nom_decore(uid, pdb)}",
        description=(f"> {message}\n\n" if message else "")
                    + f"**{nom_pet}** {replique}",
        color=0xe91e63)
    if appris:
        cle_m, niv, nouveau = appris
        variantes, emo_m, action = MOTS_APPRIS[cle_m]
        if nouveau:
            pet_carnet_note(uid, f"{emo_m} A compris ce que signifie « {message[:30]} ».", important=True)
            embed.add_field(name="✨ Il a appris quelque chose !",
                            value=(f"# {emo_m}\n**{nom_pet}** a compris ce que tu voulais dire.\n"
                                   f"Désormais, il **{action}**"), inline=False)
        elif niv >= SEUIL_COMPRIS:
            embed.add_field(name=f"{emo_m} Il comprend", value=f"*Il {action}*", inline=False)
        elif niv >= 3:
            embed.add_field(name="👀 Il commence à comprendre…",
                            value="*Il penche la tête, l'air d'y réfléchir.*", inline=False)
        else:
            embed.add_field(name="🐾 …",
                            value="*Il penche la tête. Il ne comprend pas encore.*", inline=False)
    embed.add_field(name=f"{emo_r} {nom_r}", value=f"*Il {activite}.*", inline=False)
    nb_mots = sum(1 for v in pst.get("mots", {}).values() if v >= SEUIL_COMPRIS)
    if intention:
        cle_i, conf_i = intention
        n_fois = pst.get("intentions", {}).get(cle_i, 1)
        signe = "+" if conf_i["humeur"] >= 0 else ""
        embed.add_field(name=f"{conf_i['emoji']} Il a compris",
                        value=(f"*Intention reconnue : **{cle_i}***\n"
                               f"❤️ Humeur **{signe}{conf_i['humeur']}**"
                               + (f"  ·  💞 Confiance **+{conf_i['confiance']}**" if conf_i['confiance'] else "")
                               + f"\n*Tu lui as dit ça **{n_fois} fois**.*"), inline=False)
    embed.set_footer(text=f"{pet_humeur_texte(st)} · "
                          f"{nb_mots}/{len(MOTS_APPRIS)} expressions comprises · "
                          f"{len(INTENTIONS)} intentions reconnues")
    await ctx.send(embed=embed)

@bot.command(name="petgouts", aliases=["gouts", "petpreferences"])
async def petgouts_cmd(ctx, membre: discord.Member = None):
    """Les goûts de ton compagnon — .petgouts"""
    cible = membre or ctx.author
    uid = str(cible.id)
    pid, pdb, pst = get_active_pet(uid)
    if not pid:
        return await ctx.send(f"🐾 **{cible.display_name}** n'a pas de compagnon actif.")
    pet_init_perso(uid)
    init_preferences(uid)
    prefs = pst.get("prefs", {})
    obj = pst.get("objet_prefere")
    emo_o = PET_OBJETS_TROUVES.get(obj, ("🎁",))[0] if obj else ""
    _, _, activite = activite_routine(uid)
    cle_r, emo_r, nom_r = routine_actuelle()

    embed = discord.Embed(
        title=f"❤️ Les goûts de {pet_nom_decore(uid, pdb)}",
        description="*Chaque compagnon développe ses propres préférences.*",
        color=0xe91e63)
    embed.add_field(name="🍖 Nourriture préférée", value=prefs.get("nourriture", "?"), inline=True)
    embed.add_field(name="🛏️ Endroit préféré", value=prefs.get("endroit", "?"), inline=True)
    embed.add_field(name="🎨 Couleur préférée", value=prefs.get("couleur", "?"), inline=True)
    embed.add_field(name="🧸 Objet préféré",
                    value=f"{emo_o} **{obj}**" if obj else "*Il n'a encore rien trouvé.*", inline=False)
    embed.add_field(name=f"{emo_r} En ce moment ({nom_r})", value=f"*Il {activite}.*", inline=False)
    traits = pst.get("traits", [])
    if traits:
        embed.set_footer(text="Caractère : " + " · ".join(PET_TRAITS[t][1] for t in traits if t in PET_TRAITS))
    await ctx.send(embed=embed)


