@bot.command(name="petbebe", aliases=["bebe", "descendance", "petfamille"])
async def petbebe_cmd(ctx, ami: discord.Member = None):
    """Deux compagnons très proches peuvent avoir un petit — .petbebe @ami"""
    import time as _t
    uid = str(ctx.author.id)
    pid, pdb, pst = get_active_pet(uid)
    if not pid:
        return await ctx.send("🐾 Tu n'as pas de compagnon actif !")
    pet_init_perso(uid)

    # ── Voir sa famille ──
    if not ami:
        e = discord.Embed(title=f"👨‍👩‍👧 La famille de {pet_nom_decore(uid, pdb)}",
                          color=0xe91e63)
        parents = pst.get("parents")
        if parents:
            e.add_field(name="🐣 Ses parents",
                        value=f"{parents.get('a','?')}  ×  {parents.get('b','?')}", inline=False)
        enfants = pst.get("enfants", [])
        if enfants:
            e.add_field(name=f"🍼 Ses petits ({len(enfants)})",
                        value="\n".join(f"{x.get('emoji','🐾')} **{x.get('nom','?')}** "
                                        f"— *avec {x.get('copar','?')}*" for x in enfants[:6]),
                        inline=False)
        meilleur = None
        best = 0
        for cle, pts in petamitie.items():
            if uid in cle.split("|") and pts > best:
                autre = next(x for x in cle.split("|") if x != uid)
                m = ctx.guild.get_member(int(autre)) if ctx.guild else None
                if m:
                    best, meilleur = pts, m
        if meilleur:
            a_pid, a_pdb, a_pst = get_active_pet(str(meilleur.id))
            nom_a = (a_pst.get("surnom") or a_pdb["nom"]) if a_pid else "?"
            pret = best >= 35
            e.add_field(name="💖 Relation la plus forte",
                        value=(f"**{nom_a}** *({meilleur.display_name})* — **{best}** rencontres\n"
                               + ("✅ **Ils peuvent avoir un petit !**\n"
                                  f"*`.petbebe @{meilleur.display_name}`*" if pret
                                  else f"*Encore **{35-best}** rencontres pour un petit "
                                       f"(palier 👑 Duo légendaire).*")), inline=False)
        if not parents and not enfants and not meilleur:
            e.description = ("*Pas encore de famille.*\n\n"
                             "Deux compagnons **👑 Duo légendaire** *(35 rencontres)* "
                             "peuvent avoir un petit qui hérite de leurs deux caractères.")
        e.set_footer(text="`.petvisite @ami` pour renforcer une relation")
        return await ctx.send(embed=e)

    # ── Créer un petit ──
    if ami.bot or ami.id == ctx.author.id:
        return await ctx.send("❌ Mentionne un autre membre !")
    aid = str(ami.id)
    a_pid, a_pdb, a_pst = get_active_pet(aid)
    if not a_pid:
        return await ctx.send(f"🐾 **{ami.display_name}** n'a pas de compagnon actif.")
    pts = petamitie.get(_cle_amitie(uid, aid), 0)
    if pts < 35:
        return await ctx.send(embed=discord.Embed(
            description=(f"💖 Leurs compagnons sont à **{pts}/35** rencontres.\n"
                         f"*Il faut atteindre **👑 Duo légendaire** pour avoir un petit.*"),
            color=0x95a5a6))
    if pst.get("bebe_avec") == aid:
        return await ctx.send("🍼 Vous avez déjà eu un petit ensemble !")

    COUT = 25000
    if economy_data[uid]["coins"] < COUT:
        return await ctx.send(f"❌ Il faut **{COUT:,} pièces** pour préparer l'arrivée d'un petit "
                              f"*(tu en as {economy_data[uid]['coins']:,})*.")

    # Héritage
    parent = random.choice([pid, a_pid])
    pdb_bebe = PETS_DB[parent]
    traits_p = (pst.get("traits", []) + a_pst.get("traits", []))
    traits_b = random.sample(list(set(traits_p)), min(2, len(set(traits_p)))) if traits_p else \
               random.sample(list(PET_TRAITS), 2)
    # La particularité peut être héritée, ou toute nouvelle
    parts = [x for x in (pst.get("particularite"), a_pst.get("particularite")) if x]
    if parts and random.random() < 0.6:
        part_b = random.choice(parts)
    else:
        tirage, cumul, part_b = random.randint(1, 1000), 0, None
        for k, v in sorted(PET_PARTICULARITES.items(), key=lambda x: x[1][3]):
            cumul += v[3]
            if tirage <= cumul:
                part_b = k
                break

    economy_data[uid]["coins"] -= COUT
    cle_bebe = f"bebe_{uid}_{int(_t.time())}"
    nom_a = pst.get("surnom") or pdb["nom"]
    nom_b = a_pst.get("surnom") or a_pdb["nom"]
    # BUG 2 corrigé : l'espèce n'est plus ajoutée à PETS_DB.
    # On garde l'espèce d'origine dans la fiche du bébé — `espece_base` suffit.

    pets_data.setdefault(uid, {"owned": {}, "active": None})
    pets_data[uid]["owned"][cle_bebe] = {
        "level": 1, "xp": 0, "adoption": _t.time(), "carnet": [],
        "stats": {}, "titres": [], "habitudes": {}, "prefs": {}, "objets": [],
        "est_bebe": True,
        "espece_base": parent,                      # clé d'une espèce réelle de PETS_DB
        "nom_bebe": f"Petit de {nom_a}",
        "parents": {"a": f"{pdb['emoji']} {nom_a}", "b": f"{a_pdb['emoji']} {nom_b}"},
        "parent_a": uid, "parent_b": aid,
    }
    # BUG 3 corrigé : héritage complet (traits, goûts, particularité)
    bebe_init_heritage(pets_data[uid]["owned"][cle_bebe], pst, a_pst)
    pst["bebe_avec"] = aid
    pst.setdefault("enfants", []).append(
        {"emoji": pdb_bebe["emoji"], "nom": f"Petit de {nom_a}", "copar": ami.display_name})
    a_pst.setdefault("enfants", []).append(
        {"emoji": pdb_bebe["emoji"], "nom": f"Petit de {nom_a}", "copar": ctx.author.display_name})
    pet_carnet_note(uid, f"🍼 A eu un petit avec **{nom_b}** !", important=True)
    pet_carnet_note(aid, f"🍼 A eu un petit avec **{nom_a}** !", important=True)
    ajouter_lien(uid, aid, "pet")
    save_all_data()

    embed = discord.Embed(
        title="🍼  Un petit est né !",
        description=(f"# {pdb_bebe['emoji']}\n"
                     f"**{pdb['emoji']} {nom_a}**  ×  **{a_pdb['emoji']} {nom_b}**\n\n"
                     f"Un petit **{pdb_bebe['nom']}** rejoint la famille de {ctx.author.mention} !\n\n"
                     f"🧠 **Caractère hérité :** "
                     + " · ".join(f"{PET_TRAITS[t][0]} {PET_TRAITS[t][1]}" for t in traits_b) + "\n"
                     f"✨ Il a une **particularité cachée** — à toi de la découvrir.\n\n"
                     f"💰 **−{COUT:,} pièces**"),
        color=0xf1c40f)
    embed.set_footer(text=f"`.petnom <nom>` après l'avoir équipé avec `.pet equiper` · "
                          f"`.petbebe` pour voir la famille")
    await ctx.send(f"{ami.mention}", embed=embed)
    gazette_fait("divers", f"Les compagnons de **{ctx.author.display_name}** et "
                           f"**{ami.display_name}** ont eu un petit ! 🍼", 5)

def _pages_petshop(uid, guild=None):
    """Construit les pages du petshop — même principe que le help"""
    pid, pdb, pst = get_active_pet(uid)
    solde = economy_data[uid]["coins"]
    pages = []

    # ── 🐾 Compagnons ──
    possedes = set(pets_data.get(uid, {}).get("owned", {}))
    e = discord.Embed(title="🐾  Compagnons",
        description=f"*Adopte un nouveau compagnon.*\n💰 **{solde:,} pièces**", color=0xe91e63)
    for rar in ["Commun", "Rare", "Épique", "Légendaire", "Mythique"]:
        lot = [(k, v) for k, v in PETS_DB.items()
               if v["rarete"] == rar and not k.startswith("bebe_")]
        if not lot:
            continue
        e.add_field(name=f"{rar} — {PETS_PRIX[rar]:,} p",
                    value="  ·  ".join(f"{v['emoji']} **{v['nom']}**" + (" ✅" if k in possedes else "")
                                       for k, v in lot)[:1024], inline=False)
    e.set_footer(text="`.acheter <nom du compagnon>` pour adopter")
    pages.append(("🐾", "Compagnons", e))

    # ── 🍖 Nourriture, une page par catégorie ──
    garde = stock_nourriture(uid)
    gouts = gouts_repas(uid) if pid else {}
    SYM = {"adore": "😍", "aime": "😊", "neutre": "😐", "deteste": "😖"}
    for cat, (c_emo, c_nom, c_desc) in CAT_NOURRITURE.items():
        lot = [(n, v) for n, v in PET_NOURRITURE.items() if v[1] == cat and nourriture_dispo(n)]
        if not lot:
            continue
        e = discord.Embed(title=f"{c_emo}  Nourriture — {c_nom}",
            description=f"*{c_desc}*\n💰 **{solde:,} pièces**", color=0xe67e22)
        lignes = []
        for n, v in sorted(lot, key=lambda x: x[1][3]):
            g = SYM.get(gouts.get(n), "")
            stock = f" `×{garde[n]}`" if garde.get(n) else ""
            lignes.append(f"{v[0]} **{n}** — {v[3]:,} p · +{v[2]} faim {g}{stock}")
        for i in range(0, len(lignes), 8):
            e.add_field(name="\u200b" if i else "🛒 Au menu",
                        value="\n".join(lignes[i:i+8]), inline=False)
        e.set_footer(text="`.petacheter <aliment> [quantité]` · `.petmanger <aliment>` pour lui donner")
        pages.append((c_emo, f"Nourriture · {c_nom}", e))

    # ── 🧸 Jouets ──
    coffre = stock_jouets(uid)
    TYPES = {"lance": "🎾 À lancer", "roule": "⚽ À faire rouler", "chasse": "🪶 À chasser",
             "calin": "🧸 Doudous", "tire": "🪢 Tir à la corde", "reflechit": "🧩 Réflexion",
             "bruit": "🎹 Bruyants", "cachette": "📦 Cachettes", "creatif": "🎨 Créatifs"}
    e = discord.Embed(title="🧸  Jouets",
        description=(f"*{len(coffre)}/{len(PET_JOUETS)} possédés · chaque jouet a ses propres réactions.*\n"
                     f"💰 **{solde:,} pièces**"), color=0x9b59b6)
    for typ, lab in TYPES.items():
        lot = [(k, v) for k, v in PET_JOUETS.items() if v[2] == typ]
        e.add_field(name=lab, value="  ·  ".join(
            f"{v[0]} **{k}**" + (" ✅" if k in coffre else f" `{v[1]:,}p`") for k, v in lot)[:1024],
            inline=False)
    e.set_footer(text="`.petjouets acheter <jouet>` · `.petjouets jouer <jouet>`")
    pages.append(("🧸", "Jouets", e))

    # ── 🪑 Meubles, une page par pièce ──
    ref = pets_data.get(uid, {}).get("refuge", [])
    EFF = {"humeur_lente": "❤️", "faim_lente": "🍖", "energie_lente": "⚡",
           "proprete_lente": "🧼", "saletes_lente": "🧹", "xp_passif": "⭐"}
    lignes_p = []
    for pc, (p_emo, p_nom, meubles) in PET_PIECES.items():
        lignes_p.append(f"**{p_emo} {p_nom}**  ·  {sum(1 for m in meubles if m in ref)}/{len(meubles)}")
        for m in meubles:
            v = PET_MEUBLES[m]
            etat = "✅" if m in ref else f"`{v[2]:,}p`"
            lignes_p.append(f"　{v[0]} **{v[1]}** — {etat} · {EFF[v[3]]}+{v[4]}")
    e = discord.Embed(title="🪑  Meubles du refuge",
        description=f"*{len(ref)}/{len(PET_MEUBLES)} installés.*\n💰 **{solde:,} pièces**",
        color=0x1abc9c)
    bloc, taille = [], 0
    for l in lignes_p:
        if taille + len(l) > 950:
            e.add_field(name="\u200b", value="\n".join(bloc), inline=False)
            bloc, taille = [], 0
        bloc.append(l); taille += len(l) + 1
    if bloc:
        e.add_field(name="\u200b", value="\n".join(bloc), inline=False)
    e.set_footer(text="`.refuge acheter <meuble>` · `.refuge` pour visiter la maison")
    pages.append(("🪑", "Meubles", e))

    # ── 👗 Accessoires ──
    porte = set(pst.get("garderobe", [])) if pst else set()
    LAB = {"humeur": "❤️", "coins": "💰", "xp": "⭐", "roll": "🎰"}
    e = discord.Embed(title="👗  Accessoires",
        description=("*Visibles à côté de son nom partout. Trois portés maximum.*\n"
                     f"💰 **{solde:,} pièces**"), color=0xff6fd8)
    lignes = [f"{v[0]} **{k}** — " + ("✅ possédé" if k in porte else f"{v[2]:,} p")
              + f" · {LAB[v[3]]}+{v[4]} %" for k, v in PET_ACCESSOIRES.items()]
    for i in range(0, len(lignes), 6):
        e.add_field(name="\u200b" if i else "🛍️ Garde-robe",
                    value="\n".join(lignes[i:i+6]), inline=False)
    e.set_footer(text="`.garderobe acheter <objet>` · `.garderobe porter <objet>`")
    pages.append(("👗", "Accessoires", e))

    # ── 🎁 Cadeaux ──
    e = discord.Embed(title="🎁  Cadeaux",
        description=f"*À offrir au compagnon d'un ami.*\n💰 **{solde:,} pièces**", color=0xf1c40f)
    e.add_field(name="🎁 À offrir", value=(
        "🍖 **Friandise** — 400 p · ❤️ humeur +20\n"
        "🧸 **Jouet** — 700 p · ⭐ +60 XP\n"
        "🌸 **Fleur** — 300 p · ❤️ humeur +15\n"
        "🎂 **Gâteau** — 1 200 p · ❤️ humeur +35\n"
        "📿 **Collier** — 1 500 p · 💖 relation +2\n\n"
        "*Tu peux aussi offrir n'importe quel accessoire de la garde-robe.*"), inline=False)
    e.set_footer(text="`.petcadeau @ami <objet>` pour offrir")
    pages.append(("🎁", "Cadeaux", e))
    return pages

class PetShopView(ui.View):
    """Navigation par flèches + menu déroulant, comme le help"""
    def __init__(self, pages, author, timeout=240):
        super().__init__(timeout=timeout)
        self.pages, self.author, self.i = pages, author, 0
        opts = [discord.SelectOption(label=nom[:100], emoji=emo, value=str(k))
                for k, (emo, nom, _) in enumerate(pages)][:25]
        sel = ui.Select(placeholder="📂 Choisis un rayon…", options=opts, row=0)
        async def choisir(interaction):
            if interaction.user.id != self.author.id:
                return await interaction.response.send_message("❌ Ce n'est pas ton menu !", ephemeral=True)
            self.i = int(sel.values[0])
            await self.maj(interaction)
        sel.callback = choisir
        self.add_item(sel)
        self.select = sel

    def _embed(self):
        e = self.pages[self.i][2]
        base = e.footer.text or ""
        base = base.split("  ·  Page")[0]
        e.set_footer(text=f"{base}  ·  Page {self.i+1}/{len(self.pages)}")
        return e

    async def maj(self, interaction):
        for opt in self.select.options:
            opt.default = (int(opt.value) == self.i)
        await interaction.response.edit_message(embed=self._embed(), view=self)

    async def interaction_check(self, interaction):
        if interaction.user.id != self.author.id:
            await interaction.response.send_message("❌ Ce n'est pas ton menu !", ephemeral=True)
            return False
        return True

    @ui.button(emoji="⏮️", style=discord.ButtonStyle.secondary, row=1)
    async def debut(self, interaction, button):
        self.i = 0
        await self.maj(interaction)

    @ui.button(emoji="◀️", style=discord.ButtonStyle.primary, row=1)
    async def prec(self, interaction, button):
        self.i = (self.i - 1) % len(self.pages)
        await self.maj(interaction)

    @ui.button(emoji="▶️", style=discord.ButtonStyle.primary, row=1)
    async def suiv(self, interaction, button):
        self.i = (self.i + 1) % len(self.pages)
        await self.maj(interaction)

    @ui.button(emoji="⏭️", style=discord.ButtonStyle.secondary, row=1)
    async def fin(self, interaction, button):
        self.i = len(self.pages) - 1
        await self.maj(interaction)


@bot.command(name="petinventaire", aliases=["petinv", "petsac"])
async def petinventaire_cmd(ctx):
    """Tout ce que tu possèdes pour ton compagnon — .petinventaire"""
    uid = str(ctx.author.id)
    pid, pdb, pst = get_active_pet(uid)
    migrer_inventaire_pet(uid)
    rattrapes = migrer_objets_perdus(uid)
    if rattrapes:
        save_all_data()
    par = inventaire_par_cat(uid)

    e = discord.Embed(
        title=f"🎒 Ton inventaire" + (f" — {pst.get('surnom') or pdb['nom']}" if pid else ""),
        color=0xf1c40f)
    total = 0
    for cat, (c_emo, c_nom, cmd) in CAT_INVENTAIRE.items():
        lot = par.get(cat, [])
        if not lot:
            continue
        total += sum(x[2] for x in lot)
        lignes = []
        for oid, f, n in sorted(lot, key=lambda x: x[1]["nom"])[:14]:
            q = f" ×{n}" if f["stack"] and n > 1 else ""
            lignes.append(f"{f['emoji']} **{f['nom']}**{q}")
        val = "  ·  ".join(lignes)
        if len(lot) > 14:
            val += f"\n*…et {len(lot)-14} autre(s)*"
        if cmd:
            val += f"\n➡️ `.{cmd}`"
        e.add_field(name=f"{c_emo} {c_nom}  ·  {len(lot)}", value=val[:1024], inline=False)

    if not total:
        e.description = ("*Ton inventaire est vide.*\n\n"
                         "`.petshop` pour acheter de la nourriture, des jouets ou des accessoires.")
    else:
        e.description = f"**{total}** objet(s) au total"
    if rattrapes:
        e.set_footer(text=f"🔧 {rattrapes} objet(s) manquant(s) ont été récupérés automatiquement")
    else:
        e.set_footer(text="`.petreparer` si un objet acheté n'apparaît pas")
    await ctx.send(embed=e)

