FOYER_PALIERS = [(0,"🌱","Premiers liens"),(25,"💛","Proches"),
                 (50,"💕","Complices"),(75,"💞","Inséparables"),(95,"👑","Âmes sœurs")]

def foyer_palier(c_):
    emo, nom = "🌱", "Premiers liens"
    for seuil, e, n in FOYER_PALIERS:
        if c_ >= seuil: emo, nom = e, n
    return emo, nom

