class SSVoteView(ui.View):
    """Vote par menu déroulant, éphémère, modifiable jusqu'à la fermeture."""

    def __init__(self, manche, participants):
        super().__init__(timeout=None)
        self.manche = manche
        opts = [discord.SelectOption(label=m.display_name[:90], value=str(m.id))
                for m in participants[:25]]
        s = ui.Select(placeholder="Qui se cache derrière ce secret ?", options=opts)
        s.callback = self._voter
        self.select = s
        self.add_item(s)

    async def _voter(self, itx):
        try:
            m = self.manche
            if m.get("etat") != "VOTING":
                return await itx.response.send_message(
                    "🔔 Les votes sont fermés.", ephemeral=True)
            uid = str(itx.user.id)
            cible = self.select.values[0]
            ancien = m["votes"].get(uid)
            if ancien == cible:
                return await itx.response.send_message(
                    "🔔 C'est déjà ton vote.", ephemeral=True)
            m["votes"][uid] = cible
            if ancien is not None:
                m.setdefault("a_change", set()).add(uid)
            m.setdefault("horodatage", {})[uid] = time.time()
            nom = (itx.guild.get_member(int(cible)).display_name
                   if itx.guild and itx.guild.get_member(int(cible)) else "ce membre")
            await itx.response.send_message(
                f"🕵️ Ton vote est enregistré sur **{nom}**."
                + ("\n*Tu peux encore en changer.*" if ancien is None else "\n*Vote modifié.*"),
                ephemeral=True)
        except (discord.NotFound, discord.HTTPException, discord.InteractionResponded):
            pass
        except Exception as e:
            print(f"[SS] vote : {type(e).__name__}: {e}")


class SSRegieMancheView(ui.View):
    """Après une révélation : enchaîner ou terminer. Réservé aux admins."""

    def __init__(self, ctx_guild, salon):
        super().__init__(timeout=1800)
        self.guild, self.salon = ctx_guild, salon
        self.verrou = False
        self.fait = None
        if not ss_disponibles():
            self.suivant.disabled = True

    async def interaction_check(self, itx):
        if not itx.user.guild_permissions.administrator:
            await itx.response.send_message("👁️ Seule la régie décide.", ephemeral=True)
            return False
        return True

    @ui.button(label="Secret suivant", emoji="▶️", style=discord.ButtonStyle.success)
    async def suivant(self, itx, button):
        if self.verrou or self.fait:
            try:
                if not itx.response.is_done():
                    await itx.response.defer()
            except Exception:
                pass
            return
        self.verrou = True
        self.fait = "suivant"
        try:
            for x in self.children:
                x.disabled = True
            if not itx.response.is_done():
                await itx.response.edit_message(view=self)
            self.stop()
            await ss_jouer_manche(self.guild, self.salon)
        except Exception as e:
            print(f"[SS] manche suivante : {type(e).__name__}: {e}")
        finally:
            self.verrou = False

    @ui.button(label="Terminer l'émission", emoji="⏹️", style=discord.ButtonStyle.danger)
    async def terminer(self, itx, button):
        if self.verrou or self.fait:
            try:
                if not itx.response.is_done():
                    await itx.response.defer()
            except Exception:
                pass
            return
        self.verrou = True
        self.fait = "fin"
        try:
            for x in self.children:
                x.disabled = True
            if not itx.response.is_done():
                await itx.response.edit_message(view=self)
            self.stop()
            await ss_terminer(self.salon)
        except Exception as e:
            print(f"[SS] fin d'émission : {type(e).__name__}: {e}")
        finally:
            self.verrou = False

class SortieView(ui.View):
    """Déroule n'importe quelle activité de ACTIVITES_V2 : scènes → choix → fin."""

    def __init__(self, ctx, uid, cle):
        super().__init__(timeout=180)
        self.ctx, self.uid, self.cle = ctx, uid, cle
        self.act = ACTIVITES_V2[cle]
        self.etape = 0
        self.choix = set()
        self.fin = None
        self.verrou = False
        self.construire()

    async def interaction_check(self, itx):
        if itx.user.id != self.ctx.author.id:
            await itx.response.send_message("🐾 Ce n'est pas ta sortie !", ephemeral=True)
            return False
        return True

    def _nom(self):
        pid, pdb, pst = get_active_pet(self.uid)
        return (pst or {}).get("surnom") or (pdb or {}).get("nom", "Ton compagnon")

    def construire(self):
        self.clear_items()
        if self.fin is not None or self.etape >= len(self.act["scenes"]):
            return
        sc = self.act["scenes"][self.etape]
        for i, (cle, emo, lab, trait_req) in enumerate(sc["choix"]):
            if trait_req and not pet_a_trait(self.uid, trait_req):
                continue
            b = ui.Button(label=lab.format(nom=self._nom())[:78], emoji=emo,
                          style=discord.ButtonStyle.secondary, row=i // 3)
            async def cb(itx, _c=cle):
                await self.choisir(itx, _c)
            b.callback = cb
            self.add_item(b)

    async def choisir(self, itx, cle):
        # L'activité est terminée : plus aucun clic ne compte
        if self.fin is not None or self.etape >= len(self.act["scenes"]):
            try:
                if not itx.response.is_done():
                    await itx.response.defer()
            except Exception:
                pass
            return
        # Verrou : un spam de clics ne doit jamais produire deux avancées
        if self.verrou:
            try:
                if not itx.response.is_done():
                    await itx.response.defer()
            except Exception:
                pass
            return
        self.verrou = True
        try:
            self.choix.add(cle)
            self.etape += 1
            if self.etape >= len(self.act["scenes"]):
                self.resoudre()
                self.stop()
            self.construire()
            if not itx.response.is_done():
                await itx.response.edit_message(embed=self.embed(), view=self)
        except (discord.NotFound, discord.HTTPException, discord.InteractionResponded):
            pass
        except Exception as e:
            print(f"[Activite] {type(e).__name__}: {e}")
        finally:
            self.verrou = False

    def resoudre(self):
        """Tire une fin éligible, pondérée, en tenant compte des traits."""
        uid = self.uid
        pid, pdb, pst = get_active_pet(uid)
        eligibles = []
        for f in self.act["fins"]:
            besoin = f.get("si") or set()
            if not besoin <= self.choix:
                continue
            poids = f.get("p", 20)
            tr = f.get("trait")
            if tr:
                poids = poids * 3 if pet_a_trait(uid, tr) else max(1, poids // 3)
            eligibles.append((f, poids))
        if not eligibles:
            eligibles = [(f, f.get("p", 20)) for f in self.act["fins"] if not f.get("si")]
        if not eligibles:
            eligibles = [(self.act["fins"][0], 1)]
        # Anti-répétition : on évite les fins vues récemment
        textes = [f["t"] for f, _ in eligibles]
        recent = set(pets_data.get(uid, {}).get("vu_fins", {}).get(self.cle, []))
        # Une fin vue récemment devient très improbable, sans jamais être impossible
        pond = [(f, max(1, p // 8) if f["t"] in recent else p * 6) for f, p in eligibles]
        tot = sum(p for _, p in pond)
        x, cum = random.randint(1, max(1, tot)), 0
        choisie = pond[-1][0]
        for f, p in pond:
            cum += p
            if x <= cum:
                choisie = f
                break
        self.fin = choisie
        vu = pets_data.setdefault(uid, {}).setdefault("vu_fins", {}).setdefault(self.cle, [])
        vu.insert(0, choisie["t"])
        del vu[4:]

        # ── Effets ──
        st = pet_etat(uid)
        self.gains = {}
        for k, v in (choisie.get("eff") or {}).items():
            if k in st:
                st[k] = max(0, min(100, st[k] + v))
                lib = {"humeur": "😊 Humeur", "energie": "⚡ Énergie",
                       "proprete": "🛁 Propreté", "faim": "🍖 Faim"}.get(k, k)
                self.gains[lib] = f"{v:+d}"
        if choisie.get("obj"):
            activite_donner_objet(uid, choisie["obj"])
            self.gains["🎁 Objet"] = choisie["obj"]
        if choisie.get("comp"):
            pet_stat(uid, choisie["comp"])
            self.gains["🎯 Compétence"] = choisie["comp"].capitalize()
        if choisie.get("souvenir"):
            pet_carnet_note(uid, f"{self.act['emoji']} {choisie['t'].format(nom=self._nom())[:110]}",
                            important=True)
            self.gains["📖 Souvenir"] = "enregistré"
        give_pet_xp(uid, 10)
        pst.setdefault("gouts_act", {}).setdefault("act", {})
        pst["gouts_act"]["act"][self.cle] = pst["gouts_act"]["act"].get(self.cle, 0) + 1
        pet_stat(uid, "sorties")
        save_all_data()

    def embed(self):
        nom = self._nom()
        a = self.act
        if self.fin is not None:
            e = discord.Embed(title=f"{a['emoji']}  {a['nom']}",
                              description=f"*« {self.fin['t'].format(nom=nom)} »*",
                              color=0x1abc9c)
            if getattr(self, "gains", None):
                e.add_field(name="\u200b",
                            value="\n".join(f"{k} **{v}**" for k, v in self.gains.items()),
                            inline=False)
            e.set_footer(text="`.petensemble` pour une autre sortie")
            return e
        sc = a["scenes"][self.etape]
        desc = (f"*{a['intro'].format(nom=nom)}*\n\n" if self.etape == 0 else "")
        desc += f"**{sc['q'].format(nom=nom)}**"
        e = discord.Embed(title=f"{a['emoji']}  {a['nom']}", description=desc, color=0x1abc9c)
        e.set_footer(text=f"Étape {self.etape + 1} sur {len(a['scenes'])}")
        return e

class DuoView(ui.View):
    """Une activité de duo : deux pets partenaires, scène → choix → issue."""

    def __init__(self, ctx, uid, partenaire, cle):
        super().__init__(timeout=180)
        self.ctx, self.uid, self.pid_b, self.cle = ctx, uid, partenaire, cle
        self.act = DUO_ACTIVITES[cle]
        self.fin = None
        self.verrou = False
        self.construire()

    async def interaction_check(self, itx):
        # Les deux propriétaires du foyer peuvent participer
        if str(itx.user.id) not in (self.uid, self.pid_b):
            await itx.response.send_message("❤️ Ce foyer n'est pas le tien !", ephemeral=True)
            return False
        return True

    def noms(self):
        _, pdb_a, pst_a = get_active_pet(self.uid)
        _, pdb_b, pst_b = get_active_pet(self.pid_b)
        a = (pst_a or {}).get("surnom") or (pdb_a or {}).get("nom", "Son compagnon")
        b = (pst_b or {}).get("surnom") or (pdb_b or {}).get("nom", "L'autre")
        return a, b, pst_a or {}, pst_b or {}

    def construire(self):
        self.clear_items()
        if self.fin is not None:
            return
        a, b, _, _ = self.noms()
        for i, (cle, emo, lab) in enumerate(self.act["choix"]):
            btn = ui.Button(label=lab.format(a=a, b=b)[:78], emoji=emo,
                            style=discord.ButtonStyle.secondary, row=i // 3)
            async def cb(itx, _c=cle):
                await self.choisir(itx, _c)
            btn.callback = cb
            self.add_item(btn)

    async def choisir(self, itx, cle):
        if self.fin is not None or self.verrou:
            try:
                if not itx.response.is_done():
                    await itx.response.defer()
            except Exception:
                pass
            return
        self.verrou = True
        try:
            self.resoudre(cle)
            self.stop()
            self.construire()
            if not itx.response.is_done():
                await itx.response.edit_message(embed=self.embed(), view=self)
        except (discord.NotFound, discord.HTTPException, discord.InteractionResponded):
            pass
        except Exception as e:
            print(f"[Duo] {type(e).__name__}: {e}")
        finally:
            self.verrou = False

    def resoudre(self, choix):
        a, b, pst_a, pst_b = self.noms()
        elig = []
        for f in self.act["fins"]:
            if (f.get("si") or set()) - {choix}:
                continue
            p = f.get("p", 20)
            if f.get("trait_a"):
                p = p * 3 if f["trait_a"] in (pst_a.get("traits") or []) else max(1, p // 3)
            if f.get("trait_b"):
                p = p * 3 if f["trait_b"] in (pst_b.get("traits") or []) else max(1, p // 3)
            elig.append((f, p))
        if not elig:
            elig = [(f, f.get("p", 20)) for f in self.act["fins"] if not f.get("si")] or \
                   [(self.act["fins"][0], 1)]
        vus = set(get_foyer(self.uid, self.pid_b, creer=True).get("vus", []))
        pond = [(f, max(1, p // 8) if f["t"] in vus else p * 6) for f, p in elig]
        tot = sum(p for _, p in pond)
        x, cum = random.randint(1, max(1, tot)), 0
        self.fin = pond[-1][0]
        for f, p in pond:
            cum += p
            if x <= cum:
                self.fin = f
                break
        fo = get_foyer(self.uid, self.pid_b, creer=True)
        fo.setdefault("vus", []).insert(0, self.fin["t"])
        del fo["vus"][4:]
        # Effets — complicité, souvenir, objet. Aucune pièce.
        gain = self.fin.get("c", 5)
        texte = self.fin["t"].format(a=a, b=b)
        duo_maj_complicite(self.uid, self.pid_b, gain,
                           souvenir=texte if self.fin.get("souvenir") else None)
        for u in (self.uid, self.pid_b):
            st = pet_etat(u)
            if st:
                st["humeur"] = max(0, min(100, st["humeur"] + max(2, gain // 2)))
        if self.fin.get("obj"):
            activite_donner_objet(self.uid, self.fin["obj"])
        fo["activites"] = fo.get("activites", {})
        fo["activites"][self.cle] = fo["activites"].get(self.cle, 0) + 1
        import time as _t
        fo.setdefault("cd", {})[self.cle] = _t.time()
        save_all_data()
        self.gain = gain
        self.texte = texte

    def embed(self):
        a, b, _, _ = self.noms()
        act = self.act
        if self.fin is None:
            e = discord.Embed(
                title=f"{act['emoji']}  {act['nom']}",
                description=f"*{act['intro'].format(a=a, b=b)}*\n\n**{act['q']}**",
                color=0xff9ec7)
            return e
        f = get_foyer(self.uid, self.pid_b) or {}
        emo_p, nom_p = foyer_palier(f.get("complicite", 50))
        e = discord.Embed(title=f"{act['emoji']}  {act['nom']}",
                          description=f"*« {self.texte} »*", color=0xff9ec7)
        lignes = [f"💕 Complicité **+{self.gain}**   ·   {emo_p} {nom_p}"]
        if self.fin.get("obj"):
            lignes.append(f"🎁 **{self.fin['obj']}**")
        if self.fin.get("souvenir"):
            lignes.append("📖 Souvenir ajouté à l'album")
        e.add_field(name="\u200b", value="\n".join(lignes), inline=False)
        return e


class FrictionView(ui.View):
    """Une petite friction de couple — ton léger, jamais punitif."""

    def __init__(self, ctx, uid, partenaire, friction):
        super().__init__(timeout=180)
        self.ctx, self.uid, self.pid_b, self.fr = ctx, uid, partenaire, friction
        self.fait = None
        self.verrou = False
        a, b = self.noms()
        for i, (cle, emo, lab, gain) in enumerate(friction["choix"]):
            btn = ui.Button(label=lab.format(a=a, b=b)[:78], emoji=emo,
                            style=discord.ButtonStyle.secondary, row=i // 3)
            async def cb(itx, _c=cle, _g=gain, _l=lab):
                await self.choisir(itx, _c, _g, _l)
            btn.callback = cb
            self.add_item(btn)

    def noms(self):
        _, pdb_a, pst_a = get_active_pet(self.uid)
        _, pdb_b, pst_b = get_active_pet(self.pid_b)
        return ((pst_a or {}).get("surnom") or (pdb_a or {}).get("nom", "L'un"),
                (pst_b or {}).get("surnom") or (pdb_b or {}).get("nom", "L'autre"))

    async def interaction_check(self, itx):
        if str(itx.user.id) not in (self.uid, self.pid_b):
            await itx.response.send_message("❤️ Ce foyer n'est pas le tien !", ephemeral=True)
            return False
        return True

    async def choisir(self, itx, cle, gain, lab):
        if self.fait is not None or self.verrou:
            try:
                if not itx.response.is_done():
                    await itx.response.defer()
            except Exception:
                pass
            return
        self.verrou = True
        try:
            self.fait = (cle, gain, lab)
            duo_maj_complicite(self.uid, self.pid_b, gain)
            save_all_data()
            self.clear_items()
            self.stop()
            if not itx.response.is_done():
                await itx.response.edit_message(embed=self.embed(), view=self)
        except (discord.NotFound, discord.HTTPException, discord.InteractionResponded):
            pass
        finally:
            self.verrou = False

    def embed(self):
        a, b = self.noms()
        if self.fait is None:
            return discord.Embed(title="😅  Petite tension",
                                 description=f"*{self.fr['t'].format(a=a, b=b)}*",
                                 color=0xffc4d6)
        cle, gain, lab = self.fait
        f = get_foyer(self.uid, self.pid_b) or {}
        emo_p, nom_p = foyer_palier(f.get("complicite", 50))
        e = discord.Embed(title="😅  Petite tension",
                          description=f"*{self.fr['t'].format(a=a, b=b)}*\n\n"
                                      f"→ **{lab.format(a=a, b=b)}**", color=0xffc4d6)
        e.add_field(name="\u200b",
                    value=f"💕 Complicité **{gain:+d}**   ·   {emo_p} {nom_p}", inline=False)
        return e


class BebeView(ui.View):
    """S'occuper du bébé : soins variés, éducation, passage à l'âge adulte."""

    def __init__(self, ctx, uid, pid):
        super().__init__(timeout=300)
        self.ctx, self.uid, self.pid = ctx, uid, pid
        self.msg = None
        self.education = None
        self.verrou = False
        self.construire()

    def st(self):
        return pets_data.get(self.uid, {}).get("owned", {}).get(self.pid, {})

    def nom(self):
        return self.st().get("nom_bebe") or "Le petit"

    async def interaction_check(self, itx):
        st = self.st()
        proprios = {self.uid, str(st.get("parent_a", "")), str(st.get("parent_b", ""))}
        if str(itx.user.id) not in proprios:
            await itx.response.send_message("👶 Ce n'est pas ton petit !", ephemeral=True)
            return False
        return True

    def construire(self):
        self.clear_items()
        st = self.st()
        if self.education is not None:
            conf = BEBE_EDUCATION[self.education]
            for i, (cle, emo, lab, _tr) in enumerate(conf["choix"]):
                b = ui.Button(label=lab[:78], emoji=emo,
                              style=discord.ButtonStyle.success, row=i)
                async def cb(itx, _c=cle):
                    await self.decider(itx, _c)
                b.callback = cb
                self.add_item(b)
            return
        if bebe_phase(st)[0] >= len(BEBE_PHASES) - 1 and not st.get("adulte"):
            b = ui.Button(label="Il est prêt à grandir", emoji="👑",
                          style=discord.ButtonStyle.success, row=0)
            async def cbg(itx):
                await self.grandir(itx)
            b.callback = cbg
            self.add_item(b)
            return
        for i, (cle, (emo, lab)) in enumerate(BEBE_ACTIONS.items()):
            b = ui.Button(label=lab, emoji=emo, style=discord.ButtonStyle.secondary, row=i // 3)
            async def cb(itx, _c=cle):
                await self.soigner(itx, _c)
            b.callback = cb
            self.add_item(b)

    async def _editer(self, itx):
        try:
            if not itx.response.is_done():
                await itx.response.edit_message(embed=self.embed(), view=self)
        except (discord.NotFound, discord.HTTPException, discord.InteractionResponded):
            pass

    async def soigner(self, itx, action):
        if self.verrou:
            try:
                if not itx.response.is_done():
                    await itx.response.defer()
            except Exception:
                pass
            return
        self.verrou = True
        try:
            st = self.st()
            avant = bebe_phase(st)[0]
            pts, msg = bebe_soin(st, action)
            self.dernier_msg = msg or random.choice([
                f"{self.nom()} apprécie beaucoup ce moment.",
                f"{self.nom()} te regarde avec de grands yeux.",
                f"{self.nom()} se blottit contre toi juste après.",
                f"{self.nom()} pousse un petit bruit satisfait.",
                f"{self.nom()} en redemande immédiatement."])
            # L'éducation se débloque dès que les SOINS d'un palier sont atteints
            # et que la VARIÉTÉ est suffisante. C'est elle qui fournit l'apprentissage
            # exigé par la phase correspondante.
            if pts and len(st.get("types", {})) >= BEBE_TYPES_REQUIS:
                deja = st.get("choix") or {}
                for _ph in sorted(BEBE_EDUCATION):
                    if str(_ph) in deja:
                        continue
                    if st.get("soins", 0) >= BEBE_PHASES[_ph][2]:
                        self.education = _ph
                    break
            save_all_data()
            self.construire()
            await self._editer(itx)
        finally:
            self.verrou = False

    async def decider(self, itx, cle):
        """Un seul parent décide — la décision n'est jamais appliquée deux fois."""
        if self.verrou:
            try:
                if not itx.response.is_done():
                    await itx.response.defer()
            except Exception:
                pass
            return
        self.verrou = True
        try:
            phase = self.education
            trait = bebe_appliquer_education(self.uid, self.pid, phase, cle)
            st = self.st()
            st["phase_maj"] = __import__("time").time()
            self.education = None
            self.dernier_msg = (f"Ce choix a marqué {self.nom()}." if trait is None
                                else f"{self.nom()} devient un peu plus **{trait}**.")
            save_all_data()
            self.construire()
            await self._editer(itx)
        finally:
            self.verrou = False

    async def grandir(self, itx):
        if self.verrou:
            try:
                if not itx.response.is_done():
                    await itx.response.defer()
            except Exception:
                pass
            return
        self.verrou = True
        try:
            ok = bebe_devenir_adulte(self.uid, self.pid)
            self.dernier_msg = (f"🎉 **{self.nom()}** est devenu adulte !" if ok
                                else f"{self.nom()} est déjà adulte.")
            save_all_data()
            self.construire()
            await self._editer(itx)
        finally:
            self.verrou = False

    def embed(self):
        st = self.st()
        idx, emo, nom_ph, desc = bebe_phase(st)
        fiche = pet_espece(self.uid, self.pid) or {}
        e = discord.Embed(title=f"{fiche.get('emoji', '🐾')}  {self.nom()}",
                          color=0xffd479)
        if self.education is not None:
            conf = BEBE_EDUCATION[self.education]
            e.title = conf["titre"]
            e.description = f"*{conf['texte'].format(n=self.nom())}*\n\n**Comment réagis-tu ?**"
            return e
        if st.get("adulte"):
            e.description = f"### 👑 Adulte\n*{desc}*"
        else:
            cur, req, suiv = bebe_progression(st)
            barre = jauge5(int(cur / max(1, req) * 100))
            e.description = f"{emo} **{nom_ph}** · étape {idx + 1} sur 4\n\n🌱 {barre}  **{cur} / {req}**"
        # Héritage
        par = st.get("parents") or {}
        if par:
            e.add_field(name="🧬 Héritage",
                        value=f"{par.get('a', '?')}  ·  {par.get('b', '?')}", inline=False)
        tr = st.get("traits") or []
        if tr:
            e.add_field(name="🎭 Caractère",
                        value=" · ".join(PET_TRAITS[t][1] if t in PET_TRAITS else t for t in tr),
                        inline=False)
        gouts = st.get("gouts") or {}
        if gouts:
            aime = [k for k, v in gouts.items() if v > 0][:2]
            deteste = [k for k, v in gouts.items() if v < 0][:1]
            txt = []
            if aime: txt.append("🍓 Aime : " + ", ".join(aime))
            if deteste: txt.append("🥦 Déteste : " + ", ".join(deteste))
            if txt: e.add_field(name="\u200b", value="\n".join(txt), inline=False)
        if st.get("particularite") and st.get("part_decouverte"):
            p = PET_PARTICULARITES.get(st["particularite"])
            if p: e.add_field(name="✨ Particularité", value=f"{p[0]} **{p[1]}**", inline=False)
        if not st.get("adulte"):
            manque = bebe_manque(st)
            if manque:
                e.add_field(name="Il lui faut encore", value=" · ".join(manque), inline=False)
        if getattr(self, "dernier_msg", None):
            e.set_footer(text=self.dernier_msg[:200])
        return e

SS_JOURS = ("lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi", "dimanche")

class SSRegieView(ui.View):
    """Panel admin unique : un message, plusieurs écrans."""

    def __init__(self, ctx):
        super().__init__(timeout=600)
        self.ctx = ctx
        self.ecran = "accueil"
        self.page = 0
        self.msg = None
        self.construire()

    async def interaction_check(self, itx):
        if not itx.user.guild_permissions.administrator:
            await itx.response.send_message("👁️ Régie réservée aux admins.", ephemeral=True)
            return False
        return True

    async def aller(self, itx, ecran, **kw):
        try:
            self.ecran = ecran
            self.page = kw.get("page", 0)
            self.construire()
            emb = self.embed()
        except Exception as e:
            print(f"[SS régie] {ecran} : {type(e).__name__}: {e}")
            emb = discord.Embed(description="😿 Écran indisponible — refais `.secretstory`.",
                                color=0xe74c3c)
            self.clear_items()
        try:
            if not itx.response.is_done():
                await itx.response.edit_message(embed=emb, view=self)
            else:
                await itx.edit_original_response(embed=emb, view=self)
        except (discord.NotFound, discord.HTTPException, discord.InteractionResponded):
            pass

    async def on_timeout(self):
        for x in self.children:
            x.disabled = True

    def _b(self, label, emoji, ecran, row, style=discord.ButtonStyle.secondary):
        b = ui.Button(label=label, emoji=emoji, style=style, row=row)
        async def cb(itx, _e=ecran):
            await self.aller(itx, _e)
        b.callback = cb
        self.add_item(b)

    def construire(self):
        self.clear_items()
        e = self.ecran
        if e == "accueil":
            actif = ss_session_active()
            b = ui.Button(label="Émission en cours" if actif else "Lancer", emoji="▶️",
                          style=discord.ButtonStyle.success, row=0, disabled=actif)
            async def cbl(itx):
                await self.lancer(itx)
            b.callback = cbl
            self.add_item(b)
            bc = ui.Button(label="Fermer la collecte" if SS_CONFIG.get("collecte_ouverte")
                           else "Ouvrir la collecte", emoji="📮", row=0,
                           style=discord.ButtonStyle.primary)
            async def cbc(itx):
                await self.collecte(itx)
            bc.callback = cbc
            self.add_item(bc)
            self._b("Secrets", "🗃️", "secrets", 0)
            self._b("Programmation", "📅", "prog", 1)
            self._b("Statistiques", "📊", "stats", 1)
            return

        if e == "secrets":
            att = ss_en_attente()
            if att:
                opts = [discord.SelectOption(
                    label=f"#{s['id']} · {ss_texte_court(s['texte'], 60)}"[:100],
                    value=str(s["id"]),
                    description=f"par un membre · en attente") for s in att[:25]]
                sel = ui.Select(placeholder="Modérer un secret…", options=opts, row=0)
                async def cbs(itx):
                    self.cible = sel.values[0]
                    await self.aller(itx, "moderer")
                sel.callback = cbs
                self.add_item(sel)
            self._b("Régie", "◀️", "accueil", 1)
            return

        if e == "moderer":
            for lab, emo, act, st in (("Valider", "✅", "validated", discord.ButtonStyle.success),
                                      ("Refuser", "🚫", "rejected", discord.ButtonStyle.danger),
                                      ("Supprimer", "🗑️", "delete", discord.ButtonStyle.danger)):
                b = ui.Button(label=lab, emoji=emo, style=st, row=0)
                async def cb(itx, _a=act):
                    await self.moderer(itx, _a)
                b.callback = cb
                self.add_item(b)
            self._b("Secrets", "◀️", "secrets", 1)
            return

        if e == "prog":
            opts = [discord.SelectOption(label="Manuel uniquement", value="off", emoji="🔴",
                                         description="Aucun lancement automatique"),
                    discord.SelectOption(label="Hebdomadaire", value="hebdo", emoji="📅",
                                         description="Chaque semaine, jour et heure au choix"),
                    discord.SelectOption(label="Mensuelle", value="mensuel", emoji="🗓️",
                                         description="Chaque mois, jour et heure au choix")]
            sel = ui.Select(placeholder="Mode de programmation…", options=opts, row=0)
            async def cbp(itx):
                SS_CONFIG["mode"] = sel.values[0]
                save_all_data()
                await self.aller(itx, "prog")
            sel.callback = cbp
            self.add_item(sel)
            if SS_CONFIG.get("mode") == "hebdo":
                jopts = [discord.SelectOption(label=j.capitalize(), value=str(i))
                         for i, j in enumerate(SS_JOURS)]
                sj = ui.Select(placeholder="Jour de la semaine…", options=jopts, row=1)
                async def cbj(itx):
                    SS_CONFIG["jour"] = int(sj.values[0]); save_all_data()
                    await self.aller(itx, "prog")
                sj.callback = cbj
                self.add_item(sj)
            elif SS_CONFIG.get("mode") == "mensuel":
                jopts = [discord.SelectOption(label=f"Le {d}", value=str(d))
                         for d in (1, 5, 10, 15, 20, 25, 28)]
                sj = ui.Select(placeholder="Jour du mois…", options=jopts, row=1)
                async def cbj(itx):
                    SS_CONFIG["jour"] = int(sj.values[0]); save_all_data()
                    await self.aller(itx, "prog")
                sj.callback = cbj
                self.add_item(sj)
            if SS_CONFIG.get("mode") in ("hebdo", "mensuel"):
                hopts = [discord.SelectOption(label=f"{h:02d}h00", value=str(h))
                         for h in (12, 14, 16, 18, 19, 20, 21, 22, 23)]
                sh = ui.Select(placeholder="Heure…", options=hopts, row=2)
                async def cbh(itx):
                    SS_CONFIG["heure"] = int(sh.values[0]); save_all_data()
                    await self.aller(itx, "prog")
                sh.callback = cbh
                self.add_item(sh)
            self._b("Régie", "◀️", "accueil", 3)
            return

        if e in ("stats", "collecte_ok"):
            self._b("Régie", "◀️", "accueil", 1)

    # ── Actions ──
    async def lancer(self, itx):
        try:
            if not itx.response.is_done():
                await itx.response.defer()
            ok, res = await ss_lancer(itx.guild)
            if not ok:
                await itx.followup.send(f"❌ {res}", ephemeral=True)
        except Exception as e:
            print(f"[SS] lancement : {type(e).__name__}: {e}")

    async def collecte(self, itx):
        try:
            ouvrir = not SS_CONFIG.get("collecte_ouverte")
            SS_CONFIG["collecte_ouverte"] = ouvrir
            save_all_data()
            if ouvrir:
                salon = (itx.guild.get_channel(SS_CONFIG.get("salon")) if SS_CONFIG.get("salon")
                         else None) or itx.channel
                await salon.send(embed=discord.Embed(
                    title="👁️  SECRET STORY OUVRE SES PORTES",
                    description=("La Voix veut connaître vos secrets…\n\n"
                                 "🔒 *Votre identité restera cachée pendant l'enquête.*"),
                    color=0x2c2f33), view=SSCollecteView())
            await self.aller(itx, "accueil")
        except Exception as e:
            print(f"[SS] collecte : {type(e).__name__}: {e}")

    async def moderer(self, itx, action):
        try:
            sid = str(getattr(self, "cible", ""))
            s = SS_SECRETS.get(sid)
            if s:
                if action == "delete":
                    SS_SECRETS.pop(sid, None)
                else:
                    s["statut"] = action
                save_all_data()
            await self.aller(itx, "secrets")
        except Exception as e:
            print(f"[SS] modération : {type(e).__name__}: {e}")

    # ── Écrans ──
    def embed(self):
        e = self.ecran
        if e == "secrets":
            att = ss_en_attente()
            emb = discord.Embed(title="🗃️  Secrets en attente", color=0x9b59b6)
            emb.description = ("\n".join(
                f"**#{s['id']}** — <@{s['owner']}>\n> *{ss_texte_court(s['texte'], 90)}*"
                for s in att[:8]) if att else "*Aucun secret à modérer.*")
            emb.set_footer(text="L'auteur n'est visible que par la régie")
            return emb
        if e == "moderer":
            s = SS_SECRETS.get(str(getattr(self, "cible", "")))
            emb = discord.Embed(title=f"🗃️  Secret #{s['id'] if s else '?'}", color=0x9b59b6)
            if s:
                emb.description = f"> *« {s['texte']} »*"
                emb.add_field(name="Auteur", value=f"<@{s['owner']}>", inline=True)
                emb.add_field(name="Déposé",
                              value=f"<t:{int(s['depot'])}:R>", inline=True)
            return emb
        if e == "prog":
            mode = SS_CONFIG.get("mode", "off")
            lib = {"off": "🔴 Manuel uniquement", "hebdo": "📅 Hebdomadaire",
                   "mensuel": "🗓️ Mensuelle"}[mode]
            emb = discord.Embed(title="📅  Programmation", color=0x3498db)
            txt = [f"Mode actuel : **{lib}**"]
            if mode == "hebdo":
                txt.append(f"Chaque **{SS_JOURS[SS_CONFIG.get('jour', 4)]}** "
                           f"à **{SS_CONFIG.get('heure', 21):02d}h00**")
            elif mode == "mensuel":
                txt.append(f"Le **{SS_CONFIG.get('jour', 1)}** de chaque mois "
                           f"à **{SS_CONFIG.get('heure', 21):02d}h00**")
            txt.append("\n-# Le lancement manuel reste toujours possible, sans cooldown.")
            emb.description = "\n".join(txt)
            return emb
        if e == "stats":
            emb = discord.Embed(title="📊  Statistiques Secret Story", color=0x3498db)
            tot_dep = sum(v.get("deposes", 0) for v in SS_STATS.values())
            tot_rev = sum(v.get("reveles", 0) for v in SS_STATS.values())
            tot_g = sum(v.get("gains", 0) for v in SS_STATS.values())
            emb.description = (f"📮 **{len(ss_disponibles())}** secret(s) en réserve\n"
                               f"🔒 **{tot_dep}** déposé(s) au total\n"
                               f"🎬 **{tot_rev}** révélé(s)\n"
                               f"💰 **{tot_g:,}** pièces distribuées".replace(",", " "))
            top = sorted(SS_STATS.items(), key=lambda x: -x[1].get("trouves", 0))[:5]
            if top and top[0][1].get("trouves"):
                emb.add_field(name="🔎 Meilleurs enquêteurs",
                              value="\n".join(f"<@{u}> — **{v['trouves']}**"
                                              for u, v in top if v.get("trouves")),
                              inline=False)
            return emb
        # accueil
        mode = SS_CONFIG.get("mode", "off")
        lib = {"off": "🔴 Manuel uniquement", "hebdo": "📅 Hebdomadaire",
               "mensuel": "🗓️ Mensuelle"}[mode]
        if mode == "hebdo":
            lib += f" — {SS_JOURS[SS_CONFIG.get('jour', 4)]} {SS_CONFIG.get('heure', 21):02d}h"
        elif mode == "mensuel":
            lib += f" — le {SS_CONFIG.get('jour', 1)} à {SS_CONFIG.get('heure', 21):02d}h"
        emb = discord.Embed(title="👁️  SECRET STORY — RÉGIE", color=0x2c2f33)
        emb.description = (
            f"📮 Secrets disponibles : **{len(ss_disponibles())}**\n"
            f"📝 À valider : **{len(ss_en_attente())}**\n"
            f"🎬 Émission : **{'en cours' if ss_session_active() else 'aucune'}**"
            + (f" — <#{SS_SESSION['channel_id']}>" if SS_SESSION.get("channel_id") else "") + "\n"
            f"🔒 Confessionnal : **{'ouvert' if SS_CONFIG.get('collecte_ouverte') else 'fermé'}**\n"
            f"📅 Programmation : {lib}")
        emb.set_footer(text="Le lancement manuel est toujours possible")
        return emb


class ChroRegieView(ui.View):
    """Régie Chronique — l'admin pilote, les lecteurs ne voient jamais les coulisses."""

    def __init__(self, ctx):
        super().__init__(timeout=600)
        self.ctx = ctx
        self.ecran = "accueil"
        self.construire()

    async def interaction_check(self, itx):
        if not itx.user.guild_permissions.administrator:
            await itx.response.send_message("📖 Régie réservée aux admins.", ephemeral=True)
            return False
        return True

    async def aller(self, itx, ecran):
        try:
            self.ecran = ecran
            self.construire()
            emb = self.embed()
        except Exception as e:
            print(f"[Chronique régie] {ecran} : {type(e).__name__}: {e}")
            emb = discord.Embed(description="😿 Écran indisponible — refais `.chronique`.",
                                color=0xe74c3c)
            self.clear_items()
        try:
            if not itx.response.is_done():
                await itx.response.edit_message(embed=emb, view=self)
            else:
                await itx.edit_original_response(embed=emb, view=self)
        except (discord.NotFound, discord.HTTPException, discord.InteractionResponded):
            pass

    async def on_timeout(self):
        for x in self.children:
            x.disabled = True

    def _b(self, label, emoji, ecran, row, style=discord.ButtonStyle.secondary):
        b = ui.Button(label=label, emoji=emoji, style=style, row=row)
        async def cb(itx, _e=ecran):
            await self.aller(itx, _e)
        b.callback = cb
        self.add_item(b)

    def construire(self):
        self.clear_items()
        if self.ecran == "accueil":
            etat = CHRONIQUE.get("etat")
            if not chro_active():
                opts = [discord.SelectOption(
                    label=s["titre"], value=k, emoji=s["genre"].split()[0],
                    description=s["accroche"][:95]) for k, s in CHRONIQUE_SAISONS.items()]
                sel = ui.Select(placeholder="Lancer une saison…", options=opts, row=0)
                async def cbs(itx):
                    await self.lancer(itx, sel.values[0])
                sel.callback = cbs
                self.add_item(sel)
            else:
                if etat == "ATTENTE":
                    if CHRONIQUE.get("vote_a_republier"):
                        br = ui.Button(label="Republier le vote", emoji="🔁",
                                       style=discord.ButtonStyle.danger, row=0)
                        async def cbr(itx):
                            await self.republier_vote(itx)
                        br.callback = cbr
                        self.add_item(br)
                    b = ui.Button(label="Publier l'épisode suivant", emoji="▶️",
                                  style=discord.ButtonStyle.success, row=0)
                    async def cbp(itx):
                        await self.publier(itx)
                    b.callback = cbp
                    self.add_item(b)
                elif etat in ("VOTE", "EGALITE"):
                    b = ui.Button(label="Fermer les votes", emoji="🔒",
                                  style=discord.ButtonStyle.primary, row=0)
                    async def cbf(itx):
                        await self.fermer(itx)
                    b.callback = cbf
                    self.add_item(b)
                    if etat == "EGALITE":
                        for g in (CHRONIQUE.get("egalite") or [])[:3]:
                            ep = chro_episode()
                            lib = next((l for c_, e_, l in ep["choix"]["options"] if c_ == g), g)
                            bb = ui.Button(label=f"Trancher : {lib}"[:78], emoji="⚖️", row=1)
                            async def cbt(itx, _g=g):
                                await self.trancher(itx, _g)
                            bb.callback = cbt
                            self.add_item(bb)
                self._b("État de l'histoire", "🧠", "etat", 2)
                b2 = ui.Button(label="Arrêter la saison", emoji="⏹️",
                               style=discord.ButtonStyle.danger, row=2)
                async def cba(itx):
                    await self.arreter(itx)
                b2.callback = cba
                self.add_item(b2)
            return
        self._b("Régie", "◀️", "accueil", 1)

    # ── Actions ──
    async def lancer(self, itx, cle):
        try:
            if not itx.response.is_done():
                await itx.response.defer()
            salon = chro_salon(itx.guild)
            if not salon:
                return await itx.followup.send(
                    "📖 Aucun salon configuré.\nUtilise `.setsalon chronique #salon`.",
                    ephemeral=True)
            async with _CHRO_LOCK:
                if chro_active():
                    return await itx.followup.send("📖 Une saison est déjà en cours.",
                                                   ephemeral=True)
                chro_reset()
                CHRONIQUE.update({"saison": cle, "episode": 1, "etat": "ATTENTE",
                                  "drapeaux": [], "routes_fermees": [], "historique": [],
                                  "publies": [], "votes": {},
                                  "debut": time.time(), "salon": salon.id})
                save_all_data()
            s = CHRONIQUE_SAISONS[cle]
            await salon.send(embed=discord.Embed(
                title=f"📖  {s['titre']}",
                description=(f"### {s['genre']}\n\n*{s['accroche']}*\n\n"
                             f"**{len(s['episodes'])} épisodes.** "
                             f"C'est vous qui écrivez la suite."),
                color=0xff9ec7).add_field(
                    name="Casting",
                    value="\n".join(f"{e} **{n}** — *{d}*"
                                    for e, n, d in list(s["casting"].values())[:6]),
                    inline=False))
            await self.aller(itx, "accueil")
        except Exception as e:
            print(f"[Chronique] lancement : {type(e).__name__}: {e}")

    async def publier(self, itx):
        try:
            if not itx.response.is_done():
                await itx.response.defer()
            ok, res = await chro_publier_episode(itx.guild)
            if not ok:
                await itx.followup.send(f"❌ {res}", ephemeral=True)
            await self.aller(itx, "accueil")
        except Exception as e:
            print(f"[Chronique] publication : {type(e).__name__}: {e}")

    async def republier_vote(self, itx):
        """Republie le vote de l'épisode courant après un échec ou un message perdu."""
        try:
            if not itx.response.is_done():
                await itx.response.defer()
            salon = chro_salon(itx.guild)
            ep = chro_episode()
            choix = (ep or {}).get("choix")
            if not salon or not choix:
                CHRONIQUE.pop("vote_a_republier", None)
                save_all_data()
                return await self.aller(itx, "accueil")
            vue = ChroVoteView(CHRONIQUE.get("episode"), choix)
            try:
                msg = await salon.send(embed=vue.embed(itx.guild), view=vue)
            except Exception as e:
                await itx.followup.send(f"❌ Republication impossible — "
                                        f"{type(e).__name__}", ephemeral=True)
                return
            vue.msg = msg
            CHRONIQUE["msg_vote"] = msg.id
            CHRONIQUE["salon_vote"] = salon.id
            CHRONIQUE.setdefault("votes", {})
            CHRONIQUE["etat"] = "VOTE"
            CHRONIQUE.pop("vote_a_republier", None)
            save_all_data()
            print(f"[Chronique] ✅ vote republié · message_id={msg.id}")
            await self.aller(itx, "accueil")
        except Exception as e:
            print(f"[Chronique] republication : {type(e).__name__}: {e}")

    async def fermer(self, itx):
        try:
            if not itx.response.is_done():
                await itx.response.defer()
            ok, res = await chro_fermer_vote(itx.guild)
            if not ok:
                await itx.followup.send(f"⚖️ {res}", ephemeral=True)
            await self.aller(itx, "accueil")
        except Exception as e:
            print(f"[Chronique] fermeture : {type(e).__name__}: {e}")

    async def trancher(self, itx, cle):
        try:
            if not itx.response.is_done():
                await itx.response.defer()
            await chro_appliquer_choix(itx.guild, chro_salon(itx.guild), cle)
            await self.aller(itx, "accueil")
        except Exception as e:
            print(f"[Chronique] arbitrage : {type(e).__name__}: {e}")

    async def arreter(self, itx):
        try:
            chro_reset()
            save_all_data()
            await self.aller(itx, "accueil")
        except Exception as e:
            print(f"[Chronique] arrêt : {type(e).__name__}: {e}")

    # ── Écrans ──
    def embed(self):
        if self.ecran == "etat":
            s = chro_saison()
            e = discord.Embed(title="🧠  État de l'histoire",
                              color=0x9b59b6)
            e.description = (f"*Visible uniquement en régie.*\n\n"
                             f"**Drapeaux posés** — {len(CHRONIQUE.get('drapeaux') or [])}\n"
                             f"`{', '.join(CHRONIQUE.get('drapeaux') or []) or 'aucun'}`\n\n"
                             f"**Routes fermées** — {len(CHRONIQUE.get('routes_fermees') or [])}\n"
                             f"`{', '.join(CHRONIQUE.get('routes_fermees') or []) or 'aucune'}`")
            if s:
                proj = chro_ending()
                fins = [f"{'➤' if k == proj else '　'} {v['nom']}"
                        + ("" if chro_route_ouverte(v.get("route", k)) else "  🔒")
                        for k, v in s["endings"].items()]
                e.add_field(name="Fins possibles", value="\n".join(fins), inline=False)
            h = CHRONIQUE.get("historique") or []
            if h:
                e.add_field(name="Décisions canoniques",
                            value="\n".join(f"Ép. {x['episode']} — *{x['libelle']}*"
                                            for x in h[-6:]), inline=False)
            return e
        # accueil
        e = discord.Embed(title="📖  CHRONIQUE", color=0xff9ec7)
        if not chro_active():
            e.description = ("*Aucune saison en cours.*\n\n"
                             f"**{len(CHRONIQUE_SAISONS)}** saison(s) disponible(s).")
            e.set_footer(text="📖 Salon : " + (f"#{self.ctx.guild.get_channel(SALON_CHRONIQUE_ID).name}"
                                              if SALON_CHRONIQUE_ID and self.ctx.guild
                                              and self.ctx.guild.get_channel(SALON_CHRONIQUE_ID)
                                              else "⚠️ aucun — .setsalon chronique #salon"))
            return e
        s = chro_saison()
        etat_lib = {"ATTENTE": ("⚠️ vote à republier" if CHRONIQUE.get("vote_a_republier")
                                else "⏸️ en attente de publication"),
                    "VOTE": "💌 vote ouvert",
                    "EGALITE": "⚖️ égalité à départager", "EPISODE": "📖 publication en cours",
                    "TERMINEE": "🎬 terminée"}.get(CHRONIQUE.get("etat"), CHRONIQUE.get("etat"))
        e.description = (f"### 🎬 {s['titre']}\n"
                         f"Épisode **{min(CHRONIQUE.get('episode', 1), len(s['episodes']))}"
                         f"/{len(s['episodes'])}**\n\n"
                         f"📍 État : {etat_lib}")
        if CHRONIQUE.get("derniere_decision"):
            e.add_field(name="💌 Dernière décision",
                        value=f"*{CHRONIQUE['derniere_decision']}*", inline=False)
        votes = CHRONIQUE.get("votes") or {}
        if votes:
            e.add_field(name="🗳️ Votes en cours", value=f"**{len(votes)}** lecteur(s)", inline=True)
        e.add_field(name="👥 Lecteurs", value=f"**{len(CHRONIQUE_LU)}**", inline=True)
        _sc = (self.ctx.guild.get_channel(SALON_CHRONIQUE_ID)
               if SALON_CHRONIQUE_ID and self.ctx.guild else None)
        e.set_footer(text=f"📖 Salon : {'#' + _sc.name if _sc else '⚠️ non configuré'}")
        return e


@bot.command(name="chronique", aliases=["chro", "lachronique"])
async def chronique_cmd(ctx):
    """📖 Chronique — régie pour les admins, résumé pour les lecteurs"""
    if ctx.author.guild_permissions.administrator:
        vue = ChroRegieView(ctx)
        return await ctx.send(embed=vue.embed(), view=vue)
    if not chro_active():
        return await ctx.send(embed=discord.Embed(
            description="📖 *Aucune saison en cours pour le moment.*", color=0x9b59b6))
    s = chro_saison()
    e = discord.Embed(title=f"📖  {s['titre']}", color=0xff9ec7,
        description=(f"### {s['genre']}\n*{s['accroche']}*\n\n"
                     f"Épisode **{min(CHRONIQUE.get('episode', 1), len(s['episodes']))}"
                     f"/{len(s['episodes'])}**"))
    if CHRONIQUE.get("derniere_decision"):
        e.add_field(name="💌 Votre dernière décision",
                    value=f"*{CHRONIQUE['derniere_decision']}*", inline=False)
    e.set_footer(text=f"{len(CHRONIQUE_LU)} lecteur(s) suivent cette saison")
    await ctx.send(embed=e)

@bot.command(name="secretstory", aliases=["ss", "secret"])
async def secretstory_cmd(ctx, membre: discord.Member = None):
    """Secret Story — régie pour les admins, dossier pour les membres"""
    if ctx.author.guild_permissions.administrator and membre is None:
        vue = SSRegieView(ctx)
        return await ctx.send(embed=vue.embed(), view=vue)
    cible = membre or ctx.author
    st = ss_stats(cible.id)
    e = discord.Embed(title=f"👁️  DOSSIER SECRET — {cible.display_name}", color=0x9b59b6)
    e.set_thumbnail(url=cible.display_avatar.url)
    e.description = (f"🔎 Secrets découverts : **{st['trouves']}**\n"
                     f"🥷 Secrets protégés : **{st['proteges']}**\n"
                     f"🎭 Missions réussies : **{st['missions']}**\n"
                     f"🎬 Participations : **{st['participations']}**")
    if st.get("gains"):
        e.set_footer(text=f"{st['gains']:,} pièces gagnées en émission".replace(",", " "))
    await ctx.send(embed=e)

@bot.command(name="petensemble", aliases=["ensemble", "petsortie"])
async def petensemble_cmd(ctx, activite: str = None):
    """Faites une activité tous les deux — .petensemble [activité]"""
    import time as _t
    uid = str(ctx.author.id)
    pid, pdb, pst = get_active_pet(uid)
    if not pid:
        return await ctx.send("🐾 Tu n'as pas de compagnon actif ! Rends-toi dans `.shop`.")
    pet_init_perso(uid)
    cle = normalize_str(activite or "")
    dispo = activites_disponibles()
    if cle not in dispo:
        gouts = pst.get("gouts_act", {}).get("act", {})
        favori = max(gouts, key=gouts.get) if gouts else None
        lignes = []
        for k, a in dispo.items():
            n = gouts.get(k, 0)
            marque = "  ❤️" if k == favori and n >= 3 else ""
            cout = f"  ·  {a['cout']} 🪙" if a.get("cout") else ""
            lignes.append(f"{a['emoji']} **{a['nom']}** — `{k}`{marque}{cout}\n└ *{a['desc']}*"
                          + (f"  ·  *{n} fois*" if n else ""))
        return await ctx.send(embed=discord.Embed(
            title=f"🐾 Une sortie avec {pst.get('surnom') or pdb['nom']} ?",
            description="\n".join(lignes) + "\n\n*`.petensemble peche` par exemple.*",
            color=0x1abc9c).set_footer(
                text=f"{len(dispo)} sorties · chacune a plusieurs déroulements possibles"))

    st = pet_etat(uid)
    a = dispo[cle]
    cd = a.get("cd", 10800)
    reste = cd - (_t.time() - st["dernier"].get(f"act_{cle}", 0))
    if reste > 0:
        h, m = divmod(int(reste) // 60, 60)
        return await ctx.send(
            f"⏳ Vous venez de faire ça — encore **{h}h{m:02d}**.", delete_after=8)
    if st["energie"] < 25:
        return await ctx.send(
            f"😴 **{pst.get('surnom') or pdb['nom']}** est trop fatigué — `.dormir` d'abord.")
    cout = a.get("cout", 0)
    if cout and economy_data[uid]["coins"] < cout:
        return await ctx.send(f"🪙 Il te faut **{cout} pièces** pour cette sortie.")
    if cout:
        economy_data[uid]["coins"] -= cout
    st["dernier"][f"act_{cle}"] = _t.time()

    vue = SortieView(ctx, uid, cle)
    await ctx.send(embed=vue.embed(), view=vue)

@bot.command(name="marchand", aliases=["petmarchand", "itinerant"])
async def marchand_cmd(ctx, achat: str = None):
    """Le marchand itinérant du jour — .marchand [objet]"""
    import time as _t
    uid = str(ctx.author.id)
    pid, pdb, pst = get_active_pet(uid)
    if not pid:
        return await ctx.send("🐾 Le marchand ne parle qu'aux propriétaires de compagnons.")
    pet_init_perso(uid)
    cle = marchand_du_jour()
    emo, nom, desc, coul, series, bonus_cat = MARCHANDS[cle]

    # ── Stock du jour, stable pour la journée ──
    jour = datetime.datetime.now().strftime("%Y%m%d")
    stock_cache = pst.setdefault("marchand", {})
    if stock_cache.get("jour") != jour or stock_cache.get("qui") != cle:
        rng = random.Random(f"{uid}{jour}{cle}")
        pool = []
        for s in series:
            pool += [(o, s) for o in COLLECTIONS_SERIES[s][3]
                     if o not in pst.get("series", [])]
        rng.shuffle(pool)
        offre = [{"obj": o, "serie": s, "prix": rng.choice([1200, 1800, 2500, 3500, 5000])}
                 for o, s in pool[:4]]
        # Un objet secret, si le compagnon a l'œil
        secret = None
        chance = 0.12 + (0.10 if pet_a_trait(uid, "curieux") else 0) \
                      + (0.08 if pet_a_particularite(uid, "objet") else 0) \
                      + (0.06 if pet_a_trait(uid, "malin") else 0)
        if pool[4:] and rng.random() < min(0.4, chance):
            o, s = pool[4]
            secret = {"obj": o, "serie": s, "prix": rng.choice([7000, 9000, 12000])}
        stock_cache.update({"jour": jour, "qui": cle, "offre": offre,
                            "secret": secret, "vendus": []})
        save_all_data()

    offre = stock_cache.get("offre", [])
    secret = stock_cache.get("secret")
    vendus = stock_cache.get("vendus", [])
    dispo = [x for x in offre if x["obj"] not in vendus]

    # ── Achat ──
    if achat:
        q = normalize_str(achat)
        cible = next((x for x in dispo if q in normalize_str(x["obj"])), None)
        if not cible and secret and secret["obj"] not in vendus and q in normalize_str(secret["obj"]):
            cible = secret
        if not cible:
            return await ctx.send(f"❌ Le marchand n'a pas `{achat}` aujourd'hui.")
        if economy_data[uid]["coins"] < cible["prix"]:
            return await ctx.send(f"❌ Il te faut **{cible['prix']:,} pièces**.")
        economy_data[uid]["coins"] -= cible["prix"]
        vendus.append(cible["obj"])
        stock_cache["vendus"] = vendus
        await ajouter_objet_serie(uid, cible["obj"], ctx.channel)
        donner_objet(uid, "col_" + cible["obj"])
        s_emo, s_nom = COLLECTIONS_SERIES[cible["serie"]][0], COLLECTIONS_SERIES[cible["serie"]][1]
        pet_carnet_note(uid, f"{s_emo} A acquis **{cible['obj']}** chez {nom}.",
                        important=(cible is secret))
        save_all_data()
        return await ctx.send(embed=discord.Embed(
            title=f"{emo} Marché conclu",
            description=(f"{s_emo} **{cible['obj']}**\n*Série : {s_nom}*\n\n"
                         f"💰 **−{cible['prix']:,} pièces**\n\n"
                         f"*« Prends-en soin. »*"),
            color=coul))

    # ── Vitrine ──
    e = discord.Embed(title=f"{emo}  {nom}",
        description=f"*{desc}*\n\n> {_sans_repet(uid, "marchand_dit", MARCHAND_REPLIQUES)}", color=coul)
    if dispo:
        e.add_field(name="🛒 Sa marchandise du jour", value="\n".join(
            f"{COLLECTIONS_SERIES[x['serie']][0]} **{x['obj']}** — **{x['prix']:,} p**\n"
            f"　*série {COLLECTIONS_SERIES[x['serie']][1]}*" for x in dispo), inline=False)
    else:
        e.add_field(name="🛒 Sa marchandise du jour",
                    value="*Il a tout vendu. Reviens demain.*", inline=False)
    if secret and secret["obj"] not in vendus:
        e.add_field(name="✨ Il sort quelque chose de sous la bâche",
                    value=(f"{_sans_repet(uid, 'marchand_secret', MARCHAND_SECRET)}\n\n"
                           f"{COLLECTIONS_SERIES[secret['serie']][0]} **{secret['obj']}** — "
                           f"**{secret['prix']:,} p**"), inline=False)
    e.add_field(name="\u200b",
                value=f"💰 Tu as **{economy_data[uid]['coins']:,} pièces**", inline=False)
    e.set_footer(text="`.marchand <objet>` pour acheter · un marchand différent chaque jour")
    await ctx.send(embed=e)

