def combos_actifs(uid):
    """Les combinaisons de traits présentes chez ce compagnon"""
    pid, pdb, st = get_active_pet(uid)
    if not st:
        return []
    traits = set(st.get("traits", []))
    return [(paire, conf) for paire, conf in COMBOS_TRAITS.items()
            if set(paire) <= traits]

async def tenter_combo(ctx, uid):
    """Une scène née d'une combinaison de traits — rare et spécifique"""
    import time as _t
    pid, pdb, pst = get_active_pet(uid)
    if not pst:
        return False
    actifs = combos_actifs(uid)
    if not actifs:
        return False
    if _t.time() - pst.get("dernier_combo", 0) < 7200:
        return False
    if random.random() > 0.28:
        return False
    pst["dernier_combo"] = _t.time()
    paire, (emo, nom, scenes) = random.choice(actifs)
    texte = _sans_repet(uid, "combo_" + nom, scenes, memoire=3).replace(
        "{p}", f"**{pet_nom_decore(uid, pdb)}**")
    st = pet_etat(uid)
    st["humeur"] = min(100, st["humeur"] + 5)
    save_all_data()
    e = discord.Embed(title=f"{emo}  {nom}", description=f"*{texte}*", color=0x9b59b6)
    e.set_footer(text=f"Un comportement né de : "
                      + " + ".join(PET_TRAITS[t][1] for t in paire if t in PET_TRAITS))
    await ctx.send(embed=e)
    return True



# ============================================================
#  🎒 REGISTRE UNIFIÉ DES OBJETS — anti-objet fantôme
# ============================================================
# Tout objet obtenable passe par ici. Un objet absent du registre
# ne peut pas être vendu : c'est la garantie anti-fantôme.
CAT_INVENTAIRE = {
    "food":      ("🍖", "Nourriture",  "nourrir"),
    "toy":       ("🧸", "Jouets",      "jouer"),
    "accessory": ("🎀", "Accessoires", "garderobe"),
    "gift":      ("🎁", "Cadeaux",     "petcadeau"),
    "collect":   ("💎", "Collection",  None),
    "tool":      ("🧰", "Utilitaires", "utiliser"),
    "misc":      ("📦", "Divers",      None),
}

def registre_objets():
    """{id: {nom, emoji, cat, type, prix, desc, stack, usable}} — construit une fois"""
    global _REGISTRE
    if _REGISTRE:
        return _REGISTRE
    reg = {}
    for nom, (emo, cat, faim, prix, sais) in PET_NOURRITURE.items():
        reg["food_" + nom] = {"nom": nom, "emoji": emo, "cat": "food", "prix": prix,
                              "desc": f"Rend {faim} de faim", "stack": True, "usable": True}
    for nom, (emo, prix, typ) in PET_JOUETS.items():
        reg["toy_" + nom] = {"nom": nom, "emoji": emo, "cat": "toy", "prix": prix,
                             "desc": f"Jouet — {typ}", "stack": False, "usable": True}
    for cle, (emo, nom, prix, typ, val, desc) in PET_ACCESSOIRES.items():
        reg["acc_" + cle] = {"nom": nom, "emoji": emo, "cat": "accessory", "prix": prix,
                             "desc": desc, "stack": False, "usable": True}
    for cle, (emo, nom, desc, lot) in COLLECTIONS_SERIES.items():
        for o in lot:
            reg["col_" + o] = {"nom": o, "emoji": emo, "cat": "collect", "prix": 0,
                               "desc": f"Série {nom}", "stack": False, "usable": False}
    for nom, (emo, desc, eff, bonus, rar) in PET_OBJETS_TROUVES.items():
        reg["obj_" + nom] = {"nom": nom, "emoji": emo, "cat": "collect", "prix": 0,
                             "desc": desc, "stack": False, "usable": False}
    for it in SHOP_ITEMS:
        reg[it["id"]] = {"nom": it["nom"], "emoji": "📦", "cat": "tool", "prix": it["prix"],
                         "desc": it.get("description", ""), "stack": True, "usable": True}
    _REGISTRE = reg
    return reg
_REGISTRE = None

def donner_objet(uid, oid, n=1):
    """Ajoute un objet à l'inventaire du JOUEUR. Retourne la fiche, ou None si inconnu."""
    reg = registre_objets()
    fiche = reg.get(oid)
    if not fiche:
        return None
    if fiche["stack"]:
        inventaire[uid][oid] = inventaire[uid].get(oid, 0) + n
    else:
        inventaire[uid][oid] = max(1, inventaire[uid].get(oid, 0))
    return fiche

def possede(uid, oid):
    return inventaire.get(uid, {}).get(oid, 0) > 0

def retirer_objet(uid, oid, n=1):
    if inventaire.get(uid, {}).get(oid, 0) < n:
        return False
    inventaire[uid][oid] -= n
    if inventaire[uid][oid] <= 0:
        inventaire[uid].pop(oid, None)
    return True

def inventaire_par_cat(uid):
    """{cat: [(oid, fiche, n)]} — pour l'affichage"""
    reg = registre_objets()
    par = {}
    for oid, n in inventaire.get(uid, {}).items():
        if n <= 0:
            continue
        f = reg.get(oid)
        if not f:
            continue
        par.setdefault(f["cat"], []).append((oid, f, n))
    return par

def migrer_objets_perdus(uid):
    """Rattrape les achats passés qui n'ont pas atterri dans l'inventaire.
    Notamment les objets de série achetés chez le marchand."""
    pid, pdb, pst = get_active_pet(uid)
    if not pst:
        return 0
    n = 0
    # Les objets de collection possédés doivent aussi exister dans l'inventaire
    for o in pst.get("series", []):
        oid = "col_" + o
        if oid in registre_objets() and not possede(uid, oid):
            inventaire[uid][oid] = 1
            n += 1
    for o in pst.get("objets", []):
        oid = "obj_" + o
        if oid in registre_objets() and not possede(uid, oid):
            inventaire[uid][oid] = 1
            n += 1
    # Les accessoires achetés
    for a in pst.get("garderobe", []):
        oid = "acc_" + a
        if oid in registre_objets() and not possede(uid, oid):
            inventaire[uid][oid] = 1
            n += 1
    return n

# ============================================================
#  🏠 PROPRETÉ DU REFUGE — barre, meubles, migration
# ============================================================
def migrer_bebes_pets():
    """Sort les anciens bébés de PETS_DB sans rien perdre. Idempotente."""
    import time as _t
    n_sortis = n_init = 0
    for uid, d in list(pets_data.items()):
        for pid, st in list((d.get("owned") or {}).items()):
            if not pid.startswith("bebe_"):
                continue
            st["est_bebe"] = True
            if not st.get("espece_base"):
                fiche = pet_espece(uid, pid)
                if fiche:
                    # Retrouve l'espèce réelle par son emoji
                    base = next((k for k, v in PETS_DB.items()
                                 if not k.startswith("bebe_") and v.get("emoji") == fiche.get("emoji")), None)
                    st["espece_base"] = base or next(iter(PETS_DB))
                    st.setdefault("nom_bebe", fiche.get("nom", "Petit"))
                else:
                    st["espece_base"] = next(k for k in PETS_DB if not k.startswith("bebe_"))
                    st.setdefault("nom_bebe", "Petit")
                n_sortis += 1
            # Les bébés existants reçoivent leur personnalité, sans écraser l'existant
            if not st.get("traits"):
                st["traits"] = random.sample(list(PET_TRAITS), random.choice([2, 3]))
                n_init += 1
            st.setdefault("particularite", None)
            st.setdefault("soins", 0)
            st.setdefault("appris", [])
            st.setdefault("choix", {})
            st.setdefault("phase_maj", st.get("adoption", _t.time()))
    # On purge PETS_DB des entrées bebe_ : plus personne n'en dépend
    n_purges = 0
    for k in [k for k in PETS_DB if k.startswith("bebe_")]:
        PETS_DB.pop(k, None); n_purges += 1
    return {"sortis": n_sortis, "personnalites": n_init, "purges": n_purges}

def migrer_inventaire_pet(uid):
    """Déplace nourriture et jouets du pet vers l'inventaire du JOUEUR.
    Sans perte : appelée une fois, puis inoffensive."""
    d = pets_data.get(uid, {})
    for pid, st in d.get("owned", {}).items():
        for nom, n in list(st.pop("garde_manger", {}).items()):
            if nom in PET_NOURRITURE and n > 0:
                inventaire[uid]["food_" + nom] = inventaire[uid].get("food_" + nom, 0) + n
        for j in list(st.pop("jouets", [])):
            if j in PET_JOUETS:
                inventaire[uid]["toy_" + j] = max(1, inventaire[uid].get("toy_" + j, 0))

def stock_nourriture(uid):
    """{nom: quantité} depuis l'inventaire du joueur"""
    migrer_inventaire_pet(uid)
    return {k[5:]: v for k, v in inventaire.get(uid, {}).items()
            if k.startswith("food_") and v > 0 and k[5:] in PET_NOURRITURE}

def stock_jouets(uid):
    migrer_inventaire_pet(uid)
    return [k[4:] for k, v in inventaire.get(uid, {}).items()
            if k.startswith("toy_") and v > 0 and k[4:] in PET_JOUETS]

