class CachetteView(ui.View):
    """Retrouver l'objet parmi trois cachettes"""
    def __init__(self, uid, bonne, timeout=45):
        super().__init__(timeout=timeout)
        self.uid, self.bonne, self.fini = uid, bonne, False
        for i, (emo, nom) in enumerate([("📦","Boîte"),("🛏️","Panier"),("🪴","Plante")]):
            b = ui.Button(label=nom, emoji=emo, style=discord.ButtonStyle.secondary)
            async def cb(interaction, idx=i):
                if str(interaction.user.id) != self.uid:
                    return await interaction.response.send_message("❌ Pas ton entraînement !", ephemeral=True)
                if self.fini: return await interaction.response.defer()
                self.fini = True
                await fin_entrainement(interaction, self.uid, idx == self.bonne,
                                       "fouille", ["📦","🛏️","🪴"][self.bonne], self)
            b.callback = cb
            self.add_item(b)

class SequenceView(ui.View):
    """Reproduire une séquence de couleurs"""
    COULEURS = [("🟥","Rouge"),("🟦","Bleu"),("🟩","Vert"),("🟨","Jaune")]
    def __init__(self, uid, sequence, timeout=60):
        super().__init__(timeout=timeout)
        self.uid, self.seq, self.saisie, self.fini = uid, sequence, [], False
        for i, (emo, nom) in enumerate(self.COULEURS):
            b = ui.Button(label="\u200b", emoji=emo, style=discord.ButtonStyle.secondary)
            async def cb(interaction, idx=i):
                if str(interaction.user.id) != self.uid:
                    return await interaction.response.send_message("❌ Pas ton entraînement !", ephemeral=True)
                if self.fini: return await interaction.response.defer()
                self.saisie.append(idx)
                if self.saisie[-1] != self.seq[len(self.saisie)-1]:
                    self.fini = True
                    return await fin_entrainement(interaction, self.uid, False, "musique",
                        " ".join(self.COULEURS[x][0] for x in self.seq), self)
                if len(self.saisie) == len(self.seq):
                    self.fini = True
                    return await fin_entrainement(interaction, self.uid, True, "musique",
                        " ".join(self.COULEURS[x][0] for x in self.seq), self)
                await interaction.response.edit_message(embed=discord.Embed(
                    description=f"🧠 **{len(self.saisie)}/{len(self.seq)}** — continue…",
                    color=0x3498db), view=self)
            b.callback = cb
            self.add_item(b)

class ReflexeView(ui.View):
    """Cliquer au bon moment"""
    def __init__(self, uid, timeout=40):
        super().__init__(timeout=timeout)
        self.uid, self.ouvert, self.fini = uid, False, False
        self.message = None
    @ui.button(label="ATTENDS…", emoji="🔴", style=discord.ButtonStyle.danger)
    async def b(self, interaction, button):
        if str(interaction.user.id) != self.uid:
            return await interaction.response.send_message("❌ Pas ton entraînement !", ephemeral=True)
        if self.fini: return await interaction.response.defer()
        self.fini = True
        await fin_entrainement(interaction, self.uid, self.ouvert, "course",
                               "🟢 GO !" if self.ouvert else "🔴 trop tôt", self)
    async def ouvrir(self):
        self.ouvert = True
        self.b.label, self.b.emoji, self.b.style = "GO !", "🟢", discord.ButtonStyle.success
        if self.message:
            try:
                await self.message.edit(embed=discord.Embed(
                    title="🟢 MAINTENANT !", color=0x2ecc71), view=self)
            except Exception: pass

async def fin_entrainement(interaction, uid, reussi, competence, solution, vue):
    """Résultat commun aux 3 exercices"""
    pid, pdb, pst = get_active_pet(uid)
    st = pet_etat(uid)
    nom = f"**{pet_nom_decore(uid, pdb)}**"
    for it in vue.children: it.disabled = True
    pst.setdefault("vecu", {})
    pst["vecu"]["entrainements"] = pst["vecu"].get("entrainements", 0) + 1
    if reussi:
        pst["vecu"]["entrainements_ok"] = pst["vecu"].get("entrainements_ok", 0) + 1
        stat = PET_COMPETENCES[competence][2]
        pst.setdefault("stats", {})
        pst["stats"][stat] = pst["stats"].get(stat, 0) + 3
        st["humeur"] = min(100, st["humeur"] + 12)
        pst["confiance"] = min(100, pst.get("confiance", 0) + 4)
        give_pet_xp(uid, 45)
        emo_c, nom_c, _, _ = PET_COMPETENCES[competence]
        txt = (f"✅ **Réussi !**\n{nom} a compris du premier coup.\n\n"
               f"{emo_c} Compétence **{nom_c}** progresse\n"
               f"❤️ Humeur **+12**  ·  💞 Confiance **+4**  ·  ⭐ **+45 XP**")
        coul = 0x2ecc71
    else:
        st["humeur"] = min(100, st["humeur"] + 4)
        give_pet_xp(uid, 15)
        txt = (f"😅 **Raté !**\n*La bonne réponse : {solution}*\n\n"
               f"{nom} n'a pas compris, mais il s'est bien amusé.\n"
               f"❤️ Humeur **+4**  ·  ⭐ **+15 XP**")
        coul = 0xe67e22
    save_all_data()
    await interaction.response.edit_message(embed=discord.Embed(
        title="🎯 Entraînement", description=txt, color=coul), view=vue)
    vue.stop()

@bot.command(name="petmanger", aliases=["petnourriture", "faimanger"])
async def petmanger_cmd(ctx, *, aliment: str = None):
    """Alias de .nourrir — .petmanger <aliment>"""
    await nourrir_cmd(ctx, aliment=aliment)


@bot.command(name="petmenu", aliases=["goutsrepas", "petplats"])
async def petmenu_cmd(ctx, membre: discord.Member = None):
    """Ce que ton compagnon aime manger — .petmenu"""
    cible = membre or ctx.author
    uid = str(cible.id)
    pid, pdb, pst = get_active_pet(uid)
    if not pid:
        return await ctx.send(f"🐾 **{cible.display_name}** n'a pas de compagnon actif.")
    gouts = gouts_repas(uid)
    if not gouts:
        return await ctx.send(embed=discord.Embed(
            title="🍽️ Menu inconnu",
            description=("*Tu ne sais pas encore ce qu'il aime.*\n\n"
                         "Donne-lui différents aliments avec `.petmanger` pour découvrir ses goûts.\n"
                         f"*Il y a **{len(PET_NOURRITURE)} aliments** à faire goûter.*"),
            color=0x95a5a6))
    par_gout = {"adore": [], "aime": [], "neutre": [], "deteste": []}
    for nom, g in gouts.items():
        if nom in PET_NOURRITURE:
            par_gout[g].append(f"{PET_NOURRITURE[nom][0]} {nom}")
    TITRES = {"adore":("😍","Il adore"), "aime":("😊","Il aime bien"),
              "neutre":("😐","Ça lui est égal"), "deteste":("😖","Il déteste")}
    embed = discord.Embed(
        title=f"🍽️ Le menu de {pet_nom_decore(uid, pdb)}",
        description=f"**{len(gouts)} / {len(PET_NOURRITURE)}** aliments goûtés",
        color=0xe91e63)
    pref = pst.get("repas_prefere")
    if pref and pref in PET_NOURRITURE:
        embed.add_field(name="❤️ Son plat préféré",
                        value=f"{PET_NOURRITURE[pref][0]} **{pref}**", inline=False)
    for g in ("adore","aime","neutre","deteste"):
        if par_gout[g]:
            e_g, t_g = TITRES[g]
            embed.add_field(name=f"{e_g} {t_g} ({len(par_gout[g])})",
                            value="  ·  ".join(par_gout[g])[:1024], inline=False)
    embed.set_footer(text="`.petmanger <aliment>` pour lui faire goûter autre chose")
    await ctx.send(embed=embed)

@bot.command(name="petutiliser", aliases=["utilisermeuble", "petmeuble"])
async def petutiliser_cmd(ctx, *, meuble: str = None):
    """Fais utiliser un meuble à ton compagnon — .petutiliser <meuble>"""
    import time as _t
    uid = str(ctx.author.id)
    pid, pdb, pst = get_active_pet(uid)
    if not pid:
        return await ctx.send("🐾 Tu n'as pas de compagnon actif ! Rends-toi dans `.shop`.")
    pet_init_perso(uid)
    ref = pets_data[uid].setdefault("refuge", [])
    utilisables = [m for m in ref if m in MEUBLES_INTERACTIONS]

    if not meuble:
        if not utilisables:
            return await ctx.send(embed=discord.Embed(
                description=("🏡 Son refuge est vide — installe des meubles avec `.refuge acheter <meuble>`.\n"
                             "*Chaque meuble installé peut ensuite être **utilisé** par ton compagnon.*"),
                color=0x95a5a6))
        lignes = []
        for m in utilisables:
            emo, verbe, _, eff, val = MEUBLES_INTERACTIONS[m]
            LAB = {"humeur":"❤️ humeur","energie":"⚡ énergie","faim":"🍖 faim",
                   "proprete":"🧼 propreté","xp":"⭐ XP"}
            signe = "+" if val > 0 else ""
            lignes.append(f"{emo} **{PET_MEUBLES[m][1]}** — `{m}` · *{verbe}*  ·  "
                          f"{LAB[eff]} {signe}{val}")
        return await ctx.send(embed=discord.Embed(
            title=f"🪑 Que peut faire {pst.get('surnom') or pdb['nom']} ?",
            description="\n".join(lignes) + "\n\n*`.petutiliser <meuble>` — une utilisation par heure et par meuble.*",
            color=0xe91e63))

    cle = normalize_str(meuble).replace(" ", "")
    if cle not in MEUBLES_INTERACTIONS:
        cle = next((k for k in MEUBLES_INTERACTIONS
                    if normalize_str(meuble) in normalize_str(PET_MEUBLES[k][1])), None)
    if not cle:
        return await ctx.send(f"❌ Meuble `{meuble}` inconnu — tape `.petutiliser` pour la liste.")
    if cle not in ref:
        return await ctx.send(f"❌ **{PET_MEUBLES[cle][1]}** n'est pas dans son refuge.\n"
                              f"*`.refuge acheter {cle}` pour l'installer.*")

    st = pet_etat(uid)
    dernier = st["dernier"].get("meuble_" + cle, 0)
    reste = 3600 - (_t.time() - dernier)
    if reste > 0:
        return await ctx.send(f"⏳ Il vient de s'en servir — encore **{int(reste//60)} min**.",
                              delete_after=8)
    st["dernier"]["meuble_" + cle] = _t.time()

    emo, verbe, scenes, eff, val = MEUBLES_INTERACTIONS[cle]
    nom_pet = pst.get("surnom") or pdb["nom"]
    scene = _sans_repet(uid, "meuble_" + cle, scenes, memoire=3)

    if eff == "xp":
        l, lv = give_pet_xp(uid, val)
        resultat = f"⭐ **+{val} XP**" + (f"\n🆙 Niveau **{lv}** !" if l else "")
    elif eff == "faim":
        st["faim"] = max(0, min(100, st["faim"] + val))
        resultat = f"🍖 Faim **{val}** *(il a moins faim)*"
    else:
        st[eff] = max(0, min(100, st[eff] + val))
        LAB = {"humeur":"❤️ Humeur","energie":"⚡ Énergie","proprete":"🧼 Propreté"}
        resultat = f"{LAB[eff]} **{'+' if val > 0 else ''}{val}**"
    st["humeur"] = min(100, st["humeur"] + 4)
    pet_stat(uid, "meubles_utilises")
    save_all_data()

    await ctx.send(embed=discord.Embed(
        title=f"{emo} {PET_MEUBLES[cle][1]}",
        description=f"**{nom_pet}** {scene}\n\n{resultat}",
        color=0xe91e63).set_footer(text=f"{pet_humeur_texte(st)} · un meuble par heure"))

@bot.command(name="petobjets", aliases=["objetspet", "petcollection"])
async def petobjets_cmd(ctx, action: str = None, *, nom: str = None):
    """La collection d'objets — .petobjets [prefere <objet>]"""
    uid = str(ctx.author.id)
    pid, pdb, pst = get_active_pet(uid)
    if not pid:
        return await ctx.send("🐾 Tu n'as pas de compagnon actif.")
    pet_init_perso(uid)
    possedes = pst.get("objets", [])

    if action and normalize_str(action) in ("prefere", "favori", "pref"):
        if not nom:
            return await ctx.send("❌ `.petobjets prefere <nom de l'objet>`")
        trouve = next((o for o in possedes if normalize_str(nom) in normalize_str(o)), None)
        if not trouve:
            return await ctx.send(f"❌ Il ne possède pas **{nom}**.")
        pst["objet_prefere"] = trouve
        pet_carnet_note(uid, f"❤️ **{trouve}** est devenu son objet préféré.", important=True)
        save_all_data()
        return await ctx.send(embed=discord.Embed(
            description=f"❤️ {PET_OBJETS_TROUVES[trouve][0]} **{trouve}** est maintenant son objet préféré.",
            color=0xe91e63))

    prefere = pst.get("objet_prefere")
    embed = discord.Embed(
        title=f"🎒 La collection de {pet_nom_decore(uid, pdb)}",
        description=(f"**{len(possedes)} / {len(PET_OBJETS_TROUVES)}** objets trouvés\n"
                     f"*Il les ramasse lors des **événements du quotidien** et des **expéditions**.*"),
        color=0xe91e63)
    for rar, (r_emo, r_nom, r_coul, _) in PET_OBJ_RARETES.items():
        lot = [(n, v) for n, v in PET_OBJETS_TROUVES.items() if v[4] == rar]
        a_lui = [n for n, _ in lot if n in possedes]
        lignes = [(f"{v[0]} **{n}**" + (" ❤️" if n == prefere else "")) if n in possedes else "🔒 *???*"
                  for n, v in lot]
        embed.add_field(name=f"{r_emo} {r_nom}  ·  {len(a_lui)}/{len(lot)}",
                        value="  ·  ".join(lignes)[:1024], inline=False)
    LAB = {"coins":"💰 pièces","xp":"⭐ XP","roll":"🎰 rolls","humeur":"❤️ humeur"}
    bonus = [f"{lab} **+{bonus_objets(uid, t)} %**" for t, lab in LAB.items() if bonus_objets(uid, t)]
    if bonus:
        embed.add_field(name="✨ Bonus de collection", value="  ·  ".join(bonus), inline=False)
    embed.set_footer(text=(f"Objet préféré : {prefere} · `.petobjets prefere <nom>` pour changer"
                           if prefere else "Le premier objet trouvé devient son préféré."))
    await ctx.send(embed=embed)

@bot.command(name="petcarnet", aliases=["carnet", "journalpet"])
async def petcarnet_cmd(ctx, action: str = None, numero: int = None):
    """Le carnet de bord — .petcarnet [epingler|detacher] <n°>"""
    import time as _t
    uid = str(ctx.author.id)
    pid, pdb, st = get_active_pet(uid)
    if not pid:
        return await ctx.send("🐾 Tu n'as pas de compagnon actif.")
    st.setdefault("adoption", _t.time())
    st.setdefault("carnet", [])
    carnet = st["carnet"]

    # ── Épingler / détacher ──
    if action and action.lower() in ("epingler", "pin", "detacher", "unpin"):
        if not numero or numero < 1 or numero > len(carnet):
            return await ctx.send(f"❌ Numéro invalide — entre 1 et {len(carnet)}.")
        e = carnet[numero - 1]
        if action.lower() in ("epingler", "pin"):
            if sum(1 for x in carnet if x.get("pin")) >= 5:
                return await ctx.send("📌 Cinq souvenirs épinglés maximum — détaches-en un d'abord.")
            e["pin"] = True
            save_all_data()
            return await ctx.send(f"📌 Souvenir épinglé : *{e['txt']}*")
        e.pop("pin", None)
        save_all_data()
        return await ctx.send(f"📌 Souvenir détaché : *{e['txt']}*")

    jours = int((_t.time() - st["adoption"]) / 86400) + 1
    nom_pet = st.get("surnom") or pdb["nom"]
    epingles = [e for e in carnet if e.get("pin")]
    importants = [e for e in carnet if e.get("imp") and not e.get("pin")]
    quotidiens = [e for e in carnet if not e.get("imp") and not e.get("pin")]

    embed = discord.Embed(
        title=f"📖 Le carnet de {pet_nom_decore(uid, pdb)}",
        description=(f"*Adopté il y a **{jours} jour(s)** par {ctx.author.display_name}.*\n"
                     f"*{len(carnet)} souvenir(s) — les grands moments restent pour toujours.*"),
        color=0xe91e63)

    if epingles:
        embed.add_field(name="📌 Souvenirs épinglés", value="\n".join(
            f"**Jour {e['jour']}** — {e['txt']}" for e in epingles[:5]), inline=False)
    if importants:
        embed.add_field(name="⭐ Les grands moments", value="\n".join(
            f"**Jour {e['jour']}** — {e['txt']}" for e in importants[-8:])[:1024], inline=False)
    if quotidiens:
        recents = quotidiens[-10:]
        debut = len(carnet) - len(recents) + 1
        embed.add_field(name="🌿 Le quotidien", value="\n".join(
            f"`{carnet.index(e)+1}` **J{e['jour']}** — {e['txt']}" for e in recents)[:1024],
            inline=False)
    if not carnet:
        embed.add_field(name="\u200b",
                        value="*Rien d'écrit pour l'instant. Le carnet se remplit tout seul.*",
                        inline=False)

    amis = sum(1 for k, v in petamitie.items() if uid in k.split("|") and v > 0)
    embed.set_footer(text=f"Niveau {st.get('level',1)} · {amis} ami(s) · "
                          f"`.petcarnet epingler <n°>` pour garder un souvenir")
    await ctx.send(embed=embed)


@tasks.loop(hours=6)
async def anniversaires_pets():
    """Souhaite l'anniversaire des compagnons adoptés il y a un an"""
    import time as _t
    now = _t.time()
    for guild in bot.guilds:
        salon = ((guild.get_channel(SALON_ANNONCES_ID) if SALON_ANNONCES_ID else None)
                 or guild.system_channel)
        if not salon:
            continue
        for uid, d in list(pets_data.items()):
            pid = d.get("active")
            if not pid or pid not in PETS_DB:
                continue
            st = d.get("owned", {}).get(pid, {})
            adoption = st.get("adoption")
            if not adoption:
                continue
            ans = int((now - adoption) / 31536000)
            if ans < 1 or st.get("dernier_anniv") == ans:
                continue
            m = guild.get_member(int(uid))
            if not m:
                continue
            st["dernier_anniv"] = ans
            pdb = (pet_espece(uid, pid) or {})
            economy_data[uid]["coins"] += 5000 * ans
            give_pet_xp(uid, 500)
            pet_carnet_note(uid, f"🎂 A fêté ses **{ans} an(s)** avec {m.display_name}.", important=True)
            try:
                await salon.send(embed=discord.Embed(
                    title="🎂  Joyeux anniversaire !",
                    description=(f"**{pet_nom_decore(uid, pdb)}** fête ses **{ans} an(s)** "
                                 f"aux côtés de {m.mention} !\n\n"
                                 f"🎁 **{5000*ans:,} pièces** et **+500 XP** pour l'occasion.\n\n"
                                 f"*Un an de gamelles, de siestes et de bêtises. Merci d'avoir été là.*"),
                    color=0xf1c40f))
            except Exception:
                pass
            gazette_fait("divers", f"Le compagnon de **{m.display_name}** a fêté ses {ans} an(s).", 3)
    save_all_data()

