def _sans_repet(uid, cle, pool, memoire=25):
    """Choisit dans `pool` en évitant fortement ce qui a été vu récemment.
    Pénalité progressive : le plus ancien redevient éligible en douceur.
    La rareté relative du pool est préservée."""
    if not pool:
        return ""
    pool = list(pool)
    pid, pdb, st = get_active_pet(uid)
    if not st:
        return random.choice(pool)
    vus = st.setdefault("vus", {}).setdefault(cle, [])
    if len(pool) <= 2:
        choix = random.choice(pool)
    else:
        # Poids : 1 pour du jamais vu, très faible pour du récent
        poids = []
        for x in pool:
            if x not in vus:
                poids.append(100.0)
            else:
                rang = len(vus) - 1 - vus[::-1].index(x)   # 0 = le plus ancien
                poids.append(max(1.0, 4.0 * (rang + 1) / max(1, len(vus))))
        choix = random.choices(pool, weights=poids)[0]
    vus.append(choix)
    st["vus"][cle] = vus[-min(memoire, max(4, len(pool) - 1)):]
    if len(st["vus"]) > 40:
        for k in list(st["vus"])[:-40]:
            st["vus"].pop(k, None)
    return choix

def _pool_contextuel(uid, base, variantes):
    """Assemble un pool : base + variantes qui collent au contexte du pet.
    `variantes` = {condition: [textes]} où condition est un trait, un moment,
    une saison, ou un état (faim/energie/humeur/proprete + _bas/_haut)."""
    pid, pdb, pst = get_active_pet(uid)
    if not pst:
        return list(base)
    st = pet_etat(uid)
    pool = list(base)
    traits = set(pst.get("traits", []))
    moment = routine_actuelle()[0]
    mois = datetime.datetime.now().month
    saison = ("hiver" if mois in (12,1,2) else "printemps" if mois in (3,4,5)
              else "ete" if mois in (6,7,8) else "automne")
    d = pets_data.get(uid, {})
    ref = set(d.get("refuge", []))
    actifs = set(traits) | {moment, saison}
    if st["faim"] > 65: actifs.add("faim_haute")
    if st["faim"] < 20: actifs.add("faim_basse")
    if st["energie"] < 35: actifs.add("energie_basse")
    if st["energie"] > 80: actifs.add("energie_haute")
    if st["humeur"] < 40: actifs.add("humeur_basse")
    if st["humeur"] > 80: actifs.add("humeur_haute")
    if st["proprete"] < 40: actifs.add("sale")
    if proprete_refuge(uid) < 50: actifs.add("refuge_sale")
    if pst.get("level", 1) >= 30: actifs.add("ancien")
    if pst.get("level", 1) <= 5: actifs.add("jeune")
    if pst.get("objets"): actifs.add("a_objets")
    if pst.get("jouets_cpt"): actifs.add("a_jouets")
    if any(v > 0 for k, v in petamitie.items() if uid in k.split("|")): actifs.add("a_ami")
    if any(v < 0 for k, v in petamitie.items() if uid in k.split("|")): actifs.add("a_rival")
    actifs |= {m for m in ref}
    for cond, lot in variantes.items():
        if cond in actifs:
            pool += lot * 2          # les variantes contextuelles sont favorisées
    return pool

def _remplir(uid, texte):
    """Remplace les balises par les vraies données du compagnon"""
    pid, pdb, pst = get_active_pet(uid)
    if not pst:
        return texte
    K = _ctx_pet(uid)
    objet = pst.get("objet_prefere") or (random.choice(pst["objets"]) if pst.get("objets") else "son jouet")
    jouet = pst.get("jouet_prefere") or (random.choice(list(pst.get("jouets_cpt", {}))) if pst.get("jouets_cpt") else "sa balle")
    repas = pst.get("repas_prefere") or "sa gamelle"
    endroit = (pst.get("prefs", {}) or {}).get("endroit", "son coin préféré")
    piece = "le salon"
    d = pets_data.get(uid, {})
    if d.get("refuge"):
        piece = piece_de(random.choice(d["refuge"]))[2].lower()
    ami = rival = None
    for cle, dest in (("meilleur", "ami"), ("rival", "rival")):
        if K.get(cle):
            autre = next((x for x in K[cle].split("|") if x != uid), None)
            if autre:
                _, a_pdb, a_pst = get_active_pet(autre)
                if a_pdb:
                    v = a_pst.get("surnom") or a_pdb["nom"]
                    if dest == "ami": ami = v
                    else: rival = v
    remp = {"p": f"**{pet_nom_decore(uid, pdb)}**", "o": f"**{objet}**",
            "j": f"**{jouet}**", "r": f"**{repas}**", "e": endroit,
            "piece": piece, "ami": f"**{ami or 'son ami'}**",
            "rival": f"**{rival or 'son rival'}**",
            "n": pst.get("surnom") or pdb["nom"]}
    for k, v in remp.items():
        texte = texte.replace("{" + k + "}", str(v))
    return texte


def gouts_repas(uid):
    """Découvre progressivement ce que le pet aime. Structure : {"Poulet": "adore"}"""
    pid, pdb, st = get_active_pet(uid)
    if not st:
        return {}
    st.setdefault("gouts_repas", {})
    return st["gouts_repas"]

def _tirer_gout(uid, nom):
    """Attribue un goût à un aliment, influencé par le caractère"""
    poids = {"adore": 15, "aime": 35, "neutre": 35, "deteste": 15}
    cat = PET_NOURRITURE[nom][1]
    if pet_a_trait(uid, "gourmand") or pet_a_trait(uid, "glouton"):
        poids["adore"] += 20; poids["deteste"] -= 10
    if pet_a_trait(uid, "maniaque"):
        poids["deteste"] += 12
    if cat == "friandise":
        poids["adore"] += 15
    if cat == "premium":
        poids["adore"] += 25; poids["deteste"] -= 10
    poids = {k: max(1, v) for k, v in poids.items()}
    return random.choices(list(poids), weights=list(poids.values()))[0]

def saison_actuelle_mois():
    return datetime.datetime.now().month

def nourriture_dispo(nom):
    """Les aliments saisonniers ne sont vendus qu'à leur période"""
    conf = PET_NOURRITURE.get(nom)
    if not conf or conf[4] is None:
        return True
    return conf[4] == saison_actuelle_mois()

# ============================================================
#  🎲 MOTEUR D'ÉVÉNEMENTS MODULAIRE
# ============================================================
# Une scène = un décor + des réactions conditionnelles.
# Le moteur choisit la réaction selon le trait, l'état, l'heure, la pièce…
# Ajouter du contenu = ajouter une entrée, rien d'autre à toucher.

def _ctx_pet(uid):
    """Contexte complet du pet pour filtrer les scènes et réactions"""
    pid, pdb, pst = get_active_pet(uid)
    st = pet_etat(uid)
    d = pets_data.get(uid, {})
    cle_r, _, _ = routine_actuelle()
    amis = [(k, v) for k, v in petamitie.items() if uid in k.split("|")]
    meilleur = max(amis, key=lambda x: x[1])[0] if amis else None
    rival = min(amis, key=lambda x: x[1])[0] if amis and min(amis, key=lambda x: x[1])[1] < 0 else None
    return {
        "pid": pid, "pdb": pdb, "pst": pst, "st": st,
        "nom": pst.get("surnom") or pdb["nom"],
        "traits": set(pst.get("traits", [])),
        "moment": cle_r,
        "refuge": set(d.get("refuge", [])),
        "objets": pst.get("objets", []),
        "prefere": pst.get("objet_prefere"),
        "humeur": st["humeur"], "faim": st["faim"],
        "energie": st["energie"], "proprete": st["proprete"],
        "confiance": pst.get("confiance", 0),
        "jours": pet_jours(uid),
        "niveau": pst.get("level", 1),
        "amis_n": sum(1 for _, v in amis if v > 0),
        "meilleur": meilleur, "rival": rival,
        "saletes": d.get("saletes", 0),
    }

def _scene_possible(sc, K):
    """La scène peut-elle se produire dans ce contexte ?"""
    req = sc.get("si", {})
    if "moment" in req and K["moment"] not in req["moment"]:
        return False
    if "meuble" in req and not (set(req["meuble"]) & K["refuge"]):
        return False
    if "objet" in req and not K["objets"]:
        return False
    if "ami" in req and not K["meilleur"]:
        return False
    if "rival" in req and not K["rival"]:
        return False
    if "jours_min" in req and K["jours"] < req["jours_min"]:
        return False
    if "confiance_min" in req and K["confiance"] < req["confiance_min"]:
        return False
    if "a_jouets" in req and not K["pst"].get("jouets_cpt"):
        return False
    if "a_objets" in req and not K["objets"]:
        return False
    for jauge in ("humeur", "faim", "energie", "proprete", "saletes"):
        if f"{jauge}_min" in req and K[jauge] < req[f"{jauge}_min"]:
            return False
        if f"{jauge}_max" in req and K[jauge] > req[f"{jauge}_max"]:
            return False
    return True

def _choisir_reaction(sc, K):
    """La réaction dépend d'abord du caractère, sinon de l'état, sinon défaut"""
    reacs = sc.get("reactions", {})
    # 1. Un trait du pet correspond
    candidats = [v for t, v in reacs.items() if t in K["traits"]]
    if candidats and random.random() < 0.75:
        return random.choice(candidats)
    # 2. Un état particulier
    etats = []
    if K["humeur"] < 40 and "triste" in reacs: etats.append(reacs["triste"])
    if K["humeur"] > 78 and "joyeux" in reacs: etats.append(reacs["joyeux"])
    if K["faim"] > 65 and "affame" in reacs: etats.append(reacs["affame"])
    if K["energie"] < 35 and "fatigue" in reacs: etats.append(reacs["fatigue"])
    if K["moment"] == "nuit" and "nuit" in reacs: etats.append(reacs["nuit"])
    if etats and random.random() < 0.6:
        return random.choice(etats)
    # 3. Défaut
    return random.choice(reacs.get("defaut", ["reste immobile un long moment."]))

def rendu_scene(uid, sc):
    """Assemble le texte final d'une scène"""
    K = _ctx_pet(uid)
    reaction = _choisir_reaction(sc, K)
    if isinstance(reaction, list):
        reaction = random.choice(reaction)
    nom = f"**{pet_nom_decore(uid, K['pdb'])}**"
    objet = K["prefere"] or (random.choice(K["objets"]) if K["objets"] else "son jouet")
    ami_nom = "son ami"
    if K["meilleur"]:
        autre = next((x for x in K["meilleur"].split("|") if x != uid), None)
        if autre:
            _, a_pdb, a_pst = get_active_pet(autre)
            if a_pdb:
                ami_nom = a_pst.get("surnom") or a_pdb["nom"]
    piece = "le salon"
    if K["refuge"]:
        m = random.choice(list(K["refuge"]))
        piece = piece_de(m)[2].lower()
    remp = {"p": nom, "o": objet, "ami": ami_nom, "piece": piece}
    decor = sc["decor"]
    for k, v in remp.items():
        decor = decor.replace("{" + k + "}", str(v))
        reaction = reaction.replace("{" + k + "}", str(v))
    return decor, reaction, K

