def verifier_habitudes(uid):
    """Retourne les nouvelles habitudes débloquées"""
    pid, pdb, st = get_active_pet(uid)
    if not st:
        return []
    st.setdefault("habitudes", {})
    st.setdefault("stats", {})
    nouvelles = []
    for k, (emo, nom, stat, seuil) in PET_HABITUDES.items():
        if k in st["habitudes"]:
            continue
        if st["stats"].get(stat, 0) >= seuil:
            st["habitudes"][k] = True
            nouvelles.append((emo, nom))
    return nouvelles

class SceneView(ui.View):
    """Choix sur une scène du moteur"""
    CHOIX = [
        [("😡", "Le gronder", "humeur", -6, "confiance", -2),
         ("😂", "En rire", "humeur", 10, "confiance", 3),
         ("🤨", "Lui demander ce qui s'est passé", "humeur", 4, "confiance", 5)],
        [("🤗", "Aller le voir", "confiance", 5, "humeur", 8),
         ("👀", "L'observer discrètement", "humeur", 3, "confiance", 1),
         ("😐", "Le laisser tranquille", "humeur", -2, "confiance", 0)],
        [("🎾", "Jouer avec lui", "humeur", 12, "confiance", 4),
         ("📸", "Immortaliser ça", "confiance", 3, "humeur", 4),
         ("🍖", "Lui donner quelque chose", "humeur", 8, "confiance", 3)],
    ]
    def __init__(self, uid, decor, reaction, timeout=150):
        super().__init__(timeout=timeout)
        self.uid, self.decor, self.reaction = uid, decor, reaction
        self.lot = random.choice(self.CHOIX)
        for i, (emo, label, j1, v1, j2, v2) in enumerate(self.lot):
            btn = ui.Button(label=label[:70], emoji=emo,
                            style=discord.ButtonStyle.primary if i == 0 else discord.ButtonStyle.secondary)
            async def cb(interaction, idx=i):
                if str(interaction.user.id) != self.uid:
                    return await interaction.response.send_message(
                        "❌ Ce n'est pas ton compagnon !", ephemeral=True)
                await self.resoudre(interaction, idx)
            btn.callback = cb
            self.add_item(btn)

    async def resoudre(self, interaction, idx):
        emo, label, j1, v1, j2, v2 = self.lot[idx]
        uid = self.uid
        pid, pdb, pst = get_active_pet(uid)
        st = pet_etat(uid)
        parts = []
        for jauge, val in ((j1, v1), (j2, v2)):
            if not val:
                continue
            if jauge == "confiance":
                pst["confiance"] = max(0, min(100, pst.get("confiance", 0) + val))
                parts.append(f"💞 Confiance **{'+' if val > 0 else ''}{val}**")
            else:
                st[jauge] = max(0, min(100, st[jauge] + val))
                parts.append(f"❤️ Humeur **{'+' if val > 0 else ''}{val}**")
        pst.setdefault("vecu", {})
        pst["vecu"]["scenes"] = pst["vecu"].get("scenes", 0) + 1
        save_all_data()
        for it in self.children:
            it.disabled = True
        await interaction.response.edit_message(embed=discord.Embed(
            description=(f"*{self.decor}*\n\n{self.reaction}\n\n"
                         f"➡️ **{label}**\n\n" + "  ·  ".join(parts)),
            color=0xe91e63), view=self)
        self.stop()

async def tenter_scene(ctx, uid):
    """Une scène du moteur — la variante dépend de tout le contexte du pet"""
    import time as _t
    pid, pdb, pst = get_active_pet(uid)
    if not pid:
        return False
    if _t.time() - pst.get("derniere_scene", 0) < 3600:
        return False
    if random.random() > 0.45:
        return False
    K = _ctx_pet(uid)
    pool = [s for s in SCENES_PETS if _scene_possible(s, K)]
    # On évite de répéter les 5 dernières
    recentes = pst.get("scenes_vues", [])
    frais = [s for s in pool if s["id"] not in recentes]
    sc = random.choice(frais or pool)
    pst["derniere_scene"] = _t.time()
    pst.setdefault("scenes_vues", []).append(sc["id"])
    pst["scenes_vues"] = pst["scenes_vues"][-5:]

    decor, reaction, _ = rendu_scene(uid, sc)
    # Si cette réaction précise vient d'être vue, on retire un nouveau rendu
    for _ in range(3):
        if reaction not in pst.get("vus", {}).get("reaction", []):
            break
        decor, reaction, _ = rendu_scene(uid, sc)
    pst.setdefault("vus", {}).setdefault("reaction", []).append(reaction)
    pst["vus"]["reaction"] = pst["vus"]["reaction"][-10:]
    if random.random() < 0.45:
        vue = SceneView(uid, decor, reaction)
        await ctx.send(embed=discord.Embed(
            description=f"*{decor}*\n\n{reaction}\n\n**Que fais-tu ?**",
            color=0xf39c12), view=vue)
    else:
        st = pet_etat(uid)
        st["humeur"] = min(100, st["humeur"] + 3)
        save_all_data()
        await ctx.send(embed=discord.Embed(
            description=f"*{decor}*\n\n{reaction}", color=0xe91e63))
    return True

class PetEventView(ui.View):
    """Choix lors d'un événement spontané"""
    def __init__(self, uid, evt, pdb, timeout=120):
        super().__init__(timeout=timeout)
        self.uid, self.evt, self.pdb = uid, evt, pdb
        self.resolu = False
        for i, (label, typ, val) in enumerate(evt["choix"]):
            btn = ui.Button(label=label[2:].strip()[:70], emoji=label.split()[0],
                            style=[discord.ButtonStyle.primary, discord.ButtonStyle.secondary,
                                   discord.ButtonStyle.success][i % 3])
            async def cb(interaction, idx=i):
                if str(interaction.user.id) != self.uid:
                    return await interaction.response.send_message(
                        "❌ C'est le compagnon de quelqu'un d'autre !", ephemeral=True)
                if self.resolu:
                    return await interaction.response.defer()
                self.resolu = True
                await self.resoudre(interaction, idx)
            btn.callback = cb
            self.add_item(btn)

    async def resoudre(self, interaction, idx):
        label, typ, val = self.evt["choix"][idx]
        uid = self.uid
        st = pet_etat(uid)
        pid, pdb, pst = get_active_pet(uid)
        resultat = ""
        if typ == "humeur":
            st["humeur"] = max(0, min(100, st["humeur"] + val))
            resultat = f"❤️ Humeur **{'+' if val >= 0 else ''}{val}**"
        elif typ == "xp":
            l, lv = give_pet_xp(uid, val)
            resultat = f"⭐ **+{val} XP**" + (f"\n🆙 Niveau **{lv}** !" if l else "")
        elif typ == "energie":
            st["energie"] = min(100, st["energie"] + val)
            resultat = f"⚡ Énergie **+{val}**"
        elif typ == "pieces":
            economy_data[uid]["coins"] += val
            if val > 0:
                gazette_gain(uid, val)
                pet_stat(uid, "pieces_rapportees", val)
            resultat = f"💰 **{'+' if val >= 0 else ''}{val:,} pièces**"
        elif typ == "objet":
            pst.setdefault("objets", [])
            # Objet imposé par l'événement, sinon tirage à la rareté
            nom_o = val if val in PET_OBJETS_TROUVES else tirer_objet(uid)
            if nom_o in pst["objets"]:
                nom_o = tirer_objet(uid)
            if nom_o not in pst["objets"]:
                pst["objets"].append(nom_o)
                premier = len(pst["objets"]) == 1
                if not pst.get("objet_prefere"):
                    pst["objet_prefere"] = nom_o
                emo, desc, eff, bonus, rar = PET_OBJETS_TROUVES[nom_o]
                r_emo, r_nom, r_coul, _ = objet_rarete(nom_o)
                LAB = {"coins":"pièces","xp":"XP","roll":"rolls","humeur":"humeur"}
                resultat = (f"{emo} **{nom_o}**  {r_emo} *{r_nom}*\n*{desc}*\n"
                            f"└ +{bonus} % {LAB.get(eff, eff)}")
                pet_carnet_note(uid, f"{emo} A trouvé **{nom_o}** ({r_nom}).",
                                important=rar in ("epique", "legendaire", "mythique") or premier)
                if rar in ("legendaire", "mythique"):
                    gazette_fait("divers",
                                 f"Le compagnon de <@{uid}> a déniché {emo} **{nom_o}** — un objet {r_nom} !", 4)
                pet_stat(uid, "objets_trouves")
            else:
                st["humeur"] = min(100, st["humeur"] + 8)
                resultat = "🎁 Il en avait déjà un… ❤️ Humeur **+8**"
        elif typ == "expe":
            resultat = "🎒 *Prépare-le avec `.petexpedition <lieu>` !*"
        elif typ == "aventure":
            st["humeur"] = min(100, st["humeur"] + 10)
            resultat = "🐦 L'oiseau s'est envolé. ❤️ Humeur **+10**"

        for it in self.children:
            it.disabled = True
        pet_carnet_note(uid, f"{self.evt['titre'].split()[0]} {label[2:].strip()}.")
        save_all_data()
        e = discord.Embed(
            title=self.evt["titre"],
            description=f"*{self.evt['texte'].format(p=f'**{pet_nom_decore(uid, pdb)}**')}*\n\n"
                        f"➡️ **{label}**\n\n{resultat}",
            color=0xe91e63)
        e.set_footer(text=pet_humeur_texte(st))
        await interaction.response.edit_message(embed=e, view=self)
        self.stop()

async def tenter_event_vie(ctx, uid):
    """25 % de chance qu'un événement spontané se déclenche"""
    import time as _t
    pid, pdb, pst = get_active_pet(uid)
    if not pid:
        return False
    dernier = pst.get("dernier_event_vie", 0)
    if _t.time() - dernier < 5400:      # 1 h 30 minimum entre deux
        return False
    if random.random() > 0.25:
        return False
    pst["dernier_event_vie"] = _t.time()

    # Les traits favorisent certains événements
    traits = pst.get("traits", [])
    pool = [e for e in PET_EVENTS_VIE if not e.get("trait") or e["trait"] in traits]
    lies = [e for e in PET_EVENTS_VIE if e.get("trait") and e["trait"] in traits]
    evt = random.choice(lies) if (lies and random.random() < 0.5) else random.choice(pool or PET_EVENTS_VIE)

    vue = PetEventView(uid, evt, pdb)
    await ctx.send(embed=discord.Embed(
        title=f"⚠️ {evt['titre']}",
        description=(f"*{evt['texte'].format(p=f'**{pet_nom_decore(uid, pdb)}**')}*\n\n"
                     f"**Que fais-tu ?**"),
        color=0xf39c12).set_footer(text="Ton choix aura un effet."), view=vue)
    return True

