CHRONIQUE = {}          # état courant, persisté
CHRONIQUE_LU = {}       # {uid: nb d'épisodes suivis} — statistiques lecteurs
_CHRO_LOCK = asyncio.Lock()
CHRO_ETATS = ("IDLE", "EPISODE", "VOTE", "EGALITE", "ATTENTE", "TERMINEE")
CHRO_DELAI_SCENE = 4        # secondes entre deux scènes d'un même épisode
CHRO_DUREE_VOTE = 86400     # le vote reste ouvert jusqu'à ce que l'admin ferme
CHRO_PROLONGATION = 300     # rallonge en cas d'égalité

def chro_salon(guild):
    return guild.get_channel(SALON_CHRONIQUE_ID) if (guild and SALON_CHRONIQUE_ID) else None

def chro_active():
    return bool(CHRONIQUE) and CHRONIQUE.get("etat") not in (None, "TERMINEE")

def chro_saison():
    return CHRONIQUE_SAISONS.get(CHRONIQUE.get("saison"))

def chro_episode():
    s = chro_saison()
    if not s:
        return None
    i = CHRONIQUE.get("episode", 1) - 1
    eps = s["episodes"]
    return eps[i] if 0 <= i < len(eps) else None

def chro_drapeau(nom):
    """Un drapeau posé par un choix passé. Invisible pour les lecteurs."""
    return nom in (CHRONIQUE.get("drapeaux") or [])

def chro_poser(*noms):
    d = CHRONIQUE.setdefault("drapeaux", [])
    for n in noms:
        if n and n not in d:
            d.append(n)

def chro_fermer_route(*routes):
    f = CHRONIQUE.setdefault("routes_fermees", [])
    for r in routes:
        if r and r not in f:
            f.append(r)

def chro_route_ouverte(r):
    return r not in (CHRONIQUE.get("routes_fermees") or [])

# ── Renderer : le contenu narratif ne dépend jamais de la mise en page ──
# Les scènes restent des textes purs dans CHRONIQUE_SAISONS.
# Ce sont ces fonctions, et elles seules, qui décident du rendu Discord.

CHRO_SEP = "━━━━━━━━━━━━━━━━━━━━"

def chro_est_dialogue(bloc_):
    """Un paragraphe qui commence par un guillemet français."""
    return bloc_.lstrip().startswith("«")

def chro_marqueur_scene(texte):
    """Repère un en-tête de scène en italique du type *Deux heures plus tôt.*"""
    prem = texte.lstrip().split("\n", 1)[0].strip()
    if prem.startswith("*") and prem.endswith("*") and 4 < len(prem) < 90:
        return prem.strip("*").strip()
    return None

def chro_rendu_scene(texte, numero=None):
    """Transforme une scène en contenu Discord lisible sur mobile.
    Les dialogues respirent, les en-têtes de scène ressortent."""
    entete = chro_marqueur_scene(texte)
    corps = texte
    if entete:
        corps = texte.lstrip().split("\n", 1)[1].lstrip() if "\n" in texte.lstrip() else ""
    lignes = []
    if entete:
        lignes.append(f"### ◈ {entete}")
        lignes.append("")
    for para in corps.split("\n\n"):
        p = para.strip()
        if not p:
            continue
        lignes.append(p)
        lignes.append("")
    return "\n".join(lignes).rstrip()

def chro_grouper_scenes(scenes, max_car=1700):
    """Regroupe les scènes courtes pour éviter une avalanche d'embeds espacés.
    Le découpage suit la narration : on ne coupe jamais au milieu d'une scène."""
    paquets, courant = [], []
    taille = 0
    for sc in scenes:
        n = len(sc)
        # Une scène avec en-tête ouvre toujours un nouveau bloc
        if courant and (taille + n > max_car or chro_marqueur_scene(sc)):
            paquets.append(courant)
            courant, taille = [], 0
        courant.append(sc)
        taille += n
    if courant:
        paquets.append(courant)
    return paquets

def chro_scenes_visibles(ep):
    """Filtre les scènes conditionnelles selon les drapeaux déjà posés."""
    out = []
    for sc in ep.get("scenes", []):
        if isinstance(sc, dict):
            si, sauf = sc.get("si"), sc.get("sauf")
            if si and not chro_drapeau(si):
                continue
            if sauf and chro_drapeau(sauf):
                continue
            out.append(sc["texte"])
        else:
            out.append(sc)
    return out

def chro_enregistrer_choix(num_ep, cle, libelle):
    """Un choix validé est canonique. Aucun retour arrière."""
    h = CHRONIQUE.setdefault("historique", [])
    if any(x["episode"] == num_ep for x in h):
        return False                       # jamais deux décisions pour un même épisode
    h.append({"episode": num_ep, "cle": cle, "libelle": libelle, "t": time.time()})
    return True

def chro_ending():
    """Détermine la fin d'après l'ENSEMBLE des décisions, jamais un vote unique."""
    s = chro_saison()
    if not s:
        return None
    meilleur, score_max = None, None
    for cle, fin in s["endings"].items():
        if not chro_route_ouverte(fin.get("route", cle)):
            continue
        exige = fin.get("exige", [])
        # Une fin ne se déclenche que si TOUTES ses conditions sont réunies.
        if exige and not all(chro_drapeau(d) for d in exige):
            continue
        if any(chro_drapeau(d) for d in fin.get("interdit", [])):
            continue
        score = len(exige) * 10 + fin.get("poids", 0)
        if score_max is None or score > score_max:
            meilleur, score_max = cle, score
    return meilleur or s.get("ending_defaut")

def chro_choix_decisifs():
    """Les décisions qui ont réellement orienté la fin."""
    s = chro_saison()
    if not s:
        return []
    fin = s["endings"].get(CHRONIQUE.get("ending") or "")
    marquants = set((fin or {}).get("exige", []))
    out = []
    for h in CHRONIQUE.get("historique", []):
        ep = s["episodes"][h["episode"] - 1] if h["episode"] <= len(s["episodes"]) else None
        pose = ((ep or {}).get("choix", {}).get("suites", {}).get(h["cle"], {}) or {}).get("pose", [])
        if marquants & set(pose) or (ep or {}).get("choix", {}).get("decisif"):
            out.append(h)
    return out or CHRONIQUE.get("historique", [])[:4]

def chro_reset():
    CHRONIQUE.clear()

async def chro_reprendre_apres_restart():
    """Au démarrage : on tente de récupérer le vote en cours.
    Si le message existe encore, on réattache une View fonctionnelle.
    S'il a disparu, on sort du faux état VOTE et on propose une republication."""
    if not CHRONIQUE:
        return None
    etat = CHRONIQUE.get("etat")
    info = {"etat": etat, "episode": CHRONIQUE.get("episode")}
    if etat == "EPISODE":
        CHRONIQUE["etat"] = "ATTENTE"
        info["episode_interrompu"] = True
        return info
    if etat not in ("VOTE", "EGALITE"):
        return info
    mid, cid = CHRONIQUE.get("msg_vote"), CHRONIQUE.get("salon_vote")
    ep = chro_episode()
    choix = (ep or {}).get("choix")
    if not (mid and cid and choix):
        CHRONIQUE["etat"] = "ATTENTE"
        CHRONIQUE["vote_a_republier"] = True
        info["vote_perdu"] = True
        return info
    for g in bot.guilds:
        salon = g.get_channel(cid)
        if not salon:
            continue
        try:
            msg = await salon.fetch_message(mid)
        except Exception:
            break                      # message supprimé ou introuvable
        vue = ChroVoteView(CHRONIQUE.get("episode"), choix, msg=msg)
        try:
            bot.add_view(vue, message_id=mid)     # réattache les interactions
            await msg.edit(embed=vue.embed(g), view=vue)
            info["vote_restaure"] = True
            info["votes"] = len(CHRONIQUE.get("votes") or {})
            return info
        except Exception as e:
            print(f"[Chronique] restauration du vote : {type(e).__name__}: {e}")
            break
    # Message introuvable : on refuse de rester dans un faux état VOTE
    CHRONIQUE["etat"] = "ATTENTE"
    CHRONIQUE["vote_a_republier"] = True
    info["vote_perdu"] = True
    return info

