# ── Niveaux d'évolution du refuge ──
PET_REFUGE_NIVEAUX = [
    (0,  "🏚️", "Petite pièce",       "Quatre murs et beaucoup de bonne volonté."),
    (3,  "🏠", "Petit refuge",        "Ça commence à ressembler à quelque chose."),
    (6,  "🏡", "Maison cosy",         "On s'y sent bien. Lui le premier."),
    (10, "🏘️", "Grande maison",       "Il a de la place pour courir maintenant."),
    (14, "🏰", "Villa",               "Le luxe. Il ne veut plus sortir."),
    (18, "🌴", "Domaine légendaire",  "Le plus beau refuge du QG."),
]

def refuge_niveau(nb_meubles):
    """Retourne (seuil, emoji, nom, description, numéro) du niveau de refuge"""
    actuel, num = PET_REFUGE_NIVEAUX[0], 1
    for i, n in enumerate(PET_REFUGE_NIVEAUX, 1):
        if nb_meubles >= n[0]:
            actuel, num = n, i
    return actuel[0], actuel[1], actuel[2], actuel[3], num

def refuge_niveau_suivant(nb_meubles):
    """Le palier suivant, ou None si le refuge est complet"""
    return next((n for n in PET_REFUGE_NIVEAUX if n[0] > nb_meubles), None)

def piece_de(meuble):
    """Dans quelle pièce se range ce meuble"""
    for cle, (emo, nom, meubles) in PET_PIECES.items():
        if meuble in meubles:
            return cle, emo, nom
    return "divers", "📦", "Divers"

def pet_accessoires(uid):
    """Liste des accessoires portés par le compagnon actif"""
    d = pets_data.get(uid, {})
    pid = d.get("active")
    if not pid:
        return []
    return d.get("owned", {}).get(pid, {}).get("portes", [])

def pet_nom_decore(uid, pdb):
    """Nom (ou surnom) du compagnon avec ses accessoires visibles"""
    acc = "".join(PET_ACCESSOIRES[a][0] for a in pet_accessoires(uid) if a in PET_ACCESSOIRES)
    d = pets_data.get(uid, {})
    pid = d.get("active")
    surnom = d.get("owned", {}).get(pid, {}).get("surnom") if pid else None
    return f"{pdb['emoji']} {surnom or pdb['nom']}" + (f" {acc}" if acc else "")

def bonus_accessoires(uid, type_bonus):
    """Bonus cumulé des accessoires portés"""
    total = 0
    for a in pet_accessoires(uid):
        conf = PET_ACCESSOIRES.get(a)
        if conf and conf[3] == type_bonus:
            total += conf[4]
    return total

def bonus_refuge(uid, type_bonus):
    """Bonus cumulé des meubles du refuge"""
    total = 0
    for m in pets_data.get(uid, {}).get("refuge", []):
        conf = PET_MEUBLES.get(m)
        if conf and conf[3] == type_bonus:
            total += conf[4]
    return total

@bot.command(name="garderobe", aliases=["wardrobe", "accessoires"])
async def garderobe_cmd(ctx, action: str = None, *, objet: str = None):
    """La garde-robe de ton compagnon — .garderobe [acheter|porter|retirer] <objet>"""
    uid = str(ctx.author.id)
    pid, pdb, pst = get_active_pet(uid)
    if not pid:
        return await ctx.send("🐾 Tu n'as pas de compagnon actif ! Rends-toi dans `.shop`.")
    d = pets_data[uid]["owned"][pid]
    d.setdefault("garderobe", [])
    d.setdefault("portes", [])

    if not action or action.lower() in ("voir", "liste"):
        LAB = {"humeur":"❤️ humeur","coins":"💰 pièces","xp":"⭐ XP","roll":"🎰 rolls"}
        gouts_a = gouts_accessoires(uid)
        SYM = {"adore":"❤️","neutre":"😐","deteste":"😖"}
        e = discord.Embed(
            title=f"🎀 Garde-robe de {pet_nom_decore(uid, pdb)}",
            description="*Trois accessoires portés maximum. Ils s'ajoutent au bonus de race.*",
            color=0xe91e63)

        # ── Portés ──
        if d["portes"]:
            cumul = []
            for typ, lab in LAB.items():
                v = bonus_accessoires(uid, typ)
                if v: cumul.append(f"{lab} **+{v} %**")
            e.add_field(name=f"🎀 Portés — {len(d['portes'])}/3", value="\n".join(
                f"{PET_ACCESSOIRES[a][0]} **{PET_ACCESSOIRES[a][1]}** "
                f"{SYM.get(gouts_a.get(a), '')}\n　*+{PET_ACCESSOIRES[a][4]} % "
                f"{LAB[PET_ACCESSOIRES[a][3]].split(' ',1)[1]}*"
                for a in d["portes"] if a in PET_ACCESSOIRES)
                + (f"\n\n**Cumul :** {'  ·  '.join(cumul)}" if cumul else ""), inline=False)
        else:
            e.add_field(name="🎀 Portés — 0/3",
                        value="*Il ne porte rien pour l'instant.*", inline=False)

        # ── Possédés mais non portés ──
        ranges = [a for a in d["garderobe"] if a not in d["portes"]]
        if ranges:
            e.add_field(name=f"🎒 Dans son coffre — {len(ranges)}", value="  ·  ".join(
                f"{PET_ACCESSOIRES[a][0]} **{PET_ACCESSOIRES[a][1]}** `{a}`"
                for a in ranges if a in PET_ACCESSOIRES)[:1024], inline=False)

        # ── À acheter ──
        dispo = [(k, v) for k, v in PET_ACCESSOIRES.items() if k not in d["garderobe"]]
        if dispo:
            lignes = [f"{v[0]} **{v[1]}** `{k}` — **{v[2]:,} p** · +{v[4]} % "
                      f"{LAB[v[3]].split(' ',1)[1]}" for k, v in dispo]
            for i in range(0, len(lignes), 6):
                e.add_field(name="🛍️ À acheter" if i == 0 else "\u200b",
                            value="\n".join(lignes[i:i+6]), inline=False)
        e.set_footer(text="`.garderobe acheter <objet>` · `porter` · `retirer`")
        return await ctx.send(embed=e)

    if not objet:
        return await ctx.send("❌ Précise un accessoire ! Ex : `.garderobe acheter noeud`")
    cle = normalize_str(objet).replace(" ", "")
    if cle not in PET_ACCESSOIRES:
        cle = next((k for k, v in PET_ACCESSOIRES.items()
                    if normalize_str(objet) in normalize_str(v[1])), None)
    if not cle:
        return await ctx.send(f"❌ Accessoire `{objet}` introuvable — tape `.garderobe` pour la liste.")
    emo, nom, prix, typ, val, desc = PET_ACCESSOIRES[cle]
    act = action.lower()

    if act in ("acheter", "achat", "buy"):
        if cle in d["garderobe"]:
            return await ctx.send(f"❌ Tu possèdes déjà **{nom}** !")
        if economy_data[uid]["coins"] < prix:
            return await ctx.send(f"❌ Il te faut **{prix:,} pièces** (tu en as {economy_data[uid]['coins']:,}).")
        economy_data[uid]["coins"] -= prix
        d["garderobe"].append(cle)
        pet_carnet_note(uid, f"A reçu {emo} **{nom}**.")
        if len(d["portes"]) < 3:
            d["portes"].append(cle)
        save_all_data()
        return await ctx.send(embed=discord.Embed(
            title=f"👗 {emo} {nom}",
            description=(f"**{pet_nom_decore(uid, pdb)}**\n\n*{desc}*\n\n"
                         + ("✅ Porté immédiatement !" if cle in d["portes"]
                            else "🎒 Rangé dans la garde-robe — `.garderobe porter " + cle + "`")),
            color=0xe91e63))

    if act in ("porter", "equiper", "mettre"):
        if cle not in d["garderobe"]:
            return await ctx.send(f"❌ Tu ne possèdes pas **{nom}** — `.garderobe acheter {cle}`")
        if cle in d["portes"]:
            return await ctx.send(f"✅ **{nom}** est déjà porté !")
        if len(d["portes"]) >= 3:
            return await ctx.send("❌ Trois accessoires maximum ! Retires-en un d'abord.")
        d["portes"].append(cle)
        gouts_a = gouts_accessoires(uid)
        premiere = cle not in gouts_a
        if premiere:
            gouts_a[cle] = random.choices(["adore", "neutre", "deteste"], weights=[45, 40, 15])[0]
        pool = ACC_REACTIONS.get(cle, []) + ACC_REACTIONS["defaut"]
        reaction = _sans_repet(uid, "acc_" + cle, pool, memoire=2).replace(
            "{p}", f"**{pet_nom_decore(uid, pdb)}**")
        SYM = {"adore": ("❤️", "Il adore cet accessoire !"),
               "neutre": ("😐", "Ça lui est égal."),
               "deteste": ("😖", "Il ne l'aime pas trop.")}
        e_g, t_g = SYM[gouts_a[cle]]
        emb = discord.Embed(title=f"{emo} {nom}", description=reaction, color=0xe91e63)
        if premiere:
            emb.add_field(name=f"{e_g} Première fois", value=f"*{t_g}*", inline=False)
            if gouts_a[cle] == "adore":
                pet_carnet_note(uid, f"{emo} A adoré porter **{nom}**.", important=True)
        emb.set_footer(text=f"Porté : {len(d['portes'])}/3")
        save_all_data()
        return await ctx.send(embed=emb)

    if act in ("retirer", "enlever", "remove"):
        if cle not in d["portes"]:
            return await ctx.send(f"❌ **{nom}** n'est pas porté.")
        d["portes"].remove(cle)
        save_all_data()
        return await ctx.send(f"👗 **{nom}** retiré. {pet_nom_decore(uid, pdb)}")

    await ctx.send("❌ Action inconnue : `acheter`, `porter` ou `retirer`.")

@bot.command(name="refuge", aliases=["maison", "petmaison"])
async def refuge_cmd(ctx, action: str = None, *, objet: str = None):
    """Le refuge de ton compagnon — .refuge [acheter] <meuble>"""
    uid = str(ctx.author.id)
    pid, pdb, pst = get_active_pet(uid)
    if not pid:
        return await ctx.send("🐾 Tu n'as pas de compagnon actif ! Rends-toi dans `.shop`.")
    pets_data[uid].setdefault("refuge", [])
    ref = pets_data[uid]["refuge"]

    EFFETS_L = {"humeur_lente": "❤️ humeur préservée", "faim_lente": "🍖 faim ralentie",
                "energie_lente": "⚡ énergie conservée", "xp_passif": "⭐ XP passive",
                "saletes_lente": "🧹 refuge salit moins vite"}
    if action and action.lower() in ("liste", "catalogue", "tout"):
        EFFETS_L = {"humeur_lente": "❤️ humeur préservée", "faim_lente": "🍖 faim ralentie",
                    "energie_lente": "⚡ énergie conservée", "proprete_lente": "🧼 propreté conservée", "saletes_lente": "🧹 refuge salit moins vite",
                    "xp_passif": "⭐ XP passive"}
        e = discord.Embed(
            title="🏡 Catalogue du refuge",
            description=("*Chaque meuble se range dans une pièce et aide ton compagnon au quotidien.*\n"
                         f"*Tu en as **{len(ref)}/{len(PET_MEUBLES)}**.*"),
            color=0xe91e63)
        for cle, (p_emo, p_nom, meubles) in PET_PIECES.items():
            lignes = []
            for k in meubles:
                emo, nom, prix, typ, val, desc = PET_MEUBLES[k]
                etat = "✅ **installé**" if k in ref else f"🛒 **{prix:,} p**"
                lignes.append(f"{emo} **{nom}** — `{k}` · {etat}\n"
                              f"　{EFFETS_L[typ]} **+{val}{'/h' if typ=='xp_passif' else ' %'}**\n"
                              f"　*{desc}*")
            e.add_field(name=f"{p_emo} {p_nom}  ·  {sum(1 for k in meubles if k in ref)}/{len(meubles)}",
                        value="\n".join(lignes), inline=False)
        e.set_footer(text="`.refuge acheter <meuble>` pour installer")
        return await ctx.send(embed=e)


    if action and action.lower() in ("acheter", "achat", "buy"):
        if not objet:
            return await ctx.send("❌ Précise un meuble ! Ex : `.refuge acheter panier`")
        cle = normalize_str(objet).replace(" ", "")
        if cle not in PET_MEUBLES:
            cle = next((k for k, v in PET_MEUBLES.items()
                        if normalize_str(objet) in normalize_str(v[1])), None)
        if not cle:
            return await ctx.send(f"❌ Meuble `{objet}` introuvable — tape `.refuge` pour la liste.")
        emo, nom, prix, typ, val, desc = PET_MEUBLES[cle]
        if cle in ref:
            return await ctx.send(f"❌ **{nom}** est déjà dans le refuge !")
        if economy_data[uid]["coins"] < prix:
            return await ctx.send(f"❌ Il te faut **{prix:,} pièces** (tu en as {economy_data[uid]['coins']:,}).")
        economy_data[uid]["coins"] -= prix
        ref.append(cle)
        pet_carnet_note(uid, f"{emo} **{nom}** a été installé dans le refuge.")
        save_all_data()
        _pc, _pe, _pn = piece_de(cle)
        _av = refuge_niveau(len(ref) - 1)
        _ap = refuge_niveau(len(ref))
        _msg = (f"*{desc}*\n\n"
                f"📍 Installé dans **{_pe} {_pn}**\n"
                f"**{pet_nom_decore(uid, pdb)}** vient déjà l'inspecter.")
        if _av[4] != _ap[4]:
            _msg += (f"\n\n### {_ap[1]} Le refuge s'agrandit !\n"
                     f"Il devient **{_ap[2]}** *(niveau {_ap[4]})*\n*{_ap[3]}*")
            pet_carnet_note(uid, f"{_ap[1]} Son refuge est devenu **{_ap[2]}**.", important=True)
        return await ctx.send(embed=discord.Embed(
            title=f"🏡 {emo} {nom} installé !",
            description=_msg, color=0x2ecc71))

    # ── Visite du refuge ──
    st = pet_etat(uid)
    nb = len(ref)
    n_emo, n_nom, n_desc, n_num = refuge_niveau(nb)[1], refuge_niveau(nb)[2], refuge_niveau(nb)[3], refuge_niveau(nb)[4]
    nom_pet = pst.get("surnom") or pdb["nom"]

    p_ref, e_ref, n_ref, d_ref = etat_refuge(uid)
    f_ref = max(0, min(10, p_ref // 10))
    scenes = scene_actuelle(uid)
    embed = discord.Embed(
        title=f"{n_emo}  Refuge de {nom_pet}",
        description=(f"✨ **{n_nom}** — Niveau **{n_num}**\n*{n_desc}*\n\n"
                     f"━━━━━━━━━━━━━━━━━━\n\n"
                     f"### 🏡 En ce moment\n" + "\n".join(scenes) + "\n\n"
                     f"🧹 **Propreté du refuge**\n"
                     f"`{'▰'*f_ref}{'▱'*(10-f_ref)}` **{p_ref} %**  {e_ref} *{n_ref}*"
                     + ("\n➡️ `.nettoyer`" if p_ref < 65 else "")),
        color=0xe91e63)

    # ── Les pièces, une par une ──
    for cle, (p_emo, p_nom, meubles) in PET_PIECES.items():
        presents = [m for m in meubles if m in ref]
        total = len(meubles)
        if presents:
            lignes = [f"{PET_MEUBLES[m][0]} **{PET_MEUBLES[m][1]}**\n"
                      f"　*{PET_MEUBLES[m][5]}*" for m in presents]
            corps = "\n".join(lignes)
            vides = total - len(presents)
            if vides:
                corps += f"\n\n*{vides} emplacement(s) libre(s)*"
        else:
            corps = "*Pièce vide pour l'instant…*"
        embed.add_field(name=f"{p_emo} {p_nom}  ·  {len(presents)}/{total}",
                        value=corps, inline=False)

    # ── Le compagnon et les effets ──
    EFFETS = [("humeur_lente", "❤️", "Humeur préservée", "%"),
              ("faim_lente",   "🍖", "Faim ralentie",    "%"),
              ("energie_lente","⚡", "Énergie conservée", "%"),
              ("proprete_lente","🧼","Propreté conservée","%"),
              ("saletes_lente","🧹","Refuge salit moins vite","%"),
              ("xp_passif",    "⭐", "XP passive",       "/h")]
    lignes_e = []
    for typ, emo, lab, unite in EFFETS:
        v = bonus_refuge(uid, typ)
        if v:
            lignes_e.append(f"{emo} {lab} **+{v}{unite}**")
    embed.add_field(
        name="━━━━━━━━━━━━━━━━━━",
        value=(f"🐾 **{pet_nom_decore(uid, pdb)}**\n{pet_humeur_texte(st)}\n\n"

               + ("\n".join(lignes_e) if lignes_e
                  else "*Aucun effet — installe des meubles pour l'aider au quotidien.*")),
        inline=False)

    # ── Prochain palier ──
    suiv = refuge_niveau_suivant(nb)
    if suiv:
        manque = suiv[0] - nb
        embed.add_field(name="🔨 Agrandir le refuge",
                        value=(f"Encore **{manque} meuble(s)** pour devenir "
                               f"**{suiv[1]} {suiv[2]}**\n*{suiv[3]}*"), inline=False)

    # ── À installer ──
    dispo = [(k, v) for k, v in PET_MEUBLES.items() if k not in ref]
    if dispo:
        EFF_COURT = {"humeur_lente": "❤️ humeur", "faim_lente": "🍖 faim",
                     "energie_lente": "⚡ énergie", "proprete_lente": "🧼 propreté",
                     "xp_passif": "⭐ XP passive",
                "saletes_lente": "🧹 refuge salit moins vite"}
        lot = sorted(dispo, key=lambda x: x[1][2])[:5]
        embed.add_field(name="🛒 À installer",
                        value="\n".join(
                            f"{v[0]} **{v[1]}** — `{k}` · **{v[2]:,} p**  ·  "
                            f"{EFF_COURT[v[3]]} +{v[4]}{'/h' if v[3]=='xp_passif' else ' %'}"
                            f"  ·  {piece_de(k)[1]} {piece_de(k)[2]}"
                            for k, v in lot)
                        + (f"\n\n*…et {len(dispo)-5} autre(s) — `.refuge liste`*"
                           if len(dispo) > 5 else ""), inline=False)
        embed.set_footer(text=f"{nb}/{len(PET_MEUBLES)} meubles · `.refuge acheter <meuble>`")
    else:
        embed.set_footer(text="🌴 Refuge complet — il ne manque plus rien.")
    await ctx.send(embed=embed)


@bot.command(name="petvisite", aliases=["visite", "petrencontre"])
async def petvisite_cmd(ctx, ami: discord.Member = None):
    """Fais rencontrer ton compagnon à celui d'un ami — .petvisite @ami"""
    import time as _t
    if not ami or ami.bot or ami.id == ctx.author.id:
        return await ctx.send("❌ Mentionne un ami ! Ex : `.petvisite @ami`")
    uid, aid = str(ctx.author.id), str(ami.id)
    p1, db1, st1 = get_active_pet(uid)
    p2, db2, st2 = get_active_pet(aid)
    if not p1:
        return await ctx.send("🐾 Tu n'as pas de compagnon actif ! Rends-toi dans `.shop`.")
    if not p2:
        return await ctx.send(f"🐾 **{ami.display_name}** n'a pas de compagnon actif.")

    cle_cd = "visite_" + aid
    e1 = pet_etat(uid)
    reste = 6 * 3600 - (_t.time() - e1["dernier"].get(cle_cd, 0))
    if reste > 0:
        h, m = divmod(int(reste) // 60, 60)
        return await ctx.send(f"⏳ Vos compagnons se sont vus récemment — revenez dans **{h}h{m:02d}**.",
                              delete_after=8)
    e1["dernier"][cle_cd] = _t.time()
    e2 = pet_etat(aid)

    # ── Amitié ──
    cle_am = _cle_amitie(uid, aid)
    avant = petamitie[cle_am]
    _clash = relation_incompatible(uid, aid)
    petamitie[cle_am] += (1 if not _clash or random.random() < 0.5 else 0)
    apres = petamitie[cle_am]
    (seuil, emo_p, nom_p, desc_p, bonus_p), suivant = palier_relation(apres)
    monte = palier_relation(avant)[0][2] != nom_p
    clash = relation_incompatible(uid, aid)

    # ── Scène adaptée au niveau d'amitié ──
    niveau = "debut" if apres < 5 else ("moyen" if apres < 15 else "haut")
    _pool_v = _pool_contextuel(uid, PETVISITE_SCENES[niveau], PETVISITE_CTX)
    scene = _sans_repet(uid, "visite_" + niveau, _pool_v, memoire=20).format(
        a=f"**{pet_nom_decore(uid, db1)}**", b=f"**{pet_nom_decore(aid, db2)}**")

    # ── Effets de base ──
    gain_humeur = 20 + min(20, apres)
    for st in (e1, e2):
        st["humeur"] = min(100, st["humeur"] + gain_humeur)
    xp_gagne = 40 + apres * 3
    l1, n1 = give_pet_xp(uid, xp_gagne)
    l2, n2 = give_pet_xp(aid, xp_gagne)

    # ── Récompense surprise ──
    typ, emo, txt = random.choice(PETVISITE_BONUS)
    lignes_r = []
    if typ == "pieces":
        montant = random.randint(80, 250) + bonus_p
        for u in (uid, aid):
            economy_data[u]["coins"] += montant
            gazette_gain(u, montant)
        lignes_r.append(f"🌈 Humeur améliorée")
        lignes_r.append(f"💛 **+{montant:,} pièces** chacun")
    elif typ == "xp":
        for u in (uid, aid):
            xp_data[u]["xp"] += 60
        lignes_r.append("🌈 Humeur améliorée")
        lignes_r.append("🎓 **+60 XP** de membre chacun")
    elif typ == "humeur":
        for st in (e1, e2):
            st["humeur"] = 100
            st["faim"] = max(0, st["faim"] - 20)
        lignes_r.append("🌈 **Humeur au maximum** pour les deux")
    elif typ == "item":
        objet = random.choice(["cafe", "shield", "double_rien", "boost_rarete"])
        nom_obj = next((i["nom"] for i in SHOP_ITEMS if i["id"] == objet), objet)
        for u in (uid, aid):
            inventaire[u][objet] += 1
        lignes_r.append("🌈 Humeur améliorée")
        lignes_r.append(f"🎁 **{nom_obj}** pour chacun")
    else:
        lignes_r.append(f"{emo} Humeur améliorée")
        lignes_r.append(f"*{txt}*")

    if bonus_p and typ != "pieces":
        for u in (uid, aid):
            economy_data[u]["coins"] += bonus_p
        lignes_r.append(f"💛 **+{bonus_p} pièces** grâce à leur complicité")
    recompense = "\n".join(lignes_r)

    ajouter_lien(uid, aid, "pet")
    pet_stat(uid, "rencontres")
    pet_stat(aid, "rencontres")
    pet_carnet_note(uid, f"A rencontré **{db2['nom']}** *({ami.display_name})* — {nom_p.lower()}.")
    pet_carnet_note(aid, f"A rencontré **{db1['nom']}** *({ctx.author.display_name})* — {nom_p.lower()}.")
    save_all_data()

    # ── Titre selon l'ambiance de la scène ──
    AMBIANCES = [
        (["soleil", "sieste", "endor", "dorm", "calme"],      "☀️", "Un moment tranquille"),
        (["papillon", "cour", "jou", "balle", "jouet"],       "🎾", "Une partie improvisée"),
        (["jardin", "quartier", "dehors", "boue", "buisson"], "🌳", "Une sortie à deux"),
        (["collier", "vole", "triche", "cache"],              "😈", "Encore une bêtise"),
        (["dispute", "meilleure place", "conteste"],          "💢", "Une petite dispute"),
        (["blotti", "coll", "tête", "garde", "auvent"],       "💕", "Un moment tendre"),
        (["nuit", "lune", "soir"],                            "🌙", "Une rencontre nocturne"),
        (["renifl", "méfian", "recule", "cache derrière"],    "👀", "Ils s'apprivoisent"),
    ]
    scene_min = normalize_str(scene)
    emo_t, titre_t = "🐾", "Une rencontre au QG"
    for mots, e_, t_ in AMBIANCES:
        if any(normalize_str(m) in scene_min for m in mots):
            emo_t, titre_t = e_, t_
            break

    n1_pet = db1["nom"] if not pets_data[uid]["owned"][p1].get("surnom") else pets_data[uid]["owned"][p1]["surnom"]
    n2_pet = db2["nom"] if not pets_data[aid]["owned"][p2].get("surnom") else pets_data[aid]["owned"][p2]["surnom"]
    lvl1 = pets_data[uid]["owned"][p1].get("level", 1)
    lvl2 = pets_data[aid]["owned"][p2].get("level", 1)

    # ── Barre de relation ──
    if suivant:
        prog = (apres - seuil) / max(1, suivant[0] - seuil)
        f = max(0, min(10, int(prog * 10)))
        barre = f"{'💗' * f}{'🤍' * (10 - f)}"
        manque = suivant[0] - apres
        suite = f"➡️ Encore **{manque}** rencontre{'s' if manque > 1 else ''} → {suivant[1]} {suivant[2]}"
    else:
        barre = "💗💗💗💗💗💗💗💗💗💗"
        suite = "👑 *Relation au maximum — rien ne les séparera.*"

    embed = discord.Embed(title=f"{emo_t}  {titre_t.upper()}", color=0xe91e63)

    # ── 1. Le duo, deux colonnes ──
    embed.add_field(
        name=f"{db1['emoji']} {n1_pet}",
        value=f"⭐ Niv. {lvl1}\n{pet_humeur_texte(e1)}",
        inline=True)
    embed.add_field(name="💞", value="\u200b", inline=True)
    embed.add_field(
        name=f"{db2['emoji']} {n2_pet}",
        value=f"⭐ Niv. {lvl2}\n{pet_humeur_texte(e2)}",
        inline=True)

    # ── 2. La scène, mise en valeur ──
    embed.add_field(name="\u200b", value=f"{emo_t}\n> *{scene}*", inline=False)

    # ── 3. La relation ──
    val_rel = f"{barre}\n{suite}\n\n*{desc_p}*"
    if clash:
        val_rel += f"\n💢 *{clash} — leur relation avance plus lentement.*"
    embed.add_field(name=f"💞 Relation — {emo_p} {nom_p}", value=val_rel, inline=False)

    # ── 4. Ce que la rencontre a changé ──
    embed.add_field(name="✨ Après cette rencontre",
                    value=f"{recompense}\n⭐ **+{xp_gagne} XP** chacun", inline=False)

    # ── 5. Le palier et les niveaux, seulement s'ils viennent d'arriver ──
    if monte:
        embed.add_field(name="🎉 Leur relation grandit !",
                        value=f"Ils passent au palier **{emo_p} {nom_p}**", inline=False)
        gazette_fait("divers", f"Les compagnons de **{ctx.author.display_name}** et "
                               f"**{ami.display_name}** sont devenus {nom_p}.", 2)
    if l1 and l2:
        embed.add_field(name="🎉 Double niveau supérieur !",
                        value=f"{db1['emoji']} **{n1_pet}** → Niveau {n1}\n"
                              f"{db2['emoji']} **{n2_pet}** → Niveau {n2}", inline=False)
    elif l1:
        embed.add_field(name="🆙 Niveau supérieur !",
                        value=f"{db1['emoji']} **{n1_pet}** → Niveau {n1}", inline=False)
    elif l2:
        embed.add_field(name="🆙 Niveau supérieur !",
                        value=f"{db2['emoji']} **{n2_pet}** → Niveau {n2}", inline=False)

    # ── 6. Leur histoire, discrètement ──
    JALONS = {1: "🌱 Leur histoire commence.",
              10: "💞 Ils commencent à avoir beaucoup de souvenirs ensemble.",
              25: "❤️ Ils ont vécu énormément de choses ensemble.",
              50: "👑 Ce duo est en train de devenir inséparable.",
              100: "🌟 Une amitié que tout le QG connaît."}
    jalon = JALONS.get(apres)
    hist = f"📖 **{apres} rencontre{'s' if apres > 1 else ''} ensemble**"
    if jalon:
        hist += f"\n{jalon}"
    embed.add_field(name="\u200b", value=hist, inline=False)

    _reste = int(6 * 3600 - (_t.time() - e1["dernier"].get(cle_cd, 0)))
    _h, _m = divmod(max(0, _reste) // 60, 60)
    embed.set_footer(text=f"⏳ Prochaine visite : {_h}h {_m:02d}min  ·  .petamis → toutes leurs relations")
    await ctx.send(f"{ami.mention}", embed=embed)


