def gouts_accessoires(uid):
    pid, pdb, st = get_active_pet(uid)
    if not st:
        return {}
    st.setdefault("gouts_acc", {})
    return st["gouts_acc"]

# ── 🧸 Objets sentimentaux ──
def objets_perso(uid):
    """Les objets qui racontent son histoire"""
    pid, pdb, st = get_active_pet(uid)
    if not st:
        return []
    st.setdefault("objets_perso", [])
    return st["objets_perso"]

def ajouter_objet_perso(uid, emoji, nom, origine):
    """Ajoute un objet sentimental (max 12)"""
    lst = objets_perso(uid)
    if any(o["nom"] == nom for o in lst):
        return False
    lst.append({"emoji": emoji, "nom": nom, "origine": origine, "surnom": None})
    if len(lst) > 12:
        lst.pop(0)
    return True

@bot.command(name="petsouvenirs", aliases=["objetsperso", "petmemoires"])
async def petsouvenirs_cmd(ctx, action: str = None, *, arg: str = None):
    """Les objets importants de ton compagnon — .petsouvenirs [nommer <n°> <nom>]"""
    uid = str(ctx.author.id)
    pid, pdb, pst = get_active_pet(uid)
    if not pid:
        return await ctx.send("🐾 Tu n'as pas de compagnon actif !")
    pet_init_perso(uid)
    lst = objets_perso(uid)

    if action and normalize_str(action) in ("nommer", "renommer", "baptiser"):
        if not arg or " " not in arg:
            return await ctx.send("❌ `.petsouvenirs nommer 1 Boubou`")
        num, _, nouveau = arg.partition(" ")
        if not num.isdigit() or not (1 <= int(num) <= len(lst)):
            return await ctx.send(f"❌ Numéro invalide — entre 1 et {len(lst)}.")
        nouveau = nouveau.strip()[:20]
        if len(nouveau) < 2 or any(x in nouveau for x in ("@", "http", "`", "\n")):
            return await ctx.send("❌ Nom invalide — 2 à 20 caractères, sans lien ni mention.")
        o = lst[int(num) - 1]
        o["surnom"] = nouveau
        pet_carnet_note(uid, f"{o['emoji']} A baptisé **{o['nom']}** : « {nouveau} ».", important=True)
        save_all_data()
        return await ctx.send(embed=discord.Embed(
            description=f"{o['emoji']} **{o['nom']}** s'appelle désormais **{nouveau}**.\n"
                        f"*Le bot l'utilisera dans ses scènes et ses rêves.*",
            color=0xe91e63))

    if not lst:
        return await ctx.send(embed=discord.Embed(
            title=f"🧸 Les objets de {pst.get('surnom') or pdb['nom']}",
            description=("*Il n'a encore rien de vraiment important.*\n\n"
                         "Les objets sentimentaux arrivent au fil de sa vie : "
                         "sa première trouvaille, un cadeau d'un ami, un souvenir d'expédition…"),
            color=0x95a5a6))
    lignes = []
    for i, o in enumerate(lst, 1):
        nom_aff = f"**{o['surnom']}**" + f" *({o['nom']})*" if o.get("surnom") else f"**{o['nom']}**"
        lignes.append(f"`{i}` {o['emoji']} {nom_aff}\n　*{o['origine']}*")
    await ctx.send(embed=discord.Embed(
        title=f"🧸 Les objets importants de {pet_nom_decore(uid, pdb)}",
        description="\n".join(lignes) + "\n\n*`.petsouvenirs nommer <n°> <nom>` pour en baptiser un.*",
        color=0xe91e63).set_footer(text="Ces objets racontent son histoire — ils apparaissent dans ses rêves"))

# ── 📊 Bilan de vie ──
BILANS = [30, 100, 365, 730]

async def verifier_bilan(uid, channel):
    """Un bilan aux grands caps de vie"""
    pid, pdb, pst = get_active_pet(uid)
    if not pst:
        return False
    jours = pet_jours(uid)
    faits = pst.setdefault("bilans", [])
    cap = next((b for b in BILANS if jours >= b and b not in faits), None)
    if not cap:
        return False
    faits.append(cap)
    s = pst.get("stats", {})
    v = pst.get("vecu", {})
    nom_pet = pst.get("surnom") or pdb["nom"]
    amis = [(k, x) for k, x in petamitie.items() if uid in k.split("|") and x > 0]
    meilleur = "—"
    if amis:
        cle_m = max(amis, key=lambda x: x[1])[0]
        autre = next((x for x in cle_m.split("|") if x != uid), None)
        if autre:
            _, a_pdb, a_pst = get_active_pet(autre)
            if a_pdb:
                meilleur = f"{a_pdb['emoji']} {a_pst.get('surnom') or a_pdb['nom']}"
    lignes = [
        f"🍖 **{s.get('repas', 0)}** repas partagés",
        f"🎾 **{s.get('parties', 0)}** sessions de jeu",
        f"🐾 **{s.get('rencontres', 0)}** rencontres avec d'autres compagnons",
        f"🗺️ **{v.get('expeditions', 0)}** expéditions",
        f"🎡 **{v.get('activites', 0)}** sorties ensemble",
        f"😈 **{v.get('betises', 0)}** bêtises",
        f"💎 **{len(pst.get('objets', [])) + len(pst.get('series', []))}** objets découverts",
        f"❤️ Meilleur ami : **{meilleur}**",
    ]
    if pst.get("objet_prefere"):
        lignes.append(f"🧸 Objet préféré : **{pst['objet_prefere']}**")
    if pst.get("repas_prefere"):
        lignes.append(f"🍽️ Plat préféré : **{pst['repas_prefere']}**")
    pet_carnet_note(uid, f"🎂 Bilan des **{cap} jours** ensemble.", important=True)
    save_all_data()
    if channel:
        try:
            await channel.send(embed=discord.Embed(
                title=f"🎂  {cap} JOURS AVEC {nom_pet.upper()}",
                description="\n".join(lignes) + f"\n\n*« Avec toi depuis {cap} jours. »*",
                color=0xf1c40f).set_footer(text="📖 Enregistré dans son carnet"))
        except Exception:
            pass
    return True

class PetMenuLegacyView(ui.View):
    """Navigation depuis .pet — les commandes directes restent disponibles"""
    def __init__(self, uid, timeout=180):
        super().__init__(timeout=timeout)
        self.uid = uid
        opts = [
            discord.SelectOption(label="Refuge", emoji="🏠", value="refuge",
                                 description="Visite sa maison"),
            discord.SelectOption(label="Garde-robe", emoji="🎀", value="garderobe",
                                 description="Ses accessoires"),
            discord.SelectOption(label="Compétences", emoji="🧠", value="competences",
                                 description="Ses 10 aptitudes"),
            discord.SelectOption(label="Carnet", emoji="📖", value="carnet",
                                 description="Ses souvenirs"),
            discord.SelectOption(label="Relations", emoji="💕", value="relations",
                                 description="Ses amis et rivaux"),
            discord.SelectOption(label="Collection", emoji="🎒", value="collection",
                                 description="Ses objets et séries"),
            discord.SelectOption(label="Nourrir", emoji="🍖", value="nourrir",
                                 description="Choisir un aliment"),
            discord.SelectOption(label="Ses goûts", emoji="❤️", value="gouts",
                                 description="Ce qu'il aime"),
        ]
        sel = ui.Select(placeholder="🐾 Où veux-tu aller ?", options=opts)
        async def cb(interaction):
            if str(interaction.user.id) != self.uid:
                return await interaction.response.send_message(
                    "❌ Ce n'est pas ton compagnon !", ephemeral=True)
            CMDS = {"refuge": "refuge", "garderobe": "garderobe", "competences": "petcompetences",
                    "carnet": "petcarnet", "relations": "petamis", "collection": "petobjets",
                    "nourrir": "nourrir", "gouts": "petgouts"}
            cmd = bot.get_command(CMDS[sel.values[0]])
            await interaction.response.defer()
            ctx2 = await bot.get_context(interaction.message)
            ctx2.author = interaction.user
            try:
                await cmd.callback(ctx2)
            except TypeError:
                await cmd.callback(ctx2, None)
        sel.callback = cb
        self.add_item(sel)

class PetHubView(ui.View):
    """Hub Pets 2.0 — un seul message, édité à chaque écran."""

    def __init__(self, ctx, uid):
        super().__init__(timeout=300)
        self.ctx, self.uid = ctx, uid
        self.ecran = "accueil"
        self.piece = None
        self.categorie = None
        self.construire()

    async def interaction_check(self, itx):
        if itx.user.id != self.ctx.author.id:
            await itx.response.send_message("🐾 C'est le compagnon de quelqu'un d'autre !",
                                            ephemeral=True)
            return False
        return True

    # ────────────── navigation ──────────────
    async def aller(self, itx, ecran, **kw):
        """Change d'écran. L'interaction est acquittée quoi qu'il arrive :
        aucun bouton ne doit pouvoir afficher « Akari n'a pas répondu à temps »."""
        try:
            self.ecran = ecran
            self.piece = kw.get("piece", self.piece)
            self.categorie = kw.get("categorie", self.categorie)
            self.construire()
            emb = self.embed()
        except Exception as e:
            print(f"[PetHub] écran {ecran} : {type(e).__name__}: {e}")
            emb = discord.Embed(
                description="😿 Cet écran n'a pas pu s'afficher. Refais `.pet`.",
                color=0xe74c3c)
            self.clear_items()
            self.bouton("Accueil", "◀️", "accueil", 0)
        try:
            if not itx.response.is_done():
                await itx.response.edit_message(embed=emb, view=self)
            else:
                await itx.edit_original_response(embed=emb, view=self)
        except (discord.NotFound, discord.HTTPException, discord.InteractionResponded):
            pass

    async def on_timeout(self):
        """Vue expirée : on grise les boutons plutôt que de laisser un clic échouer."""
        for x in self.children:
            x.disabled = True

    async def on_error(self, itx, error, item):
        print(f"[PetHub] {type(error).__name__}: {error}")
        try:
            if not itx.response.is_done():
                await itx.response.send_message(
                    "😿 Petit souci d'affichage — refais `.pet`.", ephemeral=True)
        except Exception:
            pass

    def bouton(self, label, emoji, ecran, row, style=discord.ButtonStyle.secondary, **kw):
        b = ui.Button(label=label, emoji=emoji, style=style, row=row)
        async def cb(itx, _e=ecran, _kw=kw):
            await self.aller(itx, _e, **_kw)
        b.callback = cb
        self.add_item(b)
        return b

    # ────────────── construction des composants ──────────────
    def construire(self):
        self.clear_items()
        e = self.ecran
        if e == "accueil":
            self.bouton("Interagir", "🐾", "interagir", 0, discord.ButtonStyle.success)
            self.bouton("Sortir",    "🗺️", "sortir",    0)
            self.bouton("Refuge",    "🏠", "refuge",    0)
            self.bouton("Famille",   "❤️", "famille",   1)
            self.bouton("Affaires",  "🎒", "affaires",  1)
            self.bouton("Vie",       "📖", "vie",       1)
            return

        if e == "interagir":
            for lab, emo, act, row in (("Nourrir", "🍖", "nourrir", 0),
                                       ("Jouer",   "🎾", "jouer",   0),
                                       ("Laver",   "🛁", "laver",   0),
                                       ("Dormir",  "🛏️", "dormir",  1),
                                       ("Câliner", "🤗", "caresser", 1)):
                b = ui.Button(label=lab, emoji=emo, row=row,
                              style=discord.ButtonStyle.success)
                async def cb(itx, _a=act):
                    await self.faire_action(itx, _a)
                b.callback = cb
                self.add_item(b)

        elif e == "refuge":
            opts = []
            for pid, (emo, nom, desc, meubles, act) in REFUGE_PIECES.items():
                n = len(meubles_piece(self.uid, pid))
                opts.append(discord.SelectOption(
                    label=nom, value=pid, emoji=emo,
                    description=f"{n} meuble(s) installé(s)" if n else "Vide pour l'instant"))
            s = ui.Select(placeholder="Entrer dans une pièce…", options=opts, row=0)
            async def cbs(itx):
                await self.aller(itx, "piece", piece=s.values[0])
            s.callback = cbs
            self.add_item(s)
            _sale = pets_data.get(self.uid, {}).get("saletes", 0)
            bn = ui.Button(label="Nettoyer", emoji="🧹", row=1,
                           style=discord.ButtonStyle.success if _sale >= 15
                           else discord.ButtonStyle.secondary)
            async def cbn(itx):
                await self.nettoyer(itx)
            bn.callback = cbn
            self.add_item(bn)

        elif e == "piece":
            emo, nom, desc, meubles, act = REFUGE_PIECES[self.piece]
            if meubles_piece(self.uid, self.piece):
                b = ui.Button(label={"dormir": "Faire dormir", "cuisiner": "Cuisiner",
                                     "laver": "Donner un bain", "jouer": "Jouer ici",
                                     "explorer": "Explorer", "lire": "Lire ensemble"}[act],
                              emoji=emo, style=discord.ButtonStyle.success, row=0)
                async def cbp(itx, _a=act):
                    await self.faire_piece(itx, _a)
                b.callback = cbp
                self.add_item(b)
            self.bouton("Refuge", "🏠", "refuge", 1)

        elif e == "famille":
            uid = self.uid
            pid, pdb, pst = get_active_pet(uid)
            part = (pst or {}).get("bebe_avec")
            if part and not (pets_data.get(str(part), {}) or {}).get("active"):
                part = None                       # partenaire inaccessible
            bebes = [(k, v) for k, v in (pets_data.get(uid, {}).get("owned") or {}).items()
                     if v.get("est_bebe") or v.get("adulte")]
            if part:
                b = ui.Button(label="Activité duo", emoji="💕",
                              style=discord.ButtonStyle.success, row=0)
                async def cbd(itx):
                    await self.ouvrir_duo(itx)
                b.callback = cbd
                self.add_item(b)
            if bebes:
                b2 = ui.Button(label=f"S'occuper de {bebes[0][1].get('nom_bebe', 'lui')}"[:78],
                               emoji="👶", style=discord.ButtonStyle.success, row=0)
                async def cbb(itx, _p=bebes[0][0]):
                    await self.ouvrir_bebe(itx, _p)
                b2.callback = cbb
                self.add_item(b2)
            if part:
                b3 = ui.Button(label="Album familial", emoji="📖", row=1)
                async def cba(itx):
                    await self.aller(itx, "album")
                b3.callback = cba
                self.add_item(b3)
            adultes = [(k, v) for k, v in bebes if v.get("adulte")]
            if adultes:
                b4 = ui.Button(label="Changer de compagnon", emoji="🔄", row=1)
                async def cbc(itx):
                    await self.aller(itx, "choisir")
                b4.callback = cbc
                self.add_item(b4)

        elif e == "choisir":
            d = pets_data.get(self.uid, {})
            opts = []
            for k, st_ in list((d.get("owned") or {}).items())[:24]:
                if st_.get("est_bebe") and not st_.get("adulte"):
                    continue
                f_ = pet_espece(self.uid, k) or {}
                opts.append(discord.SelectOption(
                    label=(st_.get("surnom") or st_.get("nom_bebe") or f_.get("nom", k))[:90],
                    value=k, emoji=f_.get("emoji", "🐾"),
                    description="Actif" if d.get("active") == k else f"Niveau {st_.get('level', 1)}"))
            if opts:
                s = ui.Select(placeholder="Choisir le compagnon actif…", options=opts, row=0)
                async def cbs(itx):
                    pets_data[self.uid]["active"] = s.values[0]
                    save_all_data()
                    await self.aller(itx, "famille")
                s.callback = cbs
                self.add_item(s)
            self.bouton("Famille", "◀️", "famille", 1)

        elif e == "album":
            self.bouton("Famille", "◀️", "famille", 1)

        elif e == "affaires":
            opts = [discord.SelectOption(label="Nourriture", value="nourriture", emoji="🍖"),
                    discord.SelectOption(label="Jouets",     value="jouets",     emoji="🎾"),
                    discord.SelectOption(label="Accessoires", value="accessoires", emoji="🎀"),
                    discord.SelectOption(label="Souvenirs",  value="souvenirs",  emoji="🎁")]
            s = ui.Select(placeholder="Ouvrir une catégorie…", options=opts, row=0)
            async def cba(itx):
                await self.aller(itx, "categorie", categorie=s.values[0])
            s.callback = cba
            self.add_item(s)

        elif e == "categorie":
            self.bouton("Affaires", "🎒", "affaires", 1)

        elif e == "vie":
            page = getattr(self, "vie_page", "profil")
            b1 = ui.Button(label="Profil", emoji="🧬", row=0,
                           style=discord.ButtonStyle.success if page == "profil"
                           else discord.ButtonStyle.secondary, disabled=page == "profil")
            b2 = ui.Button(label="Parcours", emoji="🏅", row=0,
                           style=discord.ButtonStyle.success if page == "parcours"
                           else discord.ButtonStyle.secondary, disabled=page == "parcours")
            async def cb1(itx):
                self.vie_page = "profil"
                await self.aller(itx, "vie")
            async def cb2(itx):
                self.vie_page = "parcours"
                await self.aller(itx, "vie")
            b1.callback, b2.callback = cb1, cb2
            self.add_item(b1); self.add_item(b2)

        # Retour commun
        if e not in ("accueil", "piece", "categorie", "choisir", "album"):
            self.bouton("Retour", "◀️", "accueil", 2)
        elif e in ("piece", "categorie"):
            self.bouton("Accueil", "◀️", "accueil", 2)

    # ────────────── actions ──────────────
    async def faire_action(self, itx, action):
        """Réutilise les systèmes existants — aucune logique dupliquée."""
        uid = self.uid
        st = pet_etat(uid)
        pid, pdb, pstate = get_active_pet(uid)
        if not st or not pdb:
            return await self.aller(itx, "accueil")
        gains, texte = {}, ""
        if action == "nourrir":
            if st.get("faim", 0) < 15:
                texte = "Il renifle la gamelle et s'éloigne. Il n'a pas faim."
            else:
                st["faim"] = max(0, st["faim"] - 35)
                st["humeur"] = min(100, st["humeur"] + 6)
                gains = {"🍖 Faim": "−35", "😊 Humeur": "+6"}
                texte = _sans_repet(uid, "act_nourrir", [
                    "Il engloutit tout en trois secondes et te regarde, plein d'espoir.",
                    "Il mange proprement, pour une fois.",
                    "Il pousse les morceaux qu'il n'aime pas sur le côté.",
                    "Il mange sans respirer, puis s'assoit, très satisfait."])
                pet_stat(uid, "repas")
        elif action == "jouer":
            if st.get("energie", 0) < 15:
                texte = "Il regarde le jouet, puis se rendort. Une autre fois."
            else:
                st["energie"] = max(0, st["energie"] - 12)
                st["humeur"] = min(100, st["humeur"] + 14)
                gains = {"😊 Humeur": "+14", "⚡ Énergie": "−12"}
                texte = _sans_repet(uid, "act_jouer", [
                    "Il court après la balle, dérape sur le tapis, et fait semblant d'avoir fait exprès.",
                    "Il attrape le jouet et refuse catégoriquement de le rendre.",
                    "Il joue dix secondes puis se couche, épuisé et content.",
                    "Il bondit dans tous les sens sans logique apparente."])
                pet_stat(uid, "jeux")
                give_pet_xp(uid, 6)
        elif action == "laver":
            if st.get("proprete", 0) > 88:
                texte = "Il est déjà impeccable. Il te le fait remarquer."
            else:
                st["proprete"] = 100
                st["humeur"] = max(0, st["humeur"] - 4)
                gains = {"🛁 Propreté": "100", "😊 Humeur": "−4"}
                texte = _sans_repet(uid, "act_laver", [
                    "Il subit le bain avec une dignité offensée.",
                    "Il s'ébroue au pire moment possible. Tu es trempé.",
                    "Il tente une évasion, échoue, et accepte son sort.",
                    "Il ressort propre, vexé, et magnifique."])
                pet_stat(uid, "bains")
        elif action == "dormir":
            st["energie"] = min(100, st["energie"] + 40)
            st["humeur"] = min(100, st["humeur"] + 5)
            gains = {"⚡ Énergie": "+40", "😊 Humeur": "+5"}
            texte = _sans_repet(uid, "act_dormir", [
                "Il s'endort en trois secondes, une patte en l'air.",
                "Il tourne six fois sur lui-même avant de trouver la bonne position.",
                "Il dort profondément. Ses pattes bougent, il court en rêve.",
                "Il s'installe exactement là où tu comptais t'asseoir."])
            pet_stat(uid, "siestes")
        else:                      # caresser
            st["humeur"] = min(100, st["humeur"] + 9)
            gains = {"😊 Humeur": "+9"}
            texte = _sans_repet(uid, "act_caresse", [
                "Il ferme les yeux et se laisse faire.",
                "Il pousse sa tête contre ta main pour en réclamer davantage.",
                "Il ronronne, ou fait un bruit qui y ressemble beaucoup.",
                "Il s'écroule sur le côté pour que tu continues."])
            pet_stat(uid, "calins")
        pstate["vu"] = __import__("time").time()
        save_all_data()
        self.dernier = (action, texte, gains)
        self.ecran = "resultat"
        self.clear_items()
        self.bouton("Encore", "🔁", "interagir", 0, discord.ButtonStyle.success)
        self.bouton("Accueil", "◀️", "accueil", 0)
        try:
            await itx.response.edit_message(embed=self.embed(), view=self)
        except (discord.NotFound, discord.HTTPException, discord.InteractionResponded):
            pass

    async def ouvrir_duo(self, itx):
        """Une friction une fois sur quatre, sinon une activité de duo."""
        uid = self.uid
        pid, pdb, pst = get_active_pet(uid)
        part = (pst or {}).get("bebe_avec")
        if not part:
            return await self.aller(itx, "famille")
        import time as _t
        f = get_foyer(uid, part, creer=True)
        if random.random() < 0.25:
            fr = random.choice(FRICTIONS)
            vue = FrictionView(self.ctx, uid, part, fr)
            try:
                if not itx.response.is_done():
                    await itx.response.edit_message(embed=vue.embed(), view=vue)
            except (discord.NotFound, discord.HTTPException, discord.InteractionResponded):
                pass
            return
        libres = [k for k, a in DUO_ACTIVITES.items()
                  if _t.time() - f.get("cd", {}).get(k, 0) >= a["cd"]]
        if not libres:
            try:
                if not itx.response.is_done():
                    await itx.response.send_message(
                        "⏳ Ils ont déjà tout fait aujourd'hui — reviens plus tard.",
                        ephemeral=True)
            except Exception:
                pass
            return
        vue = DuoView(self.ctx, uid, part, random.choice(libres))
        try:
            if not itx.response.is_done():
                await itx.response.edit_message(embed=vue.embed(), view=vue)
        except (discord.NotFound, discord.HTTPException, discord.InteractionResponded):
            pass

    async def ouvrir_bebe(self, itx, pid_bebe):
        vue = BebeView(self.ctx, self.uid, pid_bebe)
        try:
            if not itx.response.is_done():
                await itx.response.edit_message(embed=vue.embed(), view=vue)
        except (discord.NotFound, discord.HTTPException, discord.InteractionResponded):
            pass

    def ec_album(self):
        uid = self.uid
        pid, pdb, pst = get_active_pet(uid)
        part = (pst or {}).get("bebe_avec")
        f = get_foyer(uid, part) if part else None
        e = discord.Embed(title="📖  Album familial", color=0xff9ec7)
        moments = []
        if f:
            import datetime as _dt
            if f.get("cre"):
                moments.append(("💕", "Le foyer a été fondé", f["cre"]))
            for s in (f.get("souvenirs") or [])[:10]:
                moments.append(("✨", s.get("texte", "")[:90], s.get("t", 0)))
        for k, st_ in ((pets_data.get(uid, {}).get("owned") or {}).items()):
            if st_.get("est_bebe") or st_.get("adulte"):
                for x in (st_.get("carnet") or [])[:6]:
                    if x.get("important"):
                        moments.append(("👶", x.get("texte", "")[:90], x.get("t", 0)))
        moments.sort(key=lambda m: -m[2])
        if moments:
            e.description = "\n".join(f"{m[0]} {m[1]}" for m in moments[:14])
        else:
            e.description = "*L'album est encore vide. Vos moments s'y ajouteront tout seuls.*"
        e.set_footer(text=f"{len(moments)} moment(s)")
        return e

    def ec_choisir(self):
        d = pets_data.get(self.uid, {})
        e = discord.Embed(title="🔄  Choisir un compagnon", color=0xff9ec7)
        lignes = []
        for k, st_ in (d.get("owned") or {}).items():
            if st_.get("est_bebe") and not st_.get("adulte"):
                continue
            f_ = pet_espece(self.uid, k) or {}
            nom = st_.get("surnom") or st_.get("nom_bebe") or f_.get("nom", k)
            marque = "  🌟 *actif*" if d.get("active") == k else ""
            origine = "  ·  *né au foyer*" if st_.get("adulte") else ""
            lignes.append(f"{f_.get('emoji', '🐾')} **{nom}** — niveau {st_.get('level', 1)}{marque}{origine}")
        e.description = "\n".join(lignes) if lignes else "*Aucun compagnon disponible.*"
        e.set_footer(text="Le compagnon actif ne change que si tu le choisis")
        return e

    async def nettoyer(self, itx):
        """Nettoie le refuge — utilise la variable `saletes` existante. Aucune récompense."""
        uid = self.uid
        d = pets_data.setdefault(uid, {})
        sale = d.get("saletes", 0)
        if sale < 15:
            self.msg_refuge = "✨ Le refuge est déjà propre."
        else:
            d["saletes"] = 0
            pid, pdb, pst = get_active_pet(uid)
            nom = (pst or {}).get("surnom") or (pdb or {}).get("nom", "Ton compagnon")
            reactions = [f"{nom} inspecte chaque recoin derrière toi.",
                         f"{nom} te regarde faire depuis le canapé.",
                         f"{nom} s'installe pile à l'endroit que tu viens de nettoyer.",
                         f"{nom} suit le balai des yeux sans bouger la tête."]
            # Variantes selon les traits réellement présents dans PET_TRAITS
            for tr, phrase in (("paresseux", f"{nom} te regarde nettoyer sans proposer son aide. Évidemment."),
                               ("maniaque",  f"{nom} inspecte chaque recoin derrière toi, l'air sévère."),
                               ("joueur",    f"{nom} pense visiblement que le balai est un nouveau jouet."),
                               ("curieux",   f"{nom} veut absolument savoir ce qu'il y avait sous le meuble."),
                               ("energique", f"{nom} court partout et refait la moitié du désordre.")):
                if tr in PET_TRAITS and pet_a_trait(uid, tr):
                    reactions = [phrase] * 3 + reactions
            self.msg_refuge = ("🧹 Tu nettoies le refuge.  ✨ Tout est propre !\n"
                               f"*« {_sans_repet(uid, 'nettoyage', reactions)} »*")
            save_all_data()
        await self.aller(itx, "refuge")

    async def faire_piece(self, itx, act):
        """Activité liée à une pièce — s'appuie sur les besoins existants."""
        equiv = {"dormir": "dormir", "laver": "laver", "jouer": "jouer",
                 "cuisiner": "nourrir", "explorer": "jouer", "lire": "caresser"}
        await self.faire_action(itx, equiv.get(act, "caresser"))

    # ────────────── embeds ──────────────
    def embed(self):
        f = getattr(self, f"ec_{self.ecran}", None)
        return f() if f else self.ec_accueil()

    def ec_accueil(self):
        uid = self.uid
        pid, pdb, pstate = get_active_pet(uid)
        if not pdb:
            return discord.Embed(description="🐾 Tu n'as pas de compagnon actif.",
                                 color=0x95a5a6)
        st = pet_etat(uid) or {}
        pet_init_perso(uid)
        nom = pstate.get("surnom") or pdb["nom"]
        ph_emo, ph_nom, _ = pet_phase(pet_jours(uid))
        e = discord.Embed(
            title=f"{pdb['emoji']}  {nom}",
            description=f"{pdb['nom']} · Niveau **{pstate.get('level', 1)}** · {ph_emo} {ph_nom}",
            color=couleur_humeur(st.get("humeur", 60)))
        # Les besoins passent en avant seulement s'ils sont bas
        besoins = [("🍖", 100 - st.get("faim", 30)), ("⚡", st.get("energie", 80)),
                   ("🛁", st.get("proprete", 80)), ("😊", st.get("humeur", 70))]
        critique = [x for x in besoins if x[1] < 30]
        e.add_field(
            name="⚠️ Il a besoin de toi" if critique else "\u200b",
            value=f"{besoins[0][0]} {jauge5(besoins[0][1])}   {besoins[1][0]} {jauge5(besoins[1][1])}\n"
                  f"{besoins[2][0]} {jauge5(besoins[2][1])}   {besoins[3][0]} {jauge5(besoins[3][1])}",
            inline=False)
        e.add_field(name="\u200b", value=f"*« {ligne_vivante(uid, st, pstate)} »*", inline=False)
        bas = []
        tr = pstate.get("traits") or []
        if tr:
            bas.append("🎭 " + " · ".join(PET_TRAITS[t][1] if t in PET_TRAITS else t for t in tr[:2]))
        nref = len(pets_data.get(uid, {}).get("refuge", []))
        if nref:
            bas.append(f"🏠 {nref} meuble(s)")
        if bas:
            e.set_footer(text="   ·   ".join(bas))
        return e

    def ec_interagir(self):
        uid = self.uid
        st = pet_etat(uid) or {}
        pid, pdb, pstate = get_active_pet(uid)
        nom = pstate.get("surnom") or (pdb or {}).get("nom", "Ton compagnon")
        etats = []
        f = st.get("faim", 30)
        etats.append("🍖 Affamé" if f >= 70 else ("🍖 Un peu faim" if f >= 40 else "🍖 Rassasié"))
        en = st.get("energie", 80)
        etats.append("⚡ Épuisé" if en < 30 else ("⚡ Fatigué" if en < 60 else "⚡ En forme"))
        pr = st.get("proprete", 80)
        etats.append("🛁 Sale" if pr < 40 else "🛁 Propre")
        return discord.Embed(
            title="🐾  Que fait-on ?",
            description=f"*{nom} te regarde, les oreilles dressées.*\n\n" + "   ·   ".join(etats),
            color=HUB_COULEURS["interagir"])

    def ec_resultat(self):
        act, texte, gains = getattr(self, "dernier", ("", "", {}))
        emo = {"nourrir": "🍖", "jouer": "🎾", "laver": "🛁",
               "dormir": "🛏️", "caresser": "🤗"}.get(act, "🐾")
        e = discord.Embed(title=f"{emo}  C'est fait",
                          description=f"*« {texte} »*",
                          color=HUB_COULEURS["interagir"])
        if gains:
            e.add_field(name="\u200b",
                        value="   ·   ".join(f"{k} **{v}**" for k, v in gains.items()),
                        inline=False)
        return e

    def ec_refuge(self):
        uid = self.uid
        d = pets_data.get(uid, {})
        pid, pdb, pstate = get_active_pet(uid)
        nom = ((pstate or {}).get("surnom") or (pdb or {}).get("nom") or "ton compagnon")
        sal = 100 - d.get("saletes", 0)
        e = discord.Embed(title=f"🏠  Refuge de {nom}",
                          description=f"🧹 Propreté du refuge   {jauge5(sal)}   **{sal} %**",
                          color=HUB_COULEURS["refuge"])
        lignes = []
        for pid_, (emo, n, desc, meubles, act) in REFUGE_PIECES.items():
            poss = meubles_piece(uid, pid_)
            lignes.append(f"{emo} **{n}**  ·  {len(poss)}/{len(meubles)} meubles"
                          + ("   ✨" if poss else ""))
        e.add_field(name="\u200b", value="\n".join(lignes), inline=False)
        if getattr(self, "msg_refuge", None):
            e.add_field(name="\u200b", value=self.msg_refuge, inline=False)
            self.msg_refuge = None
        e.set_footer(text="✨ = une activité y est disponible")
        return e

    def ec_piece(self):
        uid = self.uid
        emo, nom, desc, meubles, act = REFUGE_PIECES[self.piece]
        poss = meubles_piece(uid, self.piece)
        e = discord.Embed(title=f"{emo}  {nom}", description=f"*{desc}*",
                          color=HUB_COULEURS["refuge"])
        if poss:
            lignes = []
            for m in poss:
                mm = PET_MEUBLES[m]
                lignes.append(f"{mm[0]} **{mm[1]}**")
            e.add_field(name="Installé ici", value="\n".join(lignes), inline=False)
        else:
            e.add_field(name="\u200b",
                        value="*Cette pièce est encore vide.*\n`.petshop` pour la meubler.",
                        inline=False)
        manquants = [m for m in meubles if m not in poss]
        if manquants:
            e.set_footer(text=f"{len(manquants)} meuble(s) encore disponible(s) à la boutique")
        return e

    def ec_sortir(self):
        e = discord.Embed(title="🗺️  Où allez-vous ?",
                          description="*Ton compagnon tourne déjà autour de la porte.*",
                          color=HUB_COULEURS["sortir"])
        e.add_field(name="\u200b",
                    value=("🧭 **`.petexpedition`** — la grande aventure\n"
                           "🤝 **`.petensemble`** — une activité tous les deux\n"
                           "👋 **`.petvisite @ami`** — rencontrer un autre compagnon"),
                    inline=False)
        e.set_footer(text="Ces sorties gardent leur propre commande — elles sont trop riches pour un bouton")
        return e

    def ec_famille(self):
        uid = self.uid
        pid, pdb, pstate = get_active_pet(uid)
        pstate = pstate or {}
        pdb = pdb or {}
        nom = pstate.get("surnom") or pdb.get("nom", "ton compagnon")
        e = discord.Embed(title=f"❤️  La famille de {nom}", color=HUB_COULEURS["famille"])
        if not pid:
            e.description = "*Tu n'as pas encore de compagnon actif.*"
            return e
        partenaire = pstate.get("bebe_avec")
        owned = (pets_data.get(uid, {}).get("owned") or {})
        bebes = [(k, v) for k, v in owned.items() if v.get("est_bebe") or v.get("adulte")]
        emo_moi = pdb.get("emoji", "🐾")
        if partenaire:
            f = get_foyer(uid, partenaire) or {}
            _, pdb_p, pst_p = get_active_pet(str(partenaire))
            emo_p = (pdb_p or {}).get("emoji", "🐾")
            nom_p = (pst_p or {}).get("surnom") or (pdb_p or {}).get("nom")
            e.description = (f"### {emo_moi}  ·  💕  ·  {emo_p}\n"
                             + (f"*{nom}  et  {nom_p}*" if nom_p
                                else "*Son partenaire est introuvable pour l'instant.*"))
            comp = f.get("complicite", 50)
            emo_pal, nom_pal = foyer_palier(comp)
            e.add_field(name="\u200b",
                        value=(f"💕 Complicité   {jauge5(comp)}   {emo_pal} **{nom_pal}**\n"
                               f"🏠 Foyer niveau **{f.get('niveau', 1)}**   ·   "
                               f"📖 {len(f.get('souvenirs') or [])} souvenir(s)"),
                        inline=False)
        else:
            e.description = f"### {emo_moi}\n*{nom} est seul pour l'instant.*"
            e.add_field(name="\u200b",
                        value="*Fais-lui rencontrer d'autres compagnons avec `.petvisite @ami`.*",
                        inline=False)
        if bebes:
            lignes = []
            for k, st_b in bebes[:4]:
                fiche = pet_espece(uid, k) or {}
                nom_b = st_b.get("nom_bebe", "Petit")
                if st_b.get("adulte"):
                    lignes.append(f"{fiche.get('emoji', '🐾')} **{nom_b}**\n└ 👑 Adulte")
                    continue
                idx, emo_b, ph_b, _ = bebe_phase(st_b)
                cur, req, suiv = bebe_progression(st_b)
                barre = jauge5(int(cur / max(1, req) * 100)) if suiv else "🟩🟩🟩🟩🟩"
                lignes.append(f"{fiche.get('emoji', '🐾')} **{nom_b}**\n"
                              f"└ {emo_b} {ph_b}  ·  🌱 {barre}  {min(cur, req)}/{req}")
            e.add_field(name=f"👶 Ses petits ({len(bebes)})", value="\n".join(lignes), inline=False)
        e.set_footer(text="`.petbebe` · `.petduo` · `.petamis` pour le détail")
        return e

    def ec_affaires(self):
        uid = self.uid
        inv = inventaire.get(uid, {})
        nour = sum(v for k, v in inv.items() if k in PET_NOURRITURE)
        jou = sum(v for k, v in inv.items() if k in PET_JOUETS)
        acc = len(pet_accessoires(uid))
        pid, pdb, pstate = get_active_pet(uid)
        souv = len((pstate or {}).get("objets", []))
        e = discord.Embed(title="🎒  Les affaires de ton compagnon",
                          color=HUB_COULEURS["affaires"])
        e.add_field(name="\u200b",
                    value=(f"🍖 **Nourriture**      {nour} article(s)\n"
                           f"🎾 **Jouets**          {jou} jouet(s)\n"
                           f"🎀 **Accessoires**     {acc} porté(s)\n"
                           f"🎁 **Souvenirs**       {souv} objet(s)"),
                    inline=False)
        return e

    def ec_categorie(self):
        uid = self.uid
        cat = self.categorie
        inv = inventaire.get(uid, {})
        pid, pdb, pstate = get_active_pet(uid)
        titres = {"nourriture": ("🍖", "Nourriture", PET_NOURRITURE),
                  "jouets": ("🎾", "Jouets", PET_JOUETS),
                  "accessoires": ("🎀", "Accessoires", PET_ACCESSOIRES),
                  "souvenirs": ("🎁", "Souvenirs", None)}
        emo, nom, table = titres[cat]
        e = discord.Embed(title=f"{emo}  {nom}", color=HUB_COULEURS["affaires"])
        if cat == "souvenirs":
            objets = (pstate or {}).get("objets", [])
            e.description = ("\n".join(f"🎁 {o}" for o in objets[:15])
                             if objets else "*Aucun souvenir pour l'instant.*")
        else:
            lignes = [f"{table[k][0] if isinstance(table[k], (list, tuple)) else '•'} "
                      f"**{table[k][1] if isinstance(table[k], (list, tuple)) else k}**  ×{v}"
                      for k, v in inv.items() if k in table and v > 0][:15]
            e.description = "\n".join(lignes) if lignes else "*Rien dans cette catégorie.*"
        e.set_footer(text="`.petshop` pour en acheter")
        return e

    def ec_vie(self):
        """Fiche complète du compagnon — page Profil ou page Parcours."""
        uid = self.uid
        pid, pdb, pst = get_active_pet(uid)
        pst, pdb = pst or {}, pdb or {}
        nom = pst.get("surnom") or pst.get("nom_bebe") or pdb.get("nom", "?")
        e = discord.Embed(title=f"📖  Vie de {nom}", color=HUB_COULEURS["vie"])
        if not pid:
            e.description = "*Tu n'as pas de compagnon actif.*"
            return e

        if getattr(self, "vie_page", "profil") == "profil":
            # ── 🧬 Identité ──
            jours = pet_jours(uid)
            ph_emo, ph_nom, _ = pet_phase(jours)
            niv = pst.get("level", 1)
            num, rom, nom_ev, mn, mx, cout = pet_evolution(niv)
            ident = [f"{pdb.get('nom', '?')} · **{pdb.get('rarete', '?')}**",
                     f"{ph_emo} {ph_nom} · Évolution {rom} — *{nom_ev}*",
                     f"⭐ Niveau **{niv}**"]
            if pst.get("adulte"):
                par = pst.get("parents") or {}
                if par:
                    ident.append(f"🧬 Né de {par.get('a', '?')} et {par.get('b', '?')}")
            e.add_field(name="🧬 Identité", value="\n".join(ident), inline=False)

            # ── 🎭 Personnalité ──
            tr = pst.get("traits") or []
            if tr:
                e.add_field(name="🎭 Personnalité",
                            value="\n".join(
                                f"{PET_TRAITS[t][0]} {PET_TRAITS[t][1]}" if t in PET_TRAITS
                                else f"• {t}" for t in tr),
                            inline=True)

            # ── ✨ Particularité (seulement si découverte) ──
            part = pst.get("particularite")
            if part and pst.get("part_decouverte") and part in PET_PARTICULARITES:
                p = PET_PARTICULARITES[part]
                e.add_field(name="✨ Particularité",
                            value=f"{p[0]} **{p[1]}**\n*{p[2]}*", inline=True)
            elif part:
                e.add_field(name="✨ Particularité",
                            value="*Encore inconnue…*", inline=True)

            # ── 🎁 Bonus — via les helpers existants pet_bonus() ──
            try:
                lignes_b = []
                for _t, _emo, _lab in (("coins", "💰", "Pièces"),
                                       ("xp", "⭐", "XP"),
                                       ("roll", "🎰", "Rolls")):
                    _val = pet_bonus(uid, _t)
                    if _val:
                        lignes_b.append(f"{_emo} {_lab} **+{_val} %**")
                if lignes_b:
                    e.add_field(name="🎁 Bonus", value="\n".join(lignes_b), inline=False)
            except Exception as _e:
                print(f"[PetHub] bonus illisibles : {type(_e).__name__}")

            # ── 👗 Équipement ──
            portes = [a for a in (pst.get("portes") or []) if a in PET_ACCESSOIRES]
            if portes:
                e.add_field(name="👗 Équipement",
                            value=" ".join(f"{PET_ACCESSOIRES[a][0]} {PET_ACCESSOIRES[a][1]}"
                                           for a in portes[:4]),
                            inline=False)
            # ── 🏠 Refuge · ❤️ Préférence ──
            bas = [f"🏠 **{len(pets_data.get(uid, {}).get('refuge', []))}** meuble(s)"]
            fav = pst.get("objet_prefere")
            if fav:
                bas.append(f"❤️ Préfère **{fav}**")
            e.add_field(name="\u200b", value="   ·   ".join(bas), inline=False)
            e.set_footer(text="Page 1 sur 2 — Profil")
            return e

        # ── Page Parcours ──
        jours = pet_jours(uid)
        import datetime as _dt
        _ad = pst.get("adoption")
        date = _dt.datetime.fromtimestamp(_ad).strftime("%d/%m/%Y") if _ad else "?"
        e.description = f"📅 Adopté le **{date}** · il y a **{jours}** jour(s)"

        # ── 🏅 Titres ──
        titres = [t for t in (pst.get("titres") or []) if t in PET_TITRES]
        e.add_field(name=f"🏅 Titres  ·  {len(titres)} / {len(PET_TITRES)}",
                    value=("\n".join(f"{PET_TITRES[t][0]} {PET_TITRES[t][1]}"
                                     for t in titres[-4:]) if titres
                           else "*Aucun titre pour l'instant.*"),
                    inline=False)

        # ── 🎯 Compétences ──
        comp = pst.get("stats") or {}
        top = sorted(((k, v) for k, v in comp.items() if isinstance(v, int)),
                     key=lambda x: -x[1])[:5]
        if top:
            e.add_field(name="🎯 Compétences",
                        value="\n".join(f"• {k.capitalize()} — **{v}**" for k, v in top),
                        inline=True)

        # ── 🧬 Habitudes ──
        hab = pst.get("habitudes") or {}
        if hab:
            e.add_field(name="🧬 Habitudes",
                        value="\n".join(f"• {k} — {v}" for k, v in list(hab.items())[:4]),
                        inline=True)

        # ── 📖 Carnet ──
        carnet = pst.get("carnet") or []
        epingles = [x for x in carnet if x.get("important")][:3]
        recents = [x for x in carnet if not x.get("important")][:3]
        if epingles:
            e.add_field(name="📌 Moments marquants",
                        value="\n".join(f"└ {x['texte'][:72]}" for x in epingles), inline=False)
        if recents:
            e.add_field(name="🕐 Récemment",
                        value="\n".join(f"└ {x['texte'][:72]}" for x in recents), inline=False)
        if not carnet:
            e.add_field(name="\u200b", value="*Son carnet est encore vide.*", inline=False)

        # ── 🎁 Souvenirs ──
        obj = pst.get("objets") or []
        if obj:
            e.add_field(name=f"🎁 Souvenirs  ·  {len(obj)}",
                        value=" · ".join(obj[-5:]), inline=False)
        e.set_footer(text=f"Page 2 sur 2 — Parcours  ·  {len(carnet)} entrée(s) au carnet")
        return e

@bot.command(name="pet", aliases=["compagnon"])
async def pet_cmd(ctx, action: str = None, *, pet_name: str = None):
    """Voir/gérer ton compagnon — .pet | .pet liste | .pet equiper <nom> | .pet nourrir"""
    uid = str(ctx.author.id)
    if action is None:
        # ── PETS 2.0 : le hub à boutons ──
        pid, pdb, pstate = get_active_pet(uid)
        if not pid:
            return await ctx.send("🐾 Tu n'as pas de compagnon actif !\nRends-toi dans `.shop` → page **Compagnons** pour en acheter un.")
        vue = PetHubView(ctx, uid)
        return await ctx.send(embed=vue.embed(), view=vue)

    if action == "classique":
        # Ancien affichage détaillé, conservé — .pet classique
        pid, pdb, pstate = get_active_pet(uid)
        if not pid:
            return await ctx.send("🐾 Tu n'as pas de compagnon actif !")
        st = pet_etat(uid)
        pet_init_perso(uid)
        jours = pet_jours(uid)
        ph_emo, ph_nom, ph_desc = pet_phase(jours)
        part = pet_particularite(uid)
        nom_perso = pstate.get("surnom") or pdb["nom"]
        peut_evo = pet_peut_evoluer(uid)
        SEP = "━━━━━━━━━━━━━━━━━━"

        # ── 1. IDENTITÉ ──
        titre_actuel = ""
        if pstate.get("titres"):
            _t0 = pstate["titres"][-1]
            if _t0 in PET_TITRES:
                titre_actuel = f"« {PET_TITRES[_t0][1]} »"

        entete = [f"**{pdb['rarete']}**  ·  {ph_emo} **{ph_nom}**", f"*{ph_desc}*", SEP]

        # ── 2. ÉVOLUTION ──
        num, rom, nom_ev, mn, mx, _ = pet_evolution(pstate["level"])
        if peut_evo:
            _s = pet_evolution_suivante(pstate["level"])
            _assez = economy_data[uid]["coins"] >= _s[5]
            entete += [
                f"✨ **Évolution {rom}** — *{nom_ev}*",
                f"⭐ Niveau **{pstate['level']}**",
                f"`{'▰' * 12}` **MAX**",
                "",
                "### 🌟 PRÊT À ÉVOLUER",
                f"➡️ **Évolution {_s[1]} — {_s[2]}** *(niv. {_s[3]}–{_s[4]})*",
                f"💰 **{_s[5]:,} pièces**" + ("  ·  **`.petevoluer`**" if _assez
                                             else f"  ·  *il te manque {_s[5] - economy_data[uid]['coins']:,} p*"),
            ]
        else:
            requis = pet_xp_requis(pstate["level"])
            _f = max(0, min(12, int(pstate.get("xp", 0) / max(1, requis) * 12)))
            entete += [
                f"✨ **Évolution {rom}** — *{nom_ev}*",
                f"⭐ Niveau **{pstate['level']}** *(palier {mn}–{mx})*",
                f"`{'▰' * _f}{'▱' * (12 - _f)}` **{pstate.get('xp', 0):,} / {requis:,} XP**",
            ]

        embed = discord.Embed(
            title=pet_nom_decore(uid, pdb) + (f"\n{titre_actuel}" if titre_actuel else ""),
            description="\n".join(entete),
            color=0xf1c40f if peut_evo else 0xe91e63)

        # ── 2 bis. EN CE MOMENT ──
        _sc = scene_actuelle(uid)
        if _sc:
            embed.add_field(name="🏡 En ce moment", value=_sc[0], inline=False)

        # ── 3. ÉTAT GÉNÉRAL ──
        embed.add_field(name="😊 État général", value=(
            f"❤️ Humeur      `{_jauge(st['humeur'], '▰', '▱', 10)}` {int(st['humeur'])}%\n"
            f"🍖 Faim        `{_jauge(100 - st['faim'], '▰', '▱', 10)}` {int(100 - st['faim'])}%\n"
            f"⚡ Énergie     `{_jauge(st['energie'], '▰', '▱', 10)}` {int(st['energie'])}%\n"
            f"🧼 Propreté    `{_jauge(st['proprete'], '▰', '▱', 10)}` {int(st['proprete'])}%\n\n"
            f"### {pet_humeur_texte(st)}"), inline=False)

        # ── 4. UNE SEULE PRIORITÉ ──
        PRIORITES = [
            (st["faim"] > 65,     "🍖", "Il a faim",        ".nourrir"),
            (st["energie"] < 35,  "😴", "Il est épuisé",    ".dormir"),
            (st["humeur"] < 40,   "🧸", "Il s'ennuie",      ".jouer"),
            (st["proprete"] < 35, "🛁", "Il est sale",      ".laver"),
            (st["faim"] > 45,     "🍖", "Il commence à avoir faim", ".nourrir"),
            (st["humeur"] < 60,   "🫶", "Il réclame de l'attention", ".caresser"),
        ]
        urgence = next((p for p in PRIORITES if p[0]), None)
        if urgence:
            _, emo_u, txt_u, cmd_u = urgence
            embed.add_field(name="⚠️ Il a besoin de toi",
                            value=f"{emo_u} **{txt_u}**\n➡️ `{cmd_u}`", inline=False)

        # ── 5. PERSONNALITÉ ──
        traits = pstate.get("traits", [])
        if traits:
            val_t = "\n".join(f"{PET_TRAITS[t][0]} **{PET_TRAITS[t][1]}**"
                              for t in traits if t in PET_TRAITS)
            _cb = combos_actifs(uid)
            if _cb:
                val_t += "\n\n" + "\n".join(f"{cf[0]} *{cf[1]}*" for _, cf in _cb[:2])
            embed.add_field(name="🧠 Personnalité", value=val_t, inline=True)

        # ── 6. PARTICULARITÉ ──
        if part:
            _k, _emo, _nom, _eff, _desc = part
            embed.add_field(name="✨ Particularité",
                            value=f"{_emo} **{_nom}**\n*{_desc}*", inline=True)
        elif pstate.get("particularite"):
            embed.add_field(name="❓ Particularité",
                            value="*Quelque chose semble spécial chez lui…*\n"
                                  "*Continue à t'en occuper pour le découvrir.*", inline=True)

        # ── 7. BONUS REGROUPÉS ──
        lignes_b = []
        for _typ, (_e, _q) in {"coins": ("💰", "pièces"), "xp": ("⭐", "XP"),
                               "roll": ("🎰", "rolls gratuits"),
                               "humeur": ("❤️", "humeur conservée")}.items():
            _base = pdb["base"] + (pstate["level"] - 1) if pdb["type"] == _typ else 0
            _acc = bonus_accessoires(uid, _typ)
            if _base + _acc > 0:
                lignes_b.append(f"{_e} **+{_base + _acc} % {_q}**")
        _portes = pet_accessoires(uid)
        if _portes:
            lignes_b.append("\n👗 " + " · ".join(
                f"{PET_ACCESSOIRES[a][0]} {PET_ACCESSOIRES[a][1]}"
                for a in _portes if a in PET_ACCESSOIRES))
        _ref = len(pets_data.get(uid, {}).get("refuge", []))
        if _ref:
            lignes_b.append(f"🏡 Refuge aménagé — **{_ref}** meuble(s)")
        embed.add_field(name="✨ Bonus", value="\n".join(lignes_b) or "*Aucun bonus actif.*",
                        inline=False)

        # ── 8. PRÉFÉRENCES ──
        _objets = pstate.get("objets", [])
        if pstate.get("objet_prefere") or _objets:
            _o = pstate.get("objet_prefere")
            _eo = PET_OBJETS_TROUVES.get(_o, ("🎁",))[0] if _o else ""
            val_p = (f"❤️ {_eo} **{_o}**\n" if _o else "")
            val_p += f"🎒 Collection : **{len(_objets)} / {len(PET_OBJETS_TROUVES)}** objets\n*`.petobjets`*"
            embed.add_field(name="🧸 Préférences", value=val_p, inline=True)

        # ── 9. TITRES ──
        _titres = pstate.get("titres", [])
        val_t = (f"{PET_TITRES[_titres[-1]][0]} **{PET_TITRES[_titres[-1]][1]}**\n"
                 if _titres and _titres[-1] in PET_TITRES else "*Aucun pour l'instant.*\n")
        val_t += f"**{len(_titres)} / {len(PET_TITRES)}** débloqués"
        embed.add_field(name="🏅 Titres", value=val_t, inline=True)

        # ── 10. HABITUDES ──
        hab = pstate.get("habitudes", {})
        if hab:
            embed.add_field(name="🧬 Habitudes",
                            value="  ·  ".join(f"{PET_HABITUDES[h][0]} {PET_HABITUDES[h][1]}"
                                              for h in hab if h in PET_HABITUDES), inline=False)

        # ── 11. INFOS ──
        import datetime as _dt
        _adopt = pstate.get("adoption")
        _date = _dt.datetime.fromtimestamp(_adopt).strftime("%d/%m/%Y") if _adopt else "?"
        embed.set_footer(text=f"Adopté le {_date} · il y a {jours} jour(s) · "
                              f"`.petcompetences` `.petcarnet` `.garderobe` `.refuge`")

        await ctx.send(embed=embed, view=PetMenuLegacyView(uid))
        await verifier_bilan(uid, ctx.channel)
        for e_h, n_h in verifier_habitudes(uid):
            await ctx.send(embed=discord.Embed(
                description=f"🧬 **Nouvelle habitude**\n{e_h} **{nom_perso}** {n_h.lower()}.",
                color=0xe91e63))
        for e_t, n_t in verifier_titres_pet(uid):
            await ctx.send(embed=discord.Embed(
                title="🏅 Nouveau titre !",
                description=f"# {e_t}\n**{nom_perso}** devient **« {n_t} »**", color=0xf1c40f))
        await verifier_traits_histoire(uid, ctx.channel)
        save_all_data()
        if await tenter_moment_unique(ctx, uid):
            return
        if await tenter_combo(ctx, uid):
            return
        if await tenter_histoire(ctx, uid):
            return
        if await tenter_betise(ctx, uid):
            return
        if await tenter_scene(ctx, uid):
            return
        await tenter_event_vie(ctx, uid)
        return
    action = action.lower()
    if action in ("liste", "list", "collection"):
        d = pets_data.get(uid)
        if not d or not d.get("owned"):
            return await ctx.send("🐾 Tu n'as aucun compagnon !\nRends-toi dans `.shop` → page **Compagnons** pour en acheter un.")
        lignes = []
        for pid, st in d["owned"].items():
            p = pet_espece(uid, pid)
            if p:
                actif = "  🌟 *actif*" if d.get("active") == pid else ""
                val = p["base"] + st["level"] - 1
                icone = {"coins": "💰", "xp": "⭐", "roll": "🎰"}[p["type"]]
                deco = ("".join(PET_ACCESSOIRES[a][0] for a in st.get("portes", [])
                                if a in PET_ACCESSOIRES)) if d.get("active") == pid else ""
                _rom = pet_evolution(st.get("level", 1))[1]
                lignes.append(f"{p['emoji']} **{p['nom']}**{(' ' + deco) if deco else ''} — "
                              f"✨{_rom} · Niv.{st['level']} · {icone} +{val} %{actif}")
        return await ctx.send(embed=discord.Embed(
            title=f"🐾 Compagnons de {ctx.author.display_name}",
            description="\n".join(lignes), color=0xe91e63))
    if action in ("equiper", "équiper", "equip"):
        if not pet_name:
            return await ctx.send("❌ `.pet equiper <nom>`")
        d = pets_data.get(uid, {})
        match = next((pid for pid in d.get("owned", {}) if pet_name.lower() in PETS_DB.get(pid, {}).get("nom", "").lower()), None)
        if not match:
            return await ctx.send("❌ Tu ne possèdes pas ce compagnon !")
        pets_data[uid]["active"] = match
        p = PETS_DB[match]
        return await ctx.send(embed=discord.Embed(
            description=f"🌟 **{p['emoji']} {p['nom']}** est maintenant ton compagnon actif !", color=0x2ecc71))
    if action in ("feed",):
        pid, pdb, pstate = get_active_pet(uid)
        if not pid:
            return await ctx.send("🐾 Aucun compagnon actif à nourrir !")
        PRIX_REPAS = 200
        if economy_data[uid]["coins"] < PRIX_REPAS:
            return await ctx.send(f"❌ Il te faut **{PRIX_REPAS} pièces** pour un repas !")
        if pstate["level"] >= PET_LEVEL_MAX:
            return await ctx.send(f"🌟 **{pdb['nom']}** est déjà au niveau max !")
        economy_data[uid]["coins"] -= PRIX_REPAS
        leveled, lvl = give_pet_xp(uid, 25)
        msg = f"🍖 **{pdb['emoji']} {pdb['nom']}** a bien mangé ! **+25 XP**"
        if leveled:
            msg += f"\n🆙 **NIVEAU {lvl} !** Son bonus augmente !"
        return await ctx.send(embed=discord.Embed(description=msg, color=0x2ecc71))
    await ctx.send("❌ Actions : `.pet` • `.pet liste` • `.pet equiper <nom>` • `.pet nourrir`")

# ============================================================
#  AUTOROLE — Persistance
# ============================================================
AUTOROLE_FILE = data_path("autorole_config.json")
def save_autorole():
    """Sauvegarde les panels autorole dans un fichier JSON"""
    try:
        with open(AUTOROLE_FILE, "w", encoding="utf-8") as f:
            json.dump(autorole_panels, f, ensure_ascii=False)
    except Exception as e:
        print(f"[Autorole] Erreur sauvegarde : {e}")

def load_autorole():
    """Charge les panels autorole au démarrage"""
    if not os.path.exists(AUTOROLE_FILE):
        return
    try:
        with open(AUTOROLE_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        autorole_panels.update(data)
        print(f"[Autorole] ✅ {len(data)} serveur(s) chargé(s)")
    except Exception as e:
        print(f"[Autorole] Erreur chargement : {e}")

