@bot.command(name="gachabattle", aliases=["gb", "pokebattle", "pb"])
async def gachabattle_cmd(ctx, adversaire: discord.Member = None):
    """🎴 Gacha Battle — combat 3v3 avec tes cartes ! — .gachabattle @joueur"""
    if SALON_GACHABATTLE_ID and ctx.channel.id != SALON_GACHABATTLE_ID:
        salon = ctx.guild.get_channel(SALON_GACHABATTLE_ID)
        mention = salon.mention if salon else "le salon gachabattle"
        return await ctx.send(f"🎴 Les Gacha Battles c'est dans {mention} !", delete_after=5)
    if not adversaire or adversaire.bot or adversaire.id == ctx.author.id:
        return await ctx.send("❌ Mentionne un adversaire valide ! Ex : `.gachabattle @ami`")
    if ctx.channel.id in active_gachabattles:
        return await ctx.send("⚔️ Un combat est déjà en cours ici !")

    uid1 = str(ctx.author.id)
    uid2 = str(adversaire.id)
    col1 = gacha_collections[uid1]
    col2 = gacha_collections[uid2]
    if len(col1) < 3:
        return await ctx.send(f"❌ **{ctx.author.display_name}** n'a pas assez de cartes ! (minimum 3)")
    if len(col2) < 3:
        return await ctx.send(f"❌ **{adversaire.display_name}** n'a pas assez de cartes ! (minimum 3)")

    async def choisir_equipe(joueur):
        uid = str(joueur.id)
        col = gacha_collections[uid]
        order = collection_order.get(uid, [])
        all_keys = [k for k in order if k in col] + [k for k in col if k not in order]
        valid_keys = [k for k in all_keys if k in ANIME_CARDS_DB]
        if len(valid_keys) < 3:
            return None
        chosen  = []
        page    = [0]
        PAGE_SZ = 5
        done_ev = asyncio.Event()

        def build_view():
            v = ui.View(timeout=90)
            start = page[0] * PAGE_SZ
            keys_page = valid_keys[start:start + PAGE_SZ]
            total_pages = (len(valid_keys) - 1) // PAGE_SZ + 1
            for i2, key in enumerate(keys_page):
                c   = ANIME_CARDS_DB[key]
                lv  = fusion_levels[uid].get(key, 0)
                stars = "⭐" * lv if lv else ""
                already = key in [x["key"] for x in chosen]
                btn = ui.Button(
                    label=f"{c['nom'][:15]}{stars}",
                    emoji=c.get("emoji", "⚔️"),
                    style=discord.ButtonStyle.success if already else discord.ButtonStyle.secondary,
                    disabled=already,
                    row=i2 // 3
                )
                async def cb(interaction, k=key, card=c):
                    if interaction.user.id != joueur.id:
                        return await interaction.response.send_message("❌ Pas ton tour !", ephemeral=True)
                    _pv, _atk, _def, _mult = carte_stats_finales(uid, k, card)
                    new_card = card.copy()
                    new_card["key"] = k
                    new_card["mult"]     = _mult      # sert aux dégâts des attaques
                    new_card["pv"]       = _pv
                    new_card["attaque"]  = _atk
                    new_card["defense"]  = _def
                    # ── Gameplay tactique ──
                    new_card["role"]     = role_carte(k)
                    _atqs = sorted(card.get("attaques", []),
                                   key=lambda a: a.get("degats", 30))
                    new_card["atq_base"] = _atqs[0] if _atqs else {"nom": "Attaque", "emoji": "⚔️", "degats": 30}
                    new_card["atq_tech"] = _atqs[-1] if _atqs else {"nom": "Technique", "emoji": "🔥", "degats": 45}
                    new_card["cd_tech"]  = 0
                    new_card["cd_cap"]   = 0
                    new_card["ef_reduc"] = 0   # tours restants de réduction de dégâts
                    new_card["ef_esq"]   = 0   # esquive armée
                    new_card["ef_boost"] = 0   # rage
                    new_card["ef_perce"] = 0   # faille
                    new_card["ef_entrave"] = 0 # entrave subie
                    new_card["hp_actuel"] = new_card["pv"]
                    new_card["ko"] = False
                    chosen.append(new_card)
                    noms_choisis = " • ".join(f"{c2['emoji']} **{c2['nom']}**" for c2 in chosen)
                    if len(chosen) >= 3:
                        done_ev.set()
                        await interaction.response.edit_message(
                            content=f"✅ **{joueur.display_name}** — Équipe prête !\n{noms_choisis}",
                            view=None
                        )
                    else:
                        await interaction.response.edit_message(
                            content=f"⚔️ **{joueur.display_name}** — Choisis tes 3 cartes ({len(chosen)}/3) :\n✅ {noms_choisis}",
                            view=build_view()
                        )
                btn.callback = cb
                v.add_item(btn)
            if total_pages > 1:
                prev_btn = ui.Button(label="◀", style=discord.ButtonStyle.primary, disabled=page[0] == 0, row=2)
                info_btn = ui.Button(label=f"Page {page[0]+1}/{total_pages}", style=discord.ButtonStyle.secondary, disabled=True, row=2)
                next_btn = ui.Button(label="▶", style=discord.ButtonStyle.primary, disabled=page[0] >= total_pages - 1, row=2)
                async def prev_cb(interaction):
                    if interaction.user.id != joueur.id:
                        return await interaction.response.send_message("❌", ephemeral=True)
                    page[0] = max(0, page[0] - 1)
                    await interaction.response.edit_message(view=build_view())
                async def next_cb(interaction):
                    if interaction.user.id != joueur.id:
                        return await interaction.response.send_message("❌", ephemeral=True)
                    page[0] = min(total_pages - 1, page[0] + 1)
                    await interaction.response.edit_message(view=build_view())
                prev_btn.callback = prev_cb
                next_btn.callback = next_cb
                v.add_item(prev_btn); v.add_item(info_btn); v.add_item(next_btn)
            return v

        await ctx.send(
            content=f"⚔️ **{joueur.display_name}** — Choisis tes **3 cartes** (0/3) :",
            view=build_view()
        )
        try:
            await asyncio.wait_for(done_ev.wait(), timeout=90)
        except asyncio.TimeoutError:
            return None
        return chosen if len(chosen) >= 3 else None

    await ctx.send(embed=discord.Embed(
        title="🎴 GACHA BATTLE",
        description=(
            f"⚡ **{ctx.author.mention}** défie **{adversaire.mention}** en **3 contre 3** !\n\n"
            "**3 cartes chacun. Le dernier debout gagne.**\n"
            "Le chiffre entre parenthèses sur chaque bouton = les dégâts estimés.\n\n"
            "🏆 **300 pièces + 60 XP** au vainqueur\n\n"
            "*Chacun choisit son équipe…*"),
        color=0x9b59b6))
    equipe1 = await choisir_equipe(ctx.author)
    if not equipe1:
        return await ctx.send(f"❌ **{ctx.author.display_name}** n'a pas choisi son équipe !")
    equipe2 = await choisir_equipe(adversaire)
    if not equipe2:
        return await ctx.send(f"❌ **{adversaire.display_name}** n'a pas choisi son équipe !")

    ajouter_lien(str(ctx.author.id), str(adversaire.id), "duel")
    active_gachabattles[ctx.channel.id] = {
        "j1": {"membre": ctx.author,  "equipe": equipe1, "actif": 0},
        "j2": {"membre": adversaire,  "equipe": equipe2, "actif": 0},
        "tour": ctx.author.id,
        "tour_num": 1,
        "journal": [],
    }

    def carte_active(j): return j["equipe"][j["actif"]]

    def barre_pb(val, maxi, longueur=10):
        rempli = int((val / max(maxi, 1)) * longueur)
        return "█" * rempli + "░" * (longueur - rempli)

    def equipe_str(j):
        return " | ".join(
            f"{'💀' if c['ko'] else c['emoji']} {c['nom']} `{c['hp_actuel']}HP`"
            for c in j["equipe"]
        )

    def build_embed_pb():
        game = active_gachabattles.get(ctx.channel.id, {})
        j1_g, j2_g = game.get("j1"), game.get("j2")
        if not j1_g or not j2_g:
            return discord.Embed(title="Combat terminé")
        c1, c2 = carte_active(j1_g), carte_active(j2_g)

        def barre(cc):
            p = cc["hp_actuel"] / max(cc["pv"], 1)
            n = max(0, min(8, round(p * 8)))
            couleur = "🟥" if p < 0.3 else ("🟨" if p < 0.6 else "🟩")
            return couleur * n + "⬛" * (8 - n)

        def equipe(j):
            return " ".join("💀" if x["ko"] else ("🔷" if i == j["actif"] else "🔹")
                            for i, x in enumerate(j["equipe"]))

        def etat(cc):
            """Rôle, effets actifs et cooldowns, en une ligne."""
            bouts = [f"{ROLE_EMOJI.get(cc.get('role',''),'')} {cc.get('role','')}"]
            if cc.get("ef_boost", 0) > 0:   bouts.append("🔥 Rage")
            if cc.get("ef_perce", 0) > 0:   bouts.append("💢 Faille")
            if cc.get("ef_reduc", 0) > 0:   bouts.append("🛡️ Protégé")
            if cc.get("ef_esq", 0) > 0:     bouts.append("🌫️ Esquive")
            if cc.get("ef_entrave", 0) > 0: bouts.append("✨ Entravé")
            cds = []
            if cc.get("cd_tech", 0) > 0: cds.append(f"🔥⏳{cc['cd_tech']}")
            if cc.get("cd_cap", 0) > 0:  cds.append(f"🎭⏳{cc['cd_cap']}")
            if cds: bouts.append(" ".join(cds))
            return "  ·  ".join(bouts)

        tour_de = game.get("tour")
        actif = j1_g if tour_de == j1_g["membre"].id else j2_g

        embed = discord.Embed(
            title="🎴  GACHA BATTLE",
            description=(
                f"### {c1['emoji']} {c1['nom']}\n"
                f"{barre(c1)}  **{c1['hp_actuel']}**/{c1['pv']}\n"
                f"-# {etat(c1)}\n"
                f"{equipe(j1_g)}  ·  *{j1_g['membre'].display_name}*\n\n"
                f"⚔️ **VS** ⚔️\n\n"
                f"### {c2['emoji']} {c2['nom']}\n"
                f"{barre(c2)}  **{c2['hp_actuel']}**/{c2['pv']}\n"
                f"-# {etat(c2)}\n"
                f"{equipe(j2_g)}  ·  *{j2_g['membre'].display_name}*"),
            color=0x9b59b6)

        journal = game.get("journal", [])
        if journal:
            embed.add_field(name="\u200b", value="\n".join(journal[-2:]), inline=False)
        embed.set_footer(text=f"🎯 Au tour de {actif['membre'].display_name}")
        return embed


    combat_msg = await ctx.send(embed=build_embed_pb())

    while ctx.channel.id in active_gachabattles:
        game = active_gachabattles[ctx.channel.id]
        j1_g = game["j1"]; j2_g = game["j2"]

        if all(c["ko"] for c in j1_g["equipe"]):
            del active_gachabattles[ctx.channel.id]
            economy_data[str(j2_g["membre"].id)]["coins"] += 300
            xp_data[str(j2_g["membre"].id)]["xp"] += 60
            lvlups_win = card_xp_team(str(j2_g["membre"].id), j2_g["equipe"], won=True)
            track_stat(str(j2_g["membre"].id), "pb_wins", channel=ctx.channel)
            try: missions_progress[str(j2_g["membre"].id)]["wins"] += 1
            except Exception: pass
            card_xp_team(str(j1_g["membre"].id), j1_g["equipe"], won=False)
            await combat_msg.edit(embed=build_embed_pb(), view=None, content=None)
            desc_fin = f"🎉 **{j2_g['membre'].mention}** remporte le combat 3v3 !\n💰 **+300 pièces** • ⭐ **+60 XP**"
            if lvlups_win:
                desc_fin += "\n\n📈 **Cartes qui montent de niveau :**\n" + "\n".join([f"⬆️ **{nom}** → Niv. {lvl}" for nom, lvl in lvlups_win])
            await ctx.send(embed=discord.Embed(title="🏆 FIN DU COMBAT !", description=desc_fin, color=0xf1c40f))
            return
        if all(c["ko"] for c in j2_g["equipe"]):
            del active_gachabattles[ctx.channel.id]
            economy_data[str(j1_g["membre"].id)]["coins"] += 300
            xp_data[str(j1_g["membre"].id)]["xp"] += 60
            lvlups_win = card_xp_team(str(j1_g["membre"].id), j1_g["equipe"], won=True)
            track_stat(str(j1_g["membre"].id), "pb_wins", channel=ctx.channel)
            try: missions_progress[str(j1_g["membre"].id)]["wins"] += 1
            except Exception: pass
            card_xp_team(str(j2_g["membre"].id), j2_g["equipe"], won=False)
            await combat_msg.edit(embed=build_embed_pb(), view=None, content=None)
            desc_fin = f"🎉 **{j1_g['membre'].mention}** remporte le combat 3v3 !\n💰 **+300 pièces** • ⭐ **+60 XP**"
            if lvlups_win:
                desc_fin += "\n\n📈 **Cartes qui montent de niveau :**\n" + "\n".join([f"⬆️ **{nom}** → Niv. {lvl}" for nom, lvl in lvlups_win])
            await ctx.send(embed=discord.Embed(title="🏆 FIN DU COMBAT !", description=desc_fin, color=0xf1c40f))
            return

        current = j1_g if game["tour"] == j1_g["membre"].id else j2_g
        other   = j2_g if game["tour"] == j1_g["membre"].id else j1_g
        while carte_active(current)["ko"]:
            current["actif"] = (current["actif"] + 1) % 3

        chosen_action = asyncio.Event()
        action_result = {"choix": None}
        carte_cur_pre = carte_active(current)
        carte_adv_pre = carte_active(other)
        # ── Décompte des cooldowns et effets : au début du tour de leur porteur ──
        for _k in ("cd_tech", "cd_cap", "ef_reduc", "ef_esq",
                   "ef_boost", "ef_perce", "ef_entrave"):
            carte_cur_pre[_k] = max(0, carte_cur_pre.get(_k, 0) - 1)

        _cap_cur = ROLE_CAPACITE.get(carte_cur_pre.get("role", "Équilibré"), {})
        def _estim(base_deg, cap_frappe=1.0):
            """Estimation affichée sur le bouton — même formule que le combat."""
            d = round(base_deg * cap_frappe * carte_cur_pre.get("mult", 1.0))
            _b = d * 0.40 + carte_cur_pre["attaque"] * 0.30
            return max(6, int(_b * (130 / (130 + carte_adv_pre["defense"]))))

        class CombatButtons(ui.View):
            def __init__(self):
                super().__init__(timeout=45)
                _verrou = {"pris": False}

                def _garde(fn):
                    async def inner(interaction, _fn=fn):
                        if interaction.user.id != current["membre"].id:
                            return await interaction.response.send_message(
                                "❌ Ce n'est pas ton tour !", ephemeral=True)
                        if _verrou["pris"]:      # anti double-clic
                            return await interaction.response.defer()
                        _verrou["pris"] = True
                        await _fn(interaction)
                    return inner

                # ⚔️ Attaque — toujours disponible
                _ab = carte_cur_pre.get("atq_base") or {"nom": "Attaque", "emoji": "⚔️", "degats": 30}
                b1 = ui.Button(label=f"{_ab['nom'][:18]}  ({_estim(_ab.get('degats', 30))})",
                               emoji=_ab.get("emoji", "⚔️"),
                               style=discord.ButtonStyle.primary, row=0)
                async def _cb1(interaction):
                    action_result["choix"] = "base"
                    chosen_action.set(); self.stop(); await interaction.response.defer()
                b1.callback = _garde(_cb1); self.add_item(b1)

                # 🔥 Technique — cooldown 2
                _at = carte_cur_pre.get("atq_tech") or {"nom": "Technique", "emoji": "🔥", "degats": 45}
                _cdt = carte_cur_pre.get("cd_tech", 0)
                b2 = ui.Button(
                    label=(f"{_at['nom'][:18]}  ⏳{_cdt}" if _cdt > 0
                           else f"{_at['nom'][:18]}  ({_estim(_at.get('degats', 45))})"),
                    emoji=_at.get("emoji", "🔥"),
                    style=discord.ButtonStyle.danger, disabled=_cdt > 0, row=0)
                async def _cb2(interaction):
                    action_result["choix"] = "tech"
                    chosen_action.set(); self.stop(); await interaction.response.defer()
                b2.callback = _garde(_cb2); self.add_item(b2)

                # 🎭 Capacité de rôle — cooldown 3
                _cdc = carte_cur_pre.get("cd_cap", 0)
                b3 = ui.Button(
                    label=(f"{_cap_cur.get('nom', 'Capacité')}  ⏳{_cdc}" if _cdc > 0
                           else f"{_cap_cur.get('nom', 'Capacité')}  "
                                f"({_estim((carte_cur_pre.get('atq_base') or {}).get('degats', 30), CAPACITE_FRAPPE)})"),
                    emoji=_cap_cur.get("emoji", "🎭"),
                    style=discord.ButtonStyle.success, disabled=_cdc > 0, row=1)
                async def _cb3(interaction):
                    action_result["choix"] = "cap"
                    chosen_action.set(); self.stop(); await interaction.response.defer()
                b3.callback = _garde(_cb3); self.add_item(b3)
                dispo_swap = [x for i3, x in enumerate(current["equipe"]) if not x["ko"] and i3 != current["actif"]]
                swap = ui.Button(
                    label=(f"Changer → {dispo_swap[0]['nom'][:16]}" if dispo_swap else "Aucun remplaçant"),
                    emoji="🔄", style=discord.ButtonStyle.secondary,
                    disabled=not dispo_swap, row=2)
                async def cb_swap(interaction):
                    action_result["choix"] = "swap"
                    chosen_action.set(); self.stop(); await interaction.response.defer()
                swap.callback = _garde(cb_swap)
                self.add_item(swap)

            async def on_timeout(self):
                action_result["choix"] = "base"
                chosen_action.set()

        view = CombatButtons()
        await combat_msg.edit(
            content=f"🎮 {current['membre'].mention} — **C'est ton tour !**",
            embed=build_embed_pb(), view=view
        )
        try:
            await asyncio.wait_for(chosen_action.wait(), timeout=46)
        except asyncio.TimeoutError:
            action_result["choix"] = "base"

        choix = action_result["choix"]
        carte_cur = carte_active(current)
        carte_adv = carte_active(other)

        if choix == "swap":
            dispo = [(i3, c) for i3, c in enumerate(current["equipe"]) if not c["ko"] and i3 != current["actif"]]
            if dispo:
                current["actif"] = dispo[0][0]
                game.setdefault("journal", []).append(
                    f"🔄 {dispo[0][1]['emoji']} **{dispo[0][1]['nom']}** entre en jeu")
            game["tour"] = other["membre"].id
            game["tour_num"] += 1
            await combat_msg.edit(content=None, embed=build_embed_pb(), view=None)
            continue

        # ── Action choisie : "base", "tech" ou "cap" ──
        action = choix if isinstance(choix, str) else "base"
        cap = ROLE_CAPACITE.get(carte_cur.get("role", "Équilibré"), {})
        esquive = False
        soin = 0

        if action == "tech":
            atq = carte_cur.get("atq_tech") or {"nom": "Technique", "emoji": "🔥", "degats": 45}
            base = atq.get("degats", 45)
            carte_cur["cd_tech"] = TECHNIQUE_CD + 1
        elif action == "cap":
            atq = {"nom": cap.get("nom", "Capacité"), "emoji": cap.get("emoji", "🎭"), "degats": 0}
            base = (carte_cur.get("atq_base") or {}).get("degats", 30) * CAPACITE_FRAPPE
            carte_cur["cd_cap"] = cap.get("cd", 3) + 1
            d = cap.get("duree", 1)
            if "reduc" in cap:   carte_cur["ef_reduc"] = d + 1
            if "esquive" in cap: carte_cur["ef_esq"]   = d + 1
            if "boost" in cap:   carte_cur["ef_boost"] = d + 1
            if "perce" in cap:   carte_cur["ef_perce"] = d + 1
            if "entrave" in cap: carte_adv["ef_entrave"] = d + 1
            if "soin" in cap:
                soin = round(carte_cur["pv"] * cap["soin"])
                carte_cur["hp_actuel"] = min(carte_cur["pv"], carte_cur["hp_actuel"] + soin)
        else:
            atq = carte_cur.get("atq_base") or {"nom": "Attaque", "emoji": "⚔️", "degats": 30}
            base = atq.get("degats", 30)

        if base == 0: base = random.randint(20, 35)
        base = round(base * carte_cur.get("mult", 1.0))

        # L'adversaire peut esquiver
        cap_adv = ROLE_CAPACITE.get(carte_adv.get("role", "Équilibré"), {})
        if carte_adv.get("ef_esq", 0) > 0 and random.random() < cap_adv.get("esquive", 0):
            carte_adv["ef_esq"] = 0
            esquive = True
            degats = 0
            critique = False
        else:
            critique = random.random() < 0.12
            if critique: base = int(base * 1.5)
            _boost = cap.get("boost", 0) if carte_cur.get("ef_boost", 0) > 0 else 0.0
            _entrave = cap_adv.get("entrave", 0) if carte_cur.get("ef_entrave", 0) > 0 else 0.0
            brut = (base * 0.40 + carte_cur["attaque"] * (1 + _boost) * 0.30) * (1 - _entrave)
            _perce = cap.get("perce", 0) if carte_cur.get("ef_perce", 0) > 0 else 0.0
            _def_adv = carte_adv["defense"] * (1 - _perce)
            _reduc = cap_adv.get("reduc", 0) if carte_adv.get("ef_reduc", 0) > 0 else 0.0
            degats = max(6, int(brut
                                * (130 / (130 + _def_adv))
                                * random.uniform(0.85, 1.15)
                                * (1 - _reduc)))
        carte_adv["hp_actuel"] = max(0, carte_adv["hp_actuel"] - degats)
        _j = game.setdefault("journal", [])
        if esquive:
            _j.append(f"🌫️ **{carte_adv['nom']}** esquive *{atq['nom']}* !")
        else:
            _txt = f"{atq.get('emoji','⚔️')} *{atq['nom']}* → **−{degats}**"
            if critique: _txt += " ✦ CRITIQUE"
            _j.append(_txt)
        if action == "cap":
            _eff = {"Tank": "−20 % dégâts subis", "Assassin": "esquive armée",
                    "Bruiser": "+50 % dégâts (3 tours)", "Perceur": "−75 % DEF adverse (3 tours)",
                    "Équilibré": f"−24 % dégâts · +{soin} PV",
                    "Support": "−16 % dégâts adverses (3 tours)"}.get(carte_cur.get("role", ""), "")
            if _eff: _j.append(f"{cap.get('emoji','🎭')} **{cap.get('nom','')}** — {_eff}")

        if carte_adv["hp_actuel"] <= 0:
            carte_adv["ko"] = True
            game.setdefault("journal", []).append(f"💀 **{carte_adv['nom']}** est K.O.")
            next_idx = next((i4 for i4, c in enumerate(other["equipe"]) if not c["ko"]), None)
            if next_idx is not None:
                other["actif"] = next_idx

        game["tour"] = other["membre"].id
        game["tour_num"] += 1
        await combat_msg.edit(content=None, embed=build_embed_pb(), view=None)

@bot.command(name="gachastop", aliases=["pokestop", "stopcombat"])
async def gachastop_cmd(ctx):
    """Annule le Gacha Battle en cours — .gachastop"""
    if ctx.channel.id in active_gachabattles:
        del active_gachabattles[ctx.channel.id]
        await ctx.send("🛑 Combat annulé !")
    else:
        await ctx.send("❌ Aucun combat en cours !")

