# Items utilisables seul (sans cible) depuis l'inventaire
ITEMS_SOLO = {
    "cafe", "sablier", "cadeau", "boost_rarete", "rolls_5", "oracle", "double_rien",
    "shield", "amulette", "protection", "antidote", "cadenasp",
    "potionxp", "double_xp", "trefle", "aimant", "oeil", "cristal",
    "boost_daily", "megaphone", "fanfare", "loupe", "reroll_pet", "tirelire",
}
# Items qui exigent une cible
ITEMS_CIBLE = {"freeze", "curse", "cadenas", "bombe_gacha", "fantome", "malediction", "vol_roll"}

def _info_item(iid):
    it = next((i for i in SHOP_ITEMS if i["id"] == iid), None)
    if it:
        return it["nom"], it.get("description", "")
    return iid, ""

async def utiliser_item_solo(ctx, uid, iid):
    """Applique l'effet d'un consommable de l'inventaire. Retourne True si consommé."""
    import time as _t
    nom, _ = _info_item(iid)

    if iid == "cafe":
        roll_data[uid]["rolls"] = min(roll_data[uid]["rolls"] + 3, ROLLS_MAX + 5)
        await ctx.send(embed=discord.Embed(
            description=f"☕ Un café bien serré — **+3 rolls** ! *({roll_data[uid]['rolls']} disponibles)*",
            color=0x2ecc71))
    elif iid == "sablier":
        claim_cooldown.pop(uid, None)
        await ctx.send(embed=discord.Embed(
            description="🕰️ Le sable s'inverse — ton **claim est de nouveau disponible** !", color=0x2ecc71))
    elif iid == "rolls_5":
        roll_data[uid]["rolls"] = min(roll_data[uid]["rolls"] + 5, ROLLS_MAX + 10)
        await ctx.send(embed=discord.Embed(
            description=f"🎰 **+5 rolls** ! *({roll_data[uid]['rolls']} disponibles)*", color=0x2ecc71))
    elif iid == "cadeau":
        CHANCES = [("Rare", 78), ("Épique", 19), ("Légendaire", 2.8), ("Mythique", 0.2)]
        libres = {r: [k for k, cc in ANIME_CARDS_DB.items()
                      if k not in RETIRED_CARD_MAP
                      if cc["rarete"] == r and k not in claimed_cards] for r, _ in CHANCES}
        possibles = [(r, p) for r, p in CHANCES if libres[r]]
        if not possibles:
            await ctx.send("❌ Aucune carte disponible pour le moment — ton cadeau est conservé.")
            return False
        rarete = random.choices([r for r, _ in possibles], weights=[p for _, p in possibles])[0]
        key = random.choice(libres[rarete])
        donner_carte(uid, key, ctx.channel)
        gazette_note(uid, "cartes")
        check_collection_achievements(uid, ctx.channel)
        cc = ANIME_CARDS_DB[key]
        if cc["rarete"] in ("Légendaire", "Mythique"):
            gazette_fait("carte", f"**{ctx.author.display_name}** a ouvert un cadeau et trouvé "
                                  f"{RARETE_EMOJI.get(cc['rarete'],'')} **{cc['nom']}** !",
                         10 if cc["rarete"] == "Mythique" else 5)
        e = discord.Embed(
            title="🎁 Cadeau Mystère ouvert !",
            description=(f"{RARETE_EMOJI.get(cc['rarete'],'')} **{cc['nom']}**\n"
                         f"*{cc['serie']}*  ·  **{cc['rarete']}**\n\n"
                         f"Elle rejoint ta collection !"),
            color=RARETE_COULEURS.get(cc["rarete"], 0x2ecc71))
        if cc.get("image"):
            e.set_image(url=cc["image"])
        await ctx.send(embed=e)
    elif iid == "boost_rarete":
        rarity_boost[uid] = 5
        await ctx.send(embed=discord.Embed(
            description="🎯 **Boost Rareté actif** — chances Épique+ fortement augmentées "
                        "sur tes **5 prochains rolls** !", color=0x2ecc71))
    elif iid == "oracle":
        oracle_actif[uid] = 3
        await ctx.send(embed=discord.Embed(
            description="🔮 **Oracle actif** — tes 3 prochains rolls ont 1 chance sur 5 "
                        "de faire tomber une carte bonus.", color=0x2ecc71))
    elif iid == "double_rien":
        if random.random() < 0.5:
            ajout = min(4, ROLLS_MAX + 5 - roll_data[uid]["rolls"])
            roll_data[uid]["rolls"] += max(0, ajout)
            await ctx.send(embed=discord.Embed(
                title="🎰 Double !", description=f"**+{max(0,ajout)} rolls** ! *({roll_data[uid]['rolls']} au total)*",
                color=0x2ecc71))
        else:
            perdus = roll_data[uid]["rolls"]
            roll_data[uid]["rolls"] = 0
            await ctx.send(embed=discord.Embed(
                title="💥 Rien…", description=f"Tu perds tes **{perdus} rolls**. Ça arrive.",
                color=0xe74c3c))
    elif iid == "aimant":
        aimant_actif[uid] = True
        await ctx.send(embed=discord.Embed(
            description="🧲 Ton **prochain roll** est garanti **Rare ou mieux** !", color=0x2ecc71))
    elif iid == "oeil":
        oeil_destin[uid] = 3
        await ctx.send(embed=discord.Embed(
            description="🧿 Tes **3 prochains rolls** te seront révélés à l'avance.", color=0x2ecc71))
    elif iid == "shield":
        shield_active[uid] = _t.time() + 1800
        await ctx.send(embed=discord.Embed(
            description="🛡️ **Bouclier actif 30 min** — protégé du Sceau et des Malédictions.",
            color=0x2ecc71))
    elif iid == "amulette":
        amulette_active[uid] = _t.time() + 1200
        await ctx.send(embed=discord.Embed(
            description="🪬 **Amulette active 20 min** — tout sabotage sera renvoyé à l'attaquant.",
            color=0x2ecc71))
    elif iid == "protection":
        shield_active[uid] = _t.time() + 7200
        amulette_active[uid] = _t.time() + 7200
        await ctx.send(embed=discord.Embed(
            description="🌟 **Protection Divine** — immunité totale pendant **2 heures**.",
            color=0xf1c40f))
    elif iid == "cadenasp":
        cadenas_perso[uid] = _t.time() + 86400
        await ctx.send(embed=discord.Embed(
            description="🔗 Tu es **immunisé contre le braquage** pendant **24 heures**.", color=0x2ecc71))
    elif iid == "antidote":
        n = 0
        for d in (claim_curse, claim_freeze, malediction_active, ghost_cards):
            if uid in d:
                d.pop(uid, None); n += 1
        await ctx.send(embed=discord.Embed(
            description=(f"💊 Antidote bu — **{n} malédiction(s)** annulée(s)." if n
                         else "💊 Tu n'étais sous aucune malédiction… mais ça fait du bien."),
            color=0x2ecc71))
    elif iid == "potionxp":
        xp_data[uid]["xp"] += 500
        monte = 0
        while xp_data[uid]["xp"] >= xp_data[uid]["level"] * 100:
            xp_data[uid]["xp"] -= xp_data[uid]["level"] * 100
            xp_data[uid]["level"] += 1
            points_amelio[uid] += 1
            monte += 1
        await ctx.send(embed=discord.Embed(
            description="🧪 **+500 XP** !" + (f"\n🆙 **Niveau {xp_data[uid]['level']}** atteint !" if monte else ""),
            color=0x2ecc71))
    elif iid == "double_xp":
        double_xp_actif[uid] = _t.time() + 3600
        await ctx.send(embed=discord.Embed(
            description="⚡ **Double XP actif pendant 1 heure** !", color=0x2ecc71))
    elif iid == "trefle":
        trefle_actif[uid] = _t.time() + 3600
        await ctx.send(embed=discord.Embed(
            description="🍀 Tes gains d'**events sont doublés** pendant **1 heure** !", color=0x2ecc71))
    elif iid == "boost_daily":
        double_daily[uid] = True
        await ctx.send(embed=discord.Embed(
            description="📅 Ton **prochain `.daily`** rapportera le **double** !", color=0x2ecc71))
    elif iid == "megaphone":
        megaphone_actif[uid] = True
        await ctx.send(embed=discord.Embed(
            description="📣 Ton **prochain message** sera annoncé en grand !", color=0x2ecc71))
    elif iid == "fanfare":
        fanfare_actif[uid] = True
        await ctx.send(embed=discord.Embed(
            description="🎺 Ton **prochain passage de niveau** sera annoncé en grand !", color=0x2ecc71))
    elif iid == "reroll_pet":
        pid, pdb, pstate = get_active_pet(uid)
        if not pid:
            await ctx.send("❌ Tu n'as aucun compagnon actif !")
            return False
        leveled, lvl = give_pet_xp(uid, 300)
        await ctx.send(embed=discord.Embed(
            description=(f"🍬 **{pet_nom_decore(uid, pdb)}** dévore la friandise — **+300 XP** !"
                         + (f"\n🆙 Niveau **{lvl}** !" if leveled else "")), color=0x2ecc71))
    elif iid == "loupe":
        dispo = [k for k, cc in ANIME_CARDS_DB.items()
                 if k not in RETIRED_CARD_MAP
                 if cc["rarete"] in ("Épique", "Légendaire", "Mythique") and k not in claimed_cards]
        if not dispo:
            await ctx.send("❌ Aucune carte rare disponible — ta loupe est conservée.")
            return False
        tirage = random.sample(dispo, min(3, len(dispo)))
        await ctx.send(embed=discord.Embed(
            title="🔍 La loupe révèle…",
            description="\n".join(
                f"{RARETE_EMOJI.get(ANIME_CARDS_DB[k]['rarete'],'')} **{ANIME_CARDS_DB[k]['nom']}** "
                f"— *{ANIME_CARDS_DB[k]['serie']}*" for k in tirage)
                + "\n\n*Ces cartes n'appartiennent à personne.*", color=0x9b59b6))
    elif iid == "cristal":
        mes = set(gacha_collections.get(uid, {}))
        conv = []
        for autre, wl in gacha_wishlist.items():
            if autre == uid: continue
            for k in wl & mes:
                m = ctx.guild.get_member(int(autre)) if ctx.guild else None
                conv.append(f"**{ANIME_CARDS_DB[k]['nom']}** — *{m.display_name if m else 'un membre'}*")
        await ctx.send(embed=discord.Embed(
            title="🔮 La boule s'éclaircit…",
            description="\n".join(conv[:15]) or "*Personne ne convoite tes cartes… pour l'instant.*",
            color=0x9b59b6))
    elif iid == "tirelire":
        gain = random.choices([0, 1500, 3000, 4500, 5500, 8000, 12000, 25000],
                              weights=[8, 16, 22, 20, 14, 12, 6, 2])[0]
        economy_data[uid]["coins"] += gain
        gazette_gain(uid, gain)
        check_coins_achievements(uid, ctx.channel)
        await ctx.send(embed=discord.Embed(
            title="🐷 Tu casses la tirelire…",
            description=(f"Elle contenait **{gain:,} pièces** !" if gain
                         else "💀 Elle était **vide**."), color=0x2ecc71 if gain else 0xe74c3c))
    else:
        return False
    return True


@bot.command(name="souvenirs", aliases=["collectionobjets", "mesobjets"])
async def souvenirs_cmd(ctx, membre: discord.Member = None):
    """Tes objets de collection — .souvenirs"""
    cible = membre or ctx.author
    uid = str(cible.id)
    objets = {k: v for k, v in inventaire.get(uid, {}).items()
              if v > 0 and k not in ITEMS_SOLO and k not in ITEMS_CIBLE}
    embed = discord.Embed(
        title=f"🖼️ Souvenirs de {cible.display_name}",
        color=0x9b59b6)
    embed.set_thumbnail(url=cible.display_avatar.url)
    if not objets:
        embed.description = ("*Aucun souvenir pour l'instant.*\n\n"
                             "On en récupère lors des events, des expéditions "
                             "et des ouvertures de coffres.")
    else:
        total = sum(objets.values())
        embed.description = f"**{len(objets)}** objet(s) différent(s)  ·  **{total}** au total"
        lignes = []
        for iid, n in sorted(objets.items(), key=lambda x: (-x[1], x[0])):
            nom, desc = _info_item(iid)
            lignes.append(f"**{nom}** ×{n}" + (f"\n└ *{desc[:70]}*" if desc else ""))
        for i in range(0, min(len(lignes), 24), 8):
            embed.add_field(name="\u200b" if i else "Collection",
                            value="\n".join(lignes[i:i+8]), inline=False)
        if len(lignes) > 24:
            embed.set_footer(text=f"…et {len(lignes)-24} autre(s)")
    await ctx.send(embed=embed)

@bot.command(name="inventaire", aliases=["sac", "objets", "moninventaire"])
async def inventaire_cmd(ctx, membre: discord.Member = None):
    """Ton sac — .inventaire"""
    import time as _t
    cible = membre or ctx.author
    uid = str(cible.id)
    objets = {k: v for k, v in inventaire.get(uid, {}).items() if v > 0}

    embed = discord.Embed(
        title=f"🎒 Sac de {cible.display_name}",
        color=0xf1c40f)
    embed.set_thumbnail(url=cible.display_avatar.url)

    if objets:
        solo, cible_l, autres = [], [], []
        for iid, n in sorted(objets.items(), key=lambda x: -x[1]):
            nom, desc = _info_item(iid)
            ligne = f"**{nom}** ×{n}\n└ `{iid}` — *{desc[:90]}*"
            if iid in ITEMS_SOLO:
                solo.append(ligne)
            elif iid in ITEMS_CIBLE:
                cible_l.append(ligne)
            else:
                autres.append(ligne)
        if solo:
            embed.add_field(name="✨ À utiliser quand tu veux",
                            value="\n".join(solo[:8]) + "\n\n*`.utiliser <id>`*", inline=False)
        if cible_l:
            embed.add_field(name="⚔️ À lancer sur quelqu'un",
                            value="\n".join(cible_l[:8]) + "\n\n*`.utiliser <id> @joueur`*", inline=False)
        if autres:
            embed.add_field(
                name="🖼️ Souvenirs",
                value=f"Tu possèdes **{sum(1 for i in objets if i not in ITEMS_SOLO and i not in ITEMS_CIBLE)}** "
                      f"objet(s) de collection.\n*Ils sont dans `.souvenirs`.*",
                inline=False)
    else:
        embed.description = ("*Ton sac est vide.*\n\n"
                             "Tu remplis ton inventaire en achetant dans `.shop`, "
                             "en envoyant ton compagnon en `.petexpedition`, "
                             "ou en ouvrant le calendrier de l'Avent.")

    # Effets actifs
    actifs = []
    now = _t.time()
    if roll_data.get(uid, {}).get("rolls"):
        actifs.append(f"🎰 **{roll_data[uid]['rolls']}** rolls disponibles")
    if rarity_boost.get(uid):
        actifs.append(f"🎯 Boost Rareté — {rarity_boost[uid]} roll(s)")
    if oracle_actif.get(uid):
        actifs.append(f"🔮 Oracle — {oracle_actif[uid]} roll(s)")
    if oeil_destin.get(uid):
        actifs.append(f"🧿 Œil du Destin — {oeil_destin[uid]} roll(s)")
    if aimant_actif.get(uid):
        actifs.append("🧲 Aimant armé")
    if double_daily.get(uid):
        actifs.append("📅 Prochain daily doublé")
    for cle, emo, lab in [(shield_active, "🛡️", "Bouclier"), (amulette_active, "🪬", "Amulette"),
                          (cadenas_perso, "🔗", "Cadenas Personnel"), (trefle_actif, "🍀", "Trèfle")]:
        fin = cle.get(uid, 0)
        if fin > now:
            m = int((fin - now) / 60)
            actifs.append(f"{emo} {lab} — {m} min" if m < 120 else f"{emo} {lab} — {m//60} h")
    if actifs:
        embed.add_field(name="⏳ Effets actifs", value="\n".join(actifs), inline=False)

    embed.set_footer(text=f"{sum(objets.values())} objet(s) · `.shop` pour en acheter")
    await ctx.send(embed=embed)

@bot.command(name="utiliser")
async def utiliser_cmd(ctx, item_type: str = None, cible: discord.Member = None):
    """Utilise un objet de ton sac — .utiliser <item> [@joueur]"""
    import time as _time
    uid = str(ctx.author.id)

    if not item_type:
        objets = {k: v for k, v in inventaire.get(uid, {}).items() if v > 0}
        if not objets:
            return await ctx.send(embed=discord.Embed(
                description=("🎒 Ton sac est vide.\n\n"
                             "Achète dans `.shop`, envoie ton compagnon en `.petexpedition`, "
                             "ou ouvre le calendrier de l'Avent."), color=0x95a5a6))
        lignes = []
        for iid, n in sorted(objets.items(), key=lambda x: -x[1]):
            nom, _ = _info_item(iid)
            besoin = " *(sur quelqu'un)*" if iid in ITEMS_CIBLE else ""
            lignes.append(f"`{iid}` — **{nom}** ×{n}{besoin}")
        return await ctx.send(embed=discord.Embed(
            title="🎒 Que veux-tu utiliser ?",
            description="\n".join(lignes) + "\n\n*`.utiliser <id>` · `.inventaire` pour le détail*",
            color=0xf1c40f))

    itype = item_type.lower().strip()
    # Recherche souple par nom
    if itype not in inventaire.get(uid, {}):
        trouve = next((k for k in inventaire.get(uid, {})
                       if inventaire[uid][k] > 0 and normalize_str(itype) in normalize_str(_info_item(k)[0])), None)
        if trouve:
            itype = trouve

    if inventaire[uid].get(itype, 0) <= 0:
        nom, _ = _info_item(itype)
        return await ctx.send(f"❌ Tu n'as pas **{nom}** dans ton sac ! Tape `.inventaire` pour voir ce que tu as.")

    # ── Objets utilisables seul ──
    if itype in ITEMS_SOLO:
        ok = await utiliser_item_solo(ctx, uid, itype)
        if ok:
            inventaire[uid][itype] -= 1
            if inventaire[uid][itype] <= 0:
                inventaire[uid].pop(itype, None)
            save_all_data()
        return

    if itype in ITEMS_CIBLE and not cible:
        nom, _ = _info_item(itype)
        return await ctx.send(f"❌ **{nom}** doit être lancé sur quelqu'un : `.utiliser {itype} @joueur`")
    if not cible:
        return await ctx.send(f"❌ Usage : `.utiliser {itype} @joueur`")

    uid_cible = str(cible.id)
    now_ts = _time.time()

    # Vérif amulette sur la cible
    if amulette_active.get(uid_cible, 0) > now_ts:
        inventaire[uid][itype] -= 1
        return await ctx.send(embed=discord.Embed(
            title="🪬 Amulette activée !",
            description=f"**{cible.display_name}** est protégé par une **Amulette** ! Le sabotage se retourne contre **{ctx.author.mention}** ! 😈",
            color=0x9b59b6
        ))

    # Vérif protection divine
    if shield_active.get(uid_cible, 0) > now_ts:
        inventaire[uid][itype] -= 1
        restant = int((shield_active[uid_cible] - now_ts) // 60)
        return await ctx.send(f"🌟 **{cible.display_name}** est sous **Protection Divine** ! ({restant} min restantes)")

    # Vérif bouclier basique
    if itype in ("freeze","curse") and uid_cible in shield_active and shield_active[uid_cible] > now_ts:
        return await ctx.send(f"🛡️ **{cible.display_name}** est protégé par un bouclier !")

    # Consommer l'item
    inventaire[uid][itype] -= 1

    # ── FREEZE ───────────────────────────────────────────────
    if itype == "freeze":
        claim_freeze[uid_cible] = now_ts + 10
        await ctx.send(embed=discord.Embed(title="🧊 Sceau des Ombres !",
            description=f"**{cible.mention}** ne peut plus claim pendant **10 secondes** ! 😈", color=0x3498db))

    # ── CURSE ────────────────────────────────────────────────
    elif itype == "curse":
        claim_curse[uid_cible] = now_ts + 300
        await ctx.send(embed=discord.Embed(title="⏳ Malédiction !",
            description=f"**{cible.mention}** a +5 min sur son claim cooldown ! 😈", color=0x9b59b6))

    # ── CADENAS ──────────────────────────────────────────────
    elif itype == "cadenas":
        claim_freeze[uid_cible] = now_ts + 1800  # 30 min
        await ctx.send(embed=discord.Embed(title="🔒 Cadenas !",
            description=f"**{cible.mention}** ne peut plus claim pendant **30 minutes** ! 🔒", color=0xe74c3c))

    # ── BOMBE GACHA ──────────────────────────────────────────
    elif itype == "bombe_gacha":
        # Trouver la dernière carte claimée par la cible
        cible_cards = [k for k,v in claimed_cards.items() if v == uid_cible]
        if not cible_cards:
            return await ctx.send(f"❌ **{cible.display_name}** n'a aucune carte claimée !")
        # Prendre la dernière
        lost_key = cible_cards[-1]
        lost_card = ANIME_CARDS_DB[lost_key]
        del claimed_cards[lost_key]
        if uid_cible in gacha_collections and lost_key in gacha_collections[uid_cible]:
            del gacha_collections[uid_cible][lost_key]
        r_emoji = RARETE_EMOJI.get(lost_card["rarete"], "🔵")
        await ctx.send(embed=discord.Embed(title="💣 Bombe Gacha !",
            description=f"**{cible.mention}** perd sa carte **{lost_card['nom']}** {r_emoji} ! 💥\n*Envoyée dans le néant...*",
            color=0xe74c3c))
        # Notifier la victime en MP
        try:
            await cible.send(embed=discord.Embed(
                description=f"💣 **{ctx.author.display_name}** t'a posé une Bombe Gacha ! Tu as perdu **{lost_card['nom']}** {r_emoji} !",
                color=0xe74c3c))
        except: pass

    # ── FANTÔME ───────────────────────────────────────────────
    elif itype == "fantome":
        cible_cards = [k for k,v in claimed_cards.items() if v == uid_cible]
        if not cible_cards:
            return await ctx.send(f"❌ **{cible.display_name}** n'a aucune carte !")
        ghost_key = random.choice(cible_cards)
        ghost_card = ANIME_CARDS_DB[ghost_key]
        ghost_cards[f"{uid_cible}_{ghost_key}"] = now_ts + 1800  # 30 min
        await ctx.send(embed=discord.Embed(title="👻 Fantôme !",
            description=f"Une carte de **{cible.mention}** devient invisible pendant **30 min** ! 👻",
            color=0x9b59b6))

    # ── MALÉDICTION RARE ──────────────────────────────────────
    elif itype == "malediction":
        # Vérif 1x par joueur par jour
        if not hasattr(bot, 'malediction_targets'):
            bot.malediction_targets = {}
        today = int(now_ts // 86400)
        key_mal = f"{uid}_{uid_cible}_{today}"
        if key_mal in bot.malediction_targets:
            return await ctx.send(f"❌ Tu as déjà maudit **{cible.display_name}** aujourd'hui !")
        bot.malediction_targets[key_mal] = True
        malediction_active[uid_cible] = now_ts + 3600  # 1h
        await ctx.send(embed=discord.Embed(title="🎭 Malédiction Rare !",
            description=f"**{cible.mention}** ne tirera que des cartes **Communes** lors de son prochain roll ! 😈",
            color=0x9b59b6))

    # ── VOL DE ROLL ───────────────────────────────────────────
    elif itype == "vol_roll":
        if not hasattr(bot, 'vol_roll_counts'):
            bot.vol_roll_counts = {}
        count_key = f"{uid}_{uid_cible}"
        current = bot.vol_roll_counts.get(count_key, 0)
        if current >= 3:
            return await ctx.send(f"❌ Tu as déjà volé **3 rolls** à **{cible.display_name}** ! (limite atteinte)")
        if roll_data[uid_cible]["rolls"] <= 0:
            return await ctx.send(f"❌ **{cible.display_name}** n'a plus de rolls à voler !")
        roll_data[uid_cible]["rolls"] = max(0, roll_data[uid_cible]["rolls"] - 1)
        roll_data[uid]["rolls"] = min(roll_data[uid]["rolls"] + 1, ROLLS_MAX + 5)
        bot.vol_roll_counts[count_key] = current + 1
        await ctx.send(embed=discord.Embed(title="🎯 Vol de Roll !",
            description=f"**{ctx.author.mention}** vole 1 roll à **{cible.mention}** ! ({current+1}/3 vols sur ce joueur)",
            color=0xf39c12))

    else:
        await ctx.send(f"❌ Item `{itype}` inconnu !")

# ============================================================
#  GESTION GLOBALE DES ERREURS — anti-crash
# ============================================================

def _watch_type(titre):
    """Devine si un titre est un animé ou un kdrama"""
    if chercher_oeuvre(titre, ANIMES)[0]:
        return "anime"
    if chercher_oeuvre(titre, KDRAMAS)[0]:
        return "kdrama"
    return "autre"

@bot.command(name="watch", aliases=["watchlist", "wl"])
async def watch_cmd(ctx, action: str = None, *, title: str = None):
    """Ta watchlist — .watch ajouter/liste/vu/supprimer <titre>"""
    uid = str(ctx.author.id)
    if not action:
        return await ctx.send(embed=discord.Embed(
            title="📋 Ta Watchlist",
            description=("`.watch ajouter <titre>` — ajouter à ta liste\n"
                         "`.watch liste [@membre]` — voir une watchlist\n"
                         "`.watch vu <titre>` — marquer comme **vu** ✅\n"
                         "`.watch revoir <titre>` — remettre à voir\n"
                         "`.watch supprimer <titre>` — retirer complètement"),
            color=0xff6b9d))
    action = action.lower()

    # ── AJOUTER ──
    if action in ("ajouter", "add", "+"):
        if not title:
            return await ctx.send("❌ Précise un titre ! Ex : `.watch ajouter Goblin`")
        for item in watchlist_data[uid]:
            if normalize_str(item["title"]) == normalize_str(title):
                return await ctx.send(f"❌ **{item['title']}** est déjà dans ta watchlist !")
        # Titre officiel si on le connaît
        officiel, kind = title, _watch_type(title)
        if kind == "anime":
            officiel = chercher_oeuvre(title, ANIMES)[0]["title"]
        elif kind == "kdrama":
            officiel = chercher_oeuvre(title, KDRAMAS)[0]["title"]
        watchlist_data[uid].append({"title": officiel, "status": "À voir", "type": kind})
        icone = {"anime": "📺", "kdrama": "🎭"}.get(kind, "📌")
        return await ctx.send(embed=discord.Embed(
            description=f"✅ {icone} **{officiel}** ajouté à ta watchlist !",
            color=0x2ecc71))

    # ── LISTE ──
    if action in ("liste", "list", "voir"):
        cible = ctx.message.mentions[0] if ctx.message.mentions else ctx.author
        cid = str(cible.id)
        items = watchlist_data[cid]
        if not items:
            return await ctx.send(
                f"📋 {'Ta watchlist est vide' if cible == ctx.author else f'{cible.display_name} n a rien dans sa watchlist'} ! "
                f"`.watch ajouter <titre>` pour commencer.")
        embed = discord.Embed(
            title=f"📋 Watchlist de {cible.display_name}",
            color=0xff6b9d)
        embed.set_thumbnail(url=cible.display_avatar.url)
        for kind, titre_sec in (("anime", "📺 Animés"), ("kdrama", "🎭 K-Dramas"), ("autre", "📌 Autres")):
            lot = [i for i in items if i.get("type", "autre") == kind]
            if not lot:
                continue
            a_voir = [i["title"] for i in lot if i["status"] != "Vu"]
            vus    = [i["title"] for i in lot if i["status"] == "Vu"]
            txt = ""
            if a_voir:
                txt += "**À voir**\n" + "\n".join(f"• {t}" for t in a_voir[:12])
                if len(a_voir) > 12:
                    txt += f"\n*…et {len(a_voir)-12} autre(s)*"
            if vus:
                txt += ("\n\n" if txt else "") + "**Vus ✅**\n" + "\n".join(f"• ~~{t}~~" for t in vus[:12])
                if len(vus) > 12:
                    txt += f"\n*…et {len(vus)-12} autre(s)*"
            embed.add_field(name=f"{titre_sec}  ({len(lot)})", value=txt[:1024] or "—", inline=False)
        total, nb_vus = len(items), sum(1 for i in items if i["status"] == "Vu")
        embed.set_footer(text=f"{total} titre(s) • {nb_vus} vu(s) • {total - nb_vus} à voir")
        return await ctx.send(embed=embed)

    # ── VU / REVOIR / SUPPRIMER ──
    if action in ("vu", "termine", "terminé", "fini", "revoir", "supprimer", "retirer", "remove", "-"):
        if not title:
            return await ctx.send(f"❌ Précise un titre ! Ex : `.watch {action} Goblin`")
        for item in watchlist_data[uid]:
            if normalize_str(title) in normalize_str(item["title"]) or \
               normalize_str(item["title"]) in normalize_str(title):
                if action in ("vu", "termine", "terminé", "fini"):
                    if item["status"] == "Vu":
                        return await ctx.send(f"✅ **{item['title']}** est déjà marqué comme vu !")
                    item["status"] = "Vu"
                    return await ctx.send(embed=discord.Embed(
                        description=f"✅ **{item['title']}** marqué comme **vu** ! 🎉\n*Il reste dans ta liste — ton historique est conservé.*",
                        color=0x2ecc71))
                if action == "revoir":
                    item["status"] = "À voir"
                    return await ctx.send(embed=discord.Embed(
                        description=f"🔄 **{item['title']}** est de nouveau dans les titres à voir.",
                        color=0x3498db))
                watchlist_data[uid].remove(item)
                return await ctx.send(embed=discord.Embed(
                    description=f"🗑️ **{item['title']}** retiré de ta watchlist.",
                    color=0xe74c3c))
        return await ctx.send(f"❌ **{title}** n'est pas dans ta watchlist.")

    await ctx.send("❌ Action inconnue. Tape `.watch` pour voir les options.")


